INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-international-hyper-sports-ds-japan', 'NDS', 'New International Hyper Sports DS (Japan)', '2007', 'Sports', 'Konami', '4', 'Arcade Sports', 'Multi-discipline sports competition.', 'Break world records in various athletic events.', 'Konami''s classic sports series returns for Japan.', 'New International Hyper Sports DS features 24 events including archery, swimming, and weightlifting. Compete against stylized characters or friends in this fast-paced arcade sports simulation optimized for the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-international-track-&-field-europe-enfrdeesit', 'NDS', 'New International Track & Field (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', 'Konami', '4', 'Track and Field', 'Multi-discipline sports competition.', 'Win gold medals in track and field events.', 'Modern revival of the classic Konami sports title.', 'New International Track & Field (Europe) offers a fresh take on the retro hit. Master the stylus-based controls to excel in sprints, jumps, and throws, featuring guest characters from other Konami franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-international-track-&-field-korea', 'NDS', 'New International Track & Field (Korea)', '2008', 'Sports', 'Konami', '4', 'Track and Field', 'Multi-discipline sports competition.', 'Win gold medals in track and field events.', 'Korean localized version of the Konami sports game.', 'Compete in global athletic events in Korean. This version features the same robust character customization and competitive local/online multiplayer modes that defined this modern remake of the arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-international-track-&-field-usa-enfrdeesit', 'NDS', 'New International Track & Field (USA) (En,Fr,De,Es,It)', '2008', 'Sports', 'Konami', '4', 'Track and Field', 'Multi-discipline sports competition.', 'Win gold medals in track and field events.', 'North American release of the modern sports sim.', 'Go for the gold in New International Track & Field (USA). Featuring over 20 athletic events and a vibrant comic-book art style, it’s a high-energy competition that tests your speed and precision with the stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-mario-kart-ds', 'NDS', 'New Mario Kart DS', '2006', 'Racing', 'Nintendo', '4', 'Arcade Kart Racing', 'Kart racing hack.', 'Win races in new, fan-made custom tracks.', 'Fan-made modification of Mario Kart DS.', 'New Mario Kart DS is a popular romhack that replaces standard tracks with custom-built courses. Experience fresh challenges and redesigned layouts while maintaining the tight gameplay mechanics of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-rainbow-islands-japan', 'NDS', 'New Rainbow Islands (Japan)', '2009', 'Platform', 'Natsume', '1', 'Classic Platformer', 'Vertical platforming adventure.', 'Climb to the top of the towers to rescue your friends.', 'Remake of the classic arcade platformer for Japan.', 'New Rainbow Islands features the iconic bubble-shooting mechanics. Trap enemies in rainbows and explore vibrant, vertical levels with updated graphics and touch-screen features while climbing toward the goal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-shikakui-atama-o-maruku-suru-ds---kanzen-seiha-ketteiban-japan', 'NDS', 'New Shikakui Atama o Maruku Suru. DS - Kanzen Seiha Ketteiban (Japan)', '2007', 'Puzzle', 'Success', '1', 'Brain Training', 'Brain training and educational puzzles.', 'Sharpen your mind with varied logic and math puzzles.', '"Round your square head" logic trainer for Japan.', 'This Kanzen Seiha Ketteiban (Determined Victory Edition) offers a massive collection of brain teasers. Solve logic, math, and language puzzles designed to improve cognitive flexibility for students and adults alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-advance-+-take-2-luigi', 'NDS', 'New Super Mario Advance + Take 2 (Luigi)', '2001', 'Platform', 'Nintendo', '1', 'Classic Platformer', '2D platforming (Romhack).', 'Play through New Super Mario Bros. as Luigi.', 'Fan-made "Take 2" modification featuring Luigi.', 'New Super Mario Advance + Take 2 (Luigi) is a creative hack of NSMB DS. It features redesigned levels tailored for Luigi’s unique physics, offering a fresh experience for veteran Mario fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-advance-+-take-2-mario', 'NDS', 'New Super Mario Advance + Take 2 (Mario)', '2001', 'Platform', 'Nintendo', '1', 'Classic Platformer', '2D platforming (Romhack).', 'Play through New Super Mario Bros. as Mario.', 'Fan-made "Take 2" modification featuring Mario.', 'This version of the "Take 2" hack focuses on Mario. It provides new level layouts, hidden secrets, and a higher difficulty curve than the retail game, breathing new life into the classic 2006 platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-advance-+-take-2-toad', 'NDS', 'New Super Mario Advance + Take 2 (Toad)', '2001', 'Platform', 'Nintendo', '1', 'Classic Platformer', '2D platforming (Romhack).', 'Play through New Super Mario Bros. as Toad.', 'Fan-made "Take 2" modification featuring Toad.', 'Play as Toad in this unique character-swap hack. Experience the redesigned stages of the "Take 2" series with Toad''s sprites and modified physics, creating a fun alternative to the traditional Mario gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-advance-2', 'NDS', 'New Super Mario Advance 2', '2002', 'Platform', 'Nintendo', '1', 'Classic Platformer', '2D platforming (Romhack).', 'Complete new levels in this fan expansion.', 'Unofficial "Advance" style sequel to NSMB DS.', 'New Super Mario Advance 2 (Hack) is a fan-created project that aims to deliver an "Advance" series feel. It features completely new level designs and mechanical tweaks for players looking for more content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-bros-5:-clone-tag-team', 'NDS', 'New Super Mario Bros. 5: Clone Tag Team', '2010', 'Platform', 'Fan Made', '1', 'Platform Adventure', '2D platforming (Romhack).', 'Stop Bowser in this massive fan-made project.', 'The first entry in the Clone Tag Team hack series.', 'New Super Mario Bros. 5: Clone Tag Team is a famous romhack known for high-quality level design. It introduces a "clone" mechanic where players must navigate two characters at once to solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-bros-5:-clone-tag-team-2', 'NDS', 'New Super Mario Bros. 5: Clone Tag Team 2', '2011', 'Platform', 'Fan Made', '1', 'Platform Adventure', '2D platforming (Romhack).', 'Stop Bowser in this massive fan-made project.', 'The acclaimed sequel to the Clone Tag Team hack.', 'Clone Tag Team 2 is widely considered one of the best NSMB DS hacks. It features custom assets, professional-grade level design, and a brand-new world map that rivals the quality of official Nintendo releases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-bros-5:-clone-tag-team-2-old-music', 'NDS', 'New Super Mario Bros. 5: Clone Tag Team 2 (Old Music)', '2011', 'Platform', 'Fan Made', '1', 'Platform Adventure', '2D platforming (Romhack).', 'Stop Bowser in this massive fan-made project.', 'Version of Clone Tag Team 2 with classic music.', 'This specific version of Clone Tag Team 2 replaces the custom soundtrack with "Old Music" from previous Mario titles, catering to fans who prefer a more nostalgic auditory experience while playing the hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-bros-adventure-exploratory', 'NDS', 'New Super Mario Bros. Adventure (Exploratory)', '2012', 'Platform', 'Fan Made', '1', 'Exploration Platformer', '2D platforming (Romhack).', 'Explore non-linear levels and find secrets.', 'Exploratory-focused romhack of NSMB DS.', 'New Super Mario Bros. Adventure (Exploratory) prioritizes hidden paths and item collection. The levels are designed to be played multiple times to uncover every secret, leaning more into the "metroidvania" style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-bros-adventure-normal', 'NDS', 'New Super Mario Bros. Adventure (Normal)', '2012', 'Platform', 'Fan Made', '1', 'Platform Adventure', '2D platforming (Romhack).', 'Reach the flagpole in challenging new levels.', 'Normal-progression version of the Adventure hack.', 'This "Normal" version of the Adventure hack follows a more traditional linear progression. It features all-new stages that focus on tight platforming and classic Mario challenges without the emphasis on back-tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-super-mario-bros-origins', 'NDS', 'New Super Mario Bros. Origins', '2013', 'Platform', 'Fan Made', '1', 'Classic Platformer', '2D platforming (Romhack).', 'Experience the "Origins" of Mario''s DS journey.', 'Nostalgic romhack with classic level themes.', 'New Super Mario Bros. Origins is a fan-made project that blends the mechanics of the DS game with the level themes and aesthetics of the NES and SNES eras, creating a "best of both worlds" experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-touch-party-game-europe', 'NDS', 'New Touch Party Game (Europe)', '2009', 'Party', '505 Games', '4', 'Party Minigames', 'Mini-game and party collection.', 'Win various touch-based mini-games against rivals.', 'European party game collection for the NDS.', 'New Touch Party Game offers a variety of pick-up-and-play challenges. Use the stylus for everything from card games to quick-reflex action mini-games, perfect for short play sessions and casual gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-unou-kids-ds-japan', 'NDS', 'New Unou Kids DS (Japan)', '2008', 'Educational', 'Namco', '1', 'Kids Brain Training', 'Educational brain training for kids.', 'Improve cognitive skills with fun, visual exercises.', 'Early childhood brain training tool for Japan.', 'New Unou Kids DS (New Right Brain Kids) focuses on visual processing and memory. It features colorful, interactive exercises designed to help young children develop their "right-brain" potential through play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-york-times-crosswords-the-europe', 'NDS', 'New York Times Crosswords, The (Europe)', '2007', 'Puzzle', 'Majesco', '1', 'Crossword Puzzle', 'Digital crossword puzzles.', 'Solve daily puzzles from the famous newspaper.', 'The premier crossword experience for the NDS.', 'The New York Times Crosswords (Europe) features over 1,000 puzzles from the NYT archives. Use the touch screen to write letters directly into the grid, with multiple difficulty levels and a helpful hint system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-york-times-crosswords-the-usa', 'NDS', 'New York Times Crosswords, The (USA)', '2007', 'Puzzle', 'Majesco', '1', 'Crossword Puzzle', 'Digital crossword puzzles.', 'Solve daily puzzles from the famous newspaper.', 'North American release of the NYT crosswords.', 'Carry the world''s most famous crosswords in your pocket with The New York Times Crosswords (USA). This version includes the full history of Sunday puzzles and a clean, intuitive interface for word game fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-zealand-story-ds-japan', 'NDS', 'New Zealand Story DS (Japan)', '2007', 'Platform', 'Taito', '1', 'Classic Platformer', '2D platformer and shooting.', 'Rescue your kiwi friends from the zoo.', 'Japanese version of the New Zealand Story remake.', 'Control Tiki the Kiwi in New Zealand Story DS. This version updates the classic arcade game with a dual-screen map, new touch-screen mini-games, and revamped graphics while keeping the challenging 2D gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-zealand-story-revolution-europe-enfrdeesit', 'NDS', 'New Zealand Story Revolution (Europe) (En,Fr,De,Es,It)', '2007', 'Platform', 'Taito', '1', 'Platform Adventure', '2D platformer and shooting.', 'Rescue your kiwi friends from the zoo.', 'European update of the Taito arcade classic.', 'New Zealand Story Revolution (Europe) features the "Revolution" gameplay enhancements. Use the stylus to aim your bow and solve environmental puzzles in this charming and difficult side-scrolling adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-zealand-story-revolution-usa-enfres', 'NDS', 'New Zealand Story Revolution (USA) (En,Fr,Es)', '2007', 'Platform', 'Taito', '1', 'Platform Adventure', '2D platformer and shooting.', 'Rescue your kiwi friends from the zoo.', 'North American release of the Kiwi adventure.', 'Tiki is back in New Zealand Story Revolution (USA). Fight through diverse worlds from the zoo to the ocean, utilizing various power-ups and weapons to save your friends in this colorful arcade revival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ni-hao-kai-lan---new-years-celebration-europe', 'NDS', 'Ni Hao, Kai-Lan - New Year''s Celebration (Europe)', '2010', 'Adventure', 'D3 Publisher', '1', 'Kids Adventure', 'Educational mini-games and puzzles.', 'Celebrate the Lunar New Year with Kai-Lan and friends.', 'Cultural and educational celebration for kids.', 'Ni Hao, Kai-Lan: New Year''s Celebration (Europe) teaches Chinese culture and language through festive activities. Kids help prepare for the big parade, decorate, and learn about teamwork in a colorful, bilingual environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ni-hao-kai-lan---new-years-celebration-usa', 'NDS', 'Ni Hao, Kai-Lan - New Year''s Celebration (USA)', '2010', 'Adventure', 'D3 Publisher', '1', 'Kids Adventure', 'Educational mini-games and puzzles.', 'Celebrate the Lunar New Year with Kai-Lan and friends.', 'North American release of the Kai-Lan celebration.', 'Join Kai-Lan for the ultimate party in Ni Hao, Kai-Lan (USA). Featuring voice acting from the show, players complete rhythmic and logic mini-games designed to build preschool skills and cultural awareness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ni-no-kuni---shikkoku-no-madoushi-japan', 'NDS', 'Ni no Kuni - Shikkoku no Madoushi (Japan)', '2010', 'RPG', 'Level-5', '1', 'Fantasy RPG', 'Turn-based JRPG with monster collecting.', 'Save your world and the parallel "Ni no Kuni" world.', 'Studio Ghibli collaborated RPG masterpiece.', 'Ni no Kuni: Shikkoku no Madoushi is a visual marvel. Featuring animation by Studio Ghibli and music by Joe Hisaishi, it utilizes a deep magic system where players draw runes on the touch screen to cast spells.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nickelodeon-dora-and-friends---fantastic-flight-usa-enfresnl', 'NDS', 'Nickelodeon Dora and Friends'' - Fantastic Flight (USA) (En,Fr,Es,Nl)', '2014', 'Adventure', 'High Voltage Software', '1', 'Kids Adventure', 'Flight-based action and learning.', 'Fly with Dora and friends to complete missions.', 'Preschool aerial adventure based on Nickelodeon.', 'Dora and Friends'' - Fantastic Flight (USA) features simple flight mechanics. Help Dora and her team navigate the skies, collect items, and solve math and logic problems tailored for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nickelodeon-team---umizoomi-usa', 'NDS', 'Nickelodeon Team - Umizoomi (USA)', '2011', 'Educational', 'Black Lantern Studios', '1', 'Kids Educational', 'Educational puzzles and math challenges.', 'Use "Mighty Math" to solve problems in Umi City.', 'Math-focused educational game for preschoolers.', 'Team Umizoomi (USA) focuses on patterns, shapes, and numbers. Join Milli, Geo, and Bot in various missions that encourage children to apply basic mathematical concepts to save the day in Umi City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nickelodeon-team-umizoomi-and-doras-fantastic-flight-usa', 'NDS', 'Nickelodeon Team Umizoomi and Dora''s Fantastic Flight (USA)', '2011', 'Educational', 'Black Lantern Studios', '1', 'Kids Educational', 'Educational double-pack adventure.', 'Complete missions with Team Umizoomi and Dora.', 'Two-in-one Nickelodeon educational collection.', 'This bundle combines Team Umizoomi and Dora''s Fantastic Flight. It offers double the educational content, focusing on early childhood math and problem-solving skills with popular Nick Jr. characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---attack-of-the-toybots-europe', 'NDS', 'Nicktoons - Attack of the Toybots (Europe)', '2007', 'Action Platformer', 'Blue Tongue Entertainment', '2', 'Cartoon Action', '2D side-scrolling action platformer.', 'Stop Professor Calamitous and his army of Toybots.', 'Crossover action featuring various Nicktoons heroes.', 'Nicktoons: Attack of the Toybots (Europe) lets you play as SpongeBob, Danny Phantom, and more. Use a giant mechanical suit and unique hero abilities to fight through toy-themed levels and rescue captured friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---attack-of-the-toybots-europe-enfr', 'NDS', 'Nicktoons - Attack of the Toybots (Europe) (En,Fr)', '2007', 'Action Platformer', 'Blue Tongue Entertainment', '2', 'Cartoon Action', '2D side-scrolling action platformer.', 'Stop Professor Calamitous and his army of Toybots.', 'Multi-language European release of Toybots.', 'This English/French edition of Attack of the Toybots features the same high-energy platforming. Switch between characters to utilize their specific powers and collect parts to upgrade your Toybot mech.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---attack-of-the-toybots-europe-esit', 'NDS', 'Nicktoons - Attack of the Toybots (Europe) (Es,It)', '2007', 'Action Platformer', 'Blue Tongue Entertainment', '2', 'Cartoon Action', '2D side-scrolling action platformer.', 'Stop Professor Calamitous and his army of Toybots.', 'Spanish/Italian edition of the Nicktoons action game.', 'Localized for Southern Europe, this version of Toybots brings the battle against the toy army to Spanish and Italian fans. Master the mech-suit combat and defeat robotic versions of famous cartoon stars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---attack-of-the-toybots-usa', 'NDS', 'Nicktoons - Attack of the Toybots (USA)', '2007', 'Action Platformer', 'Blue Tongue Entertainment', '2', 'Cartoon Action', '2D side-scrolling action platformer.', 'Stop Professor Calamitous and his army of Toybots.', 'North American release of Attack of the Toybots.', 'Join the Nicktoons alliance in Attack of the Toybots (USA). Explore detailed levels based on popular shows, engage in boss battles, and unlock secret characters in this definitive crossover platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---battle-for-volcano-island-usa', 'NDS', 'Nicktoons - Battle for Volcano Island (USA)', '2006', 'Action Platformer', 'Blue Tongue Entertainment', '2', 'Cartoon Action', '3D action-adventure and combat.', 'Defeat the Mawgu and save Volcano Island.', 'Island-themed Nicktoons crossover adventure.', 'Nicktoons: Battle for Volcano Island (USA) brings SpongeBob, Danny Phantom, and Timmy Turner together. Fight through jungle environments, solve puzzles, and stop an ancient evil in this action-packed quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons-mlb-usa', 'NDS', 'Nicktoons MLB (USA)', '2008', 'Sports', 'GameMill Entertainment', '2', 'Arcade Sports', 'Arcade baseball simulation.', 'Win the World Series with Nicktoons and MLB stars.', 'Unique mash-up of cartoons and pro baseball.', 'Nicktoons MLB (USA) features real MLB players alongside Nicktoons characters like Zim and Dudley Puppy. Play in wacky stadiums with over-the-top power-ups in this accessible and fun sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons-unite!-usa', 'NDS', 'Nicktoons Unite! (USA)', '2005', 'Action Platformer', 'Namco', '2', 'Crossover Action', '2D side-scrolling action crossover.', 'Stop the syndicate of villains from taking over.', 'The original Nicktoons crossover team-up.', 'Nicktoons Unite! (USA) features the first grand alliance of SpongeBob, Jimmy Neutron, Danny Phantom, and Timmy Turner. Work together to thwart their combined arch-enemies in this classic cooperative platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicola-kanshuu---model-oshare-audition-japan', 'NDS', 'Nicola Kanshuu - Model Oshare Audition (Japan)', '2006', 'Simulation', 'Spike', '1', 'Fashion Simulation', 'Fashion simulation and career management.', 'Become a top model through auditions and styling.', 'Fashion and modeling simulator for Japan.', 'Nicola Kanshuu: Model Oshare Audition tasks you with managing a model''s career. Choose outfits, master the runway, and participate in photo shoots to become a star in the Japanese fashion magazine world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('night-at-the-museum---battle-of-the-smithsonian---the-video-game-usa', 'NDS', 'Night at the Museum - Battle of the Smithsonian - The Video Game (USA)', '2009', 'Action Adventure', 'Amaze Entertainment', '1', 'Movie Action', '3D action-adventure and puzzle solving.', 'Protect the Smithsonian and stop the evil Pharaoh.', 'Movie-based adventure set in the world''s largest museum.', 'Night at the Museum 2 (USA) puts you in control of Larry Daley. Use your flashlight and key artifacts to interact with exhibits, solve puzzles, and defeat historical villains in this engaging tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('night-at-the-museum-2---the-video-game-europe-enfrde', 'NDS', 'Night at the Museum 2 - The Video Game (Europe) (En,Fr,De)', '2009', 'Action Adventure', 'Amaze Entertainment', '1', 'Movie Action', '3D action-adventure and puzzle solving.', 'Protect the Smithsonian and stop the evil Pharaoh.', 'European release of the movie adventure game.', 'Experience the magic of the museum in Night at the Museum 2 (Europe). Navigate the halls of the Smithsonian, command historical figures, and stop Kahmunrah from unleashing an ancient army.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihon-curling-kyoukai-kounin---minna-no-ds-curling-japan', 'NDS', 'Nihon Curling Kyoukai Kounin - Minna no DS Curling (Japan)', '2006', 'Sports', 'Nintendo', '4', 'Curling Simulation', 'Sports simulation.', 'Master the art of curling and win tournaments.', 'Officially licensed curling simulation for Japan.', 'Minna no DS Curling brings the strategic winter sport to your handheld. Use the stylus to aim the stones and sweep the ice, featuring realistic physics and various modes including a deep career path.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihon-golfers-kentei-ds-japan', 'NDS', 'Nihon Golfer''s Kentei DS (Japan)', '2006', 'Sports', 'Nintendo', '1', 'Golf Training', 'Sports trivia and golf management.', 'Test your golf knowledge and manage your play.', 'Educational golf certification and quiz game.', 'Nihon Golfer''s Kentei DS is designed for golf enthusiasts. It includes rules of etiquette, history, and tactical quizzes to help players improve their mental game and knowledge of the sport in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihon-keizai-shinbunsha-kanshuu---shiranai-mama-dewa-son-wo-suru---mono-ya-okane-no-shikumi-ds-japan', 'NDS', 'Nihon Keizai Shinbunsha Kanshuu - Shiranai Mama dewa Son wo Suru - ''Mono ya Okane no Shikumi'' DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Economics Training', 'Educational economics and finance.', 'Learn how money and the economy work in daily life.', 'Practical finance and economics trainer for Japan.', 'Shiranai Mama dewa Son wo Suru teaches essential financial literacy. Learn about banking, taxes, and household economics through interactive lessons and simulations designed by the Nihon Keizai Shinbun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihon-pro-mahjong-kishikai-kanshuu---pro-ni-naru-mahjong-ds-japan', 'NDS', 'Nihon Pro Mahjong Kishikai Kanshuu - Pro ni Naru Mahjong DS (Japan)', '2005', 'Tabletop', 'Enterbrain', '4', 'Mahjong Simulation', 'Mahjong simulation and training.', 'Study with professionals to master the game of Mahjong.', 'High-level Mahjong trainer supervised by pros.', 'Pro ni Naru Mahjong DS is for serious players. It features tutorials from professional Mahjong players, advanced tactical drills, and a competitive mode to sharpen your skills in this classic Japanese tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihongo-bunshou-nouryoku-kentei-kyoukai-kyouryoku---tadashii-nihongo-ds-japan', 'NDS', 'Nihongo Bunshou Nouryoku Kentei Kyoukai Kyouryoku - Tadashii Nihongo DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Language Training', 'Educational Japanese language and writing.', 'Improve your Japanese writing and sentence structure.', 'Advanced Japanese language proficiency trainer.', 'Tadashii Nihongo DS focuses on correct grammar and elegant writing. It features exercises on punctuation, honorifics, and clear communication, helping users achieve professional-level Japanese skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihongo-de-asobo-ds-japan', 'NDS', 'Nihongo de Asobo DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Language Learning', 'Educational language and cultural games.', 'Play with Japanese words and traditional literature.', 'Educational game based on the popular NHK show.', 'Nihongo de Asobo DS makes learning Japanese fun. Through rhythmic games and visual puzzles, children and adults can enjoy the beauty of Japanese poetry, proverbs, and classic literature in a playful format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihongo-kentei-iinkai-kounin---nihongo-kentei-ds-japan', 'NDS', 'Nihongo Kentei Iinkai Kounin - Nihongo Kentei DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Language Certification', 'Educational Japanese language testing.', 'Prepare for the official Japanese Proficiency Test.', 'Comprehensive Japanese language certification tool.', 'Nihongo Kentei DS offers mock tests and study modules for various levels of the Japanese Proficiency exam. Track your progress in vocabulary, grammar, and Kanji to ensure success on test day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nihonshi-ds-japan', 'NDS', 'Nihonshi DS (Japan)', '2007', 'Educational', 'Nintendo', '1', 'History Training', 'Educational history simulation.', 'Master the timeline and events of Japanese history.', 'Comprehensive Japanese history study guide.', 'Nihonshi DS provides a detailed look at Japan''s past. From ancient eras to modern times, use interactive maps and timelines to learn about key figures and events, perfect for students preparing for exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nine-hours-nine-persons-nine-doors-usa', 'NDS', 'Nine Hours, Nine Persons, Nine Doors (USA)', '2010', 'Adventure', 'Chunsoft', '1', 'Visual Novel', 'Visual novel and puzzle adventure.', 'Escape a sinking ship by solving deadly puzzles.', 'The legendary first entry in the Zero Escape series.', 'Nine Hours, Nine Persons, Nine Doors (USA) is a gripping thriller. Make life-or-death choices and solve "Escape the Room" puzzles to uncover the dark secret of the Nonary Game in this cult classic narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-captains-europe-enfrdeesit', 'NDS', 'Ninja Captains (Europe) (En,Fr,De,Es,It)', '2008', 'Action Platformer', 'Green Hill Software', '2', 'Arcade Action', 'Mini-game collection and action.', 'Complete various missions to become the ultimate ninja.', 'Wacky ninja-themed mini-game collection.', 'Ninja Captains (Europe) features a group of clumsy ninjas traveling the world. Use the touch screen for a variety of stylus-based mini-games that test your speed, memory, and reflexes in a humorous setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden---dragon-sword-europe-enfrdeesit', 'NDS', 'Ninja Gaiden - Dragon Sword (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Team Ninja', '1', 'Hack and Slash', 'Side-scrolling 2D/3D action.', 'Use the "Dragon Sword" to defeat the Fiends.', 'Acclaimed action game played with the DS held vertically.', 'Ninja Gaiden: Dragon Sword (Europe) features intense stylus-based combat. Swipe and tap to perform lightning-fast combos and Ninpo spells as Ryu Hayabusa in this technical masterpiece for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden---dragon-sword-japan', 'NDS', 'Ninja Gaiden - Dragon Sword (Japan)', '2008', 'Action', 'Team Ninja', '1', 'Hack and Slash', 'Side-scrolling 2D/3D action.', 'Use the "Dragon Sword" to defeat the Fiends.', 'Japanese release of the Ryu Hayabusa adventure.', 'Experience the definitive handheld action game. Held like a book, Ninja Gaiden: Dragon Sword (Japan) offers incredible 3D visuals and a control scheme that redefined what was possible for action games on the DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden---dragon-sword-korea', 'NDS', 'Ninja Gaiden - Dragon Sword (Korea)', '2008', 'Action', 'Team Ninja', '1', 'Hack and Slash', 'Side-scrolling 2D/3D action.', 'Use the "Dragon Sword" to defeat the Fiends.', 'Korean localized version of the Ninja Gaiden hit.', 'Master the way of the ninja in Korea. Use the Dragon Sword to carve through enemies and navigate beautifully pre-rendered backgrounds, utilizing the DS''s vertical orientation for a unique perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden---dragon-sword-usa', 'NDS', 'Ninja Gaiden - Dragon Sword (USA)', '2008', 'Action', 'Team Ninja', '1', 'Hack and Slash', 'Side-scrolling 2D/3D action.', 'Use the "Dragon Sword" to defeat the Fiends.', 'North American release of Dragon Sword.', 'Unleash the power of the Hayabusa clan in Ninja Gaiden: Dragon Sword (USA). With a deep story and challenging boss fights, it’s a high-speed action experience that rewards skill and precision with the stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-reflex-europe-enfrdeesit', 'NDS', 'Ninja Reflex (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Koei', '1', 'Reflex Action', 'Mini-game collection and reflex training.', 'Train your ninja skills through high-speed trials.', 'Reflex-based mini-game collection for Europe.', 'Ninja Reflex (Europe) tests your hand-eye coordination. Complete challenges like catching flies with chopsticks or throwing shuriken at moving targets to earn your black belt in this fast-paced trainer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-reflex-usa-enfrdeesit', 'NDS', 'Ninja Reflex (USA) (En,Fr,De,Es,It)', '2007', 'Action', 'Koei', '1', 'Reflex Action', 'Mini-game collection and reflex training.', 'Train your ninja skills through high-speed trials.', 'North American release of the reflex trainer.', 'Sharpen your senses in Ninja Reflex (USA). Compete against friends in local multiplayer or aim for high scores in diverse mini-games designed to push your reaction time and focus to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninjatown-europe-enfrdeesit', 'NDS', 'Ninjatown (Europe) (En,Fr,De,Es,It)', '2008', 'Strategy', 'Action Studio', '1', 'Tower Defense', 'Tower defense and strategy.', 'Defend Ninjatown from the invading Wee Devils.', 'Acclaimed and stylish tower defense game.', 'Ninjatown (Europe) is based on the popular plush toy line. Strategically place different types of ninjas with unique abilities to stop waves of enemies in this deep, humorous, and visually striking strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninjatown-usa', 'NDS', 'Ninjatown (USA)', '2008', 'Strategy', 'Action Studio', '1', 'Tower Defense', 'Tower defense and strategy.', 'Defend Ninjatown from the invading Wee Devils.', 'North American release of the Ninjatown strategy hit.', 'Use your tactical skills to protect the town''s secret cookie recipe in Ninjatown (USA). With a great difficulty curve and charming art style, it’s one of the most highly-regarded tower defense titles on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou---gakunen-taikousen-puzzle!-no-dan-japan', 'NDS', 'Nintama Rantarou - Gakunen Taikousen Puzzle! no Dan (Japan)', '2008', 'Puzzle', 'Culture Brain', '1', 'Anime Puzzle', 'Puzzle and strategy.', 'Compete in school-wide puzzle battles to win the tournament.', 'Ninja-themed tile-matching puzzle game.', 'Nintama Rantarou: Gakunen Taikousen Puzzle! brings the beloved anime to a competitive puzzle format. Match tiles quickly to launch attacks against classmates and teachers in this vibrant, Japanese-exclusive logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintama-rantarou---nintama-no-tame-no-ninjutsu-training-japan', 'NDS', 'Nintama Rantarou - Nintama no Tame no Ninjutsu Training (Japan)', '2006', 'Educational', 'Culture Brain', '1', 'Kids Training', 'Educational and mini-games.', 'Train your ninja skills through various training exercises.', 'Ninjutsu-themed educational and reflex trainer.', 'Nintama no Tame no Ninjutsu Training features a variety of stylus-based mini-games designed to test memory, speed, and accuracy. Learn the ways of the ninja alongside Rantarou in this fun and interactive training sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-ds-browser-japan', 'NDS', 'Nintendo DS Browser (Japan)', '2006', 'Utility', 'Opera Software', '1', 'Web Browser', 'Web browsing utility.', 'Browse the internet using the DS dual screens.', 'Official Opera-based web browser for Japan.', 'The Nintendo DS Browser (Japan) allows users to surf the web via Wi-Fi. It utilizes the top screen for viewing and the bottom for navigation and text entry, requiring the included Memory Expansion Pak to function.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-ds-browser-usa-europe-enfrdeesit', 'NDS', 'Nintendo DS Browser (USA, Europe) (En,Fr,De,Es,It)', '2006', 'Utility', 'Opera Software', '1', 'Web Browser', 'Web browsing utility.', 'Browse the internet using the DS dual screens.', 'Official Opera-based web browser for the West.', 'Surf the internet on your handheld with the Nintendo DS Browser (USA/Europe). Powered by Opera, it offers a secure browsing experience, utilizing the DS touch screen for scrolling and link selection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-presents---crossword-collection-europe', 'NDS', 'Nintendo Presents - Crossword Collection (Europe)', '2008', 'Puzzle', 'Nintendo', '1', 'Crossword Collection', 'Word puzzle collection.', 'Solve hundreds of crosswords across multiple difficulties.', 'Definitive Nintendo-published crossword collection.', 'Crossword Collection (Europe) features over 380 puzzles. Ranging from Easy to Professional, it uses a clean handwriting recognition system to let you write answers directly into the grid with your stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-presents---style-boutique-europe-enfrdeesit-rev-1', 'NDS', 'Nintendo Presents - Style Boutique (Europe) (En,Fr,De,Es,It) (Rev 1)', '2008', 'Simulation', 'Syn Sophia', '1', 'Fashion Simulation', 'Fashion and boutique management.', 'Run a successful boutique and become a fashion icon.', 'Stylized fashion management simulation (Revised).', 'Nintendo Presents: Style Boutique (Europe) Rev 1 is the ultimate fashion sim. Stock your shop, coordinate outfits for picky customers, and enter fashion contests to prove your eye for style in this multi-language hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendo-touch-golf---birdie-challenge-europe-enjafrdeesit', 'NDS', 'Nintendo Touch Golf - Birdie Challenge (Europe) (En,Ja,Fr,De,Es,It)', '2009', 'Sports', 'Indies Zero', '1', 'Golf Simulation', 'Sports simulation.', 'Master the greens and win international golf tournaments.', 'Intuitive touch-screen golf simulation.', 'Nintendo Touch Golf (Europe) offers a realistic and accessible golfing experience. Use the stylus to swing your club with precision, factoring in wind and terrain across beautifully rendered 3D courses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---best-friends-usa', 'NDS', 'Nintendogs - Best Friends (USA)', '2011', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train six popular dog breeds.', 'Special edition featuring the most popular puppies.', 'Nintendogs: Best Friends (USA) is a curated version of the hit pet sim. It includes the six most popular breeds from other versions from the start, allowing you to feed, bathe, and train your puppies with the mic and stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---chihuahua-&-chingudeul-korea', 'NDS', 'Nintendogs - Chihuahua & Chingudeul (Korea)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train various puppies including Chihuahuas.', 'Korean localized version of the Chihuahua edition.', 'Experience the joy of pet ownership in Korean. Nintendogs: Chihuahua & Chingudeul allows you to interact with your puppy using voice commands and the touch screen, building a lifelong bond with your virtual pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---chihuahua-&-friends-europe-enfrdeesit', 'NDS', 'Nintendogs - Chihuahua & Friends (Europe) (En,Fr,De,Es,It)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'The classic Chihuahua-focused pet simulation.', 'Nintendogs: Chihuahua & Friends (Europe) features the Chihuahua, German Shepherd, and more. Use the microphone to teach your dog its name and tricks, and walk them to meet other puppies via "Bark Mode" wireless connection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---chihuahua-&-friends-japan', 'NDS', 'Nintendogs - Chihuahua & Friends (Japan)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'Original Japanese release of the Chihuahua sim.', 'The game that started the puppy craze. Nintendogs (Japan) utilizes the DS''s unique hardware to create a lifelike pet experience, focusing on daily care, grooming, and competitive obedience trials.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---chihuahua-&-friends-japan-rev-1', 'NDS', 'Nintendogs - Chihuahua & Friends (Japan) (Rev 1)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'Revised Japanese edition of the Chihuahua sim.', 'This Revision 1 of the Japanese original includes minor bug fixes and optimizations, ensuring the most stable puppy-raising experience for Japanese players looking for virtual companionship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---chihuahua-&-friends-usa', 'NDS', 'Nintendogs - Chihuahua & Friends (USA)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'North American release of the Chihuahua edition.', 'Nintendogs: Chihuahua & Friends (USA) offers a heartwarming experience. Groom your pup, buy toys, and enter competitions to earn money for new furniture and even more adorable dog breeds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---dachshund-&-chingudeul-korea', 'NDS', 'Nintendogs - Dachshund & Chingudeul (Korea)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train various puppies including Dachshunds.', 'Korean localized version of the Dachshund edition.', 'Join the virtual pet revolution in Korea. This version of Nintendogs focuses on the Miniature Dachshund and its friends, providing a fully localized experience for nurturing and training your digital dog.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---dachshund-&-friends-europe-enfrdeesit', 'NDS', 'Nintendogs - Dachshund & Friends (Europe) (En,Fr,De,Es,It)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'The Dachshund-focused pet simulation for Europe.', 'Nintendogs: Dachshund & Friends (Europe) features the titular breed along with the Beagle, Golden Retriever, and others. Compete in Disc Competitions and Agility Trials to show off your puppy''s training.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---dachshund-&-friends-usa', 'NDS', 'Nintendogs - Dachshund & Friends (USA)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'North American release of the Dachshund edition.', 'Nurture your favorite breed in Nintendogs: Dachshund & Friends (USA). With realistic fur textures and responsive AI, your virtual puppy reacts to your touch and voice like a real animal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---dalmatian-&-friends-europe-enfrdeesit', 'NDS', 'Nintendogs - Dalmatian & Friends (Europe) (En,Fr,De,Es,It)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train puppies including the rare Dalmatian.', 'The expanded Dalmatian edition for Europe.', 'Nintendogs: Dalmatian & Friends (Europe) adds the iconic spotted breed to the roster. Enjoy all the classic Nintendogs activities—bathing, walking, and playing—with a fresh set of starting breeds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---dalmatian-&-friends-usa', 'NDS', 'Nintendogs - Dalmatian & Friends (USA)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train puppies including the rare Dalmatian.', 'North American release of the Dalmatian edition.', 'Bring home a Dalmatian in Nintendogs (USA). This version provides a great entry point for new fans, offering a diverse selection of puppies to raise, train, and enter into high-stakes canine competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---lab-&-friends-usa', 'NDS', 'Nintendogs - Lab & Friends (USA)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'North American release of the Labrador edition.', 'Nintendogs: Lab & Friends (USA) features the Labrador Retriever, Miniature Schnauzer, and more. Use the DS stylus to pet your dog and the mic to give commands in this award-winning simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---labrador-&-chingudeul-korea', 'NDS', 'Nintendogs - Labrador & Chingudeul (Korea)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train various puppies including Labradors.', 'Korean localized version of the Labrador edition.', 'Labrador & Chingudeul brings the world-famous puppy sim to Korea. Focus on the lovable Labrador Retriever as you learn the responsibilities of pet care through interactive and rewarding gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---labrador-&-friends-europe-enfrdeesit', 'NDS', 'Nintendogs - Labrador & Friends (Europe) (En,Fr,De,Es,It)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'The Labrador-focused pet simulation for Europe.', 'Nintendogs: Labrador & Friends (Europe) offers a relaxing and charming experience. Spend your time teaching your Lab to fetch or simply enjoying a quiet walk in the park using the dual-screen interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---miniature-dachshund-&-friends-japan', 'NDS', 'Nintendogs - Miniature Dachshund & Friends (Japan)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'Japanese edition featuring Miniature Dachshunds.', 'Known as Miniature Dachshund & Friends in Japan, this version highlights one of the country''s most beloved breeds. Build a deep connection with your pet through daily interaction and voice-activated training.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---miniature-dachshund-&-friends-japan-rev-1', 'NDS', 'Nintendogs - Miniature Dachshund & Friends (Japan) (Rev 1)', '2005', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise, train, and bond with your virtual puppy.', 'Revised Japanese edition of the Dachshund sim.', 'This updated Japanese release ensures a smooth and bug-free experience for dog lovers. Focus on raising a champion puppy and unlocking secret items through the Nintendogs "Bark Mode."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---shiba-&-friends-japan', 'NDS', 'Nintendogs - Shiba & Friends (Japan)', '2006', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train puppies including the Shiba Inu.', 'Japanese edition featuring the iconic Shiba Inu.', 'Nintendogs: Shiba & Friends (Japan) celebrates the national dog of Japan. Train your Shiba to be the best in show, utilizing the DS microphone for precise command recognition and interaction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nintendogs---shiba-&-friends-japan-rev-1', 'NDS', 'Nintendogs - Shiba & Friends (Japan) (Rev 1)', '2006', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet simulation and care.', 'Raise and train puppies including the Shiba Inu.', 'Revised Japanese edition of the Shiba sim.', 'The refined version of the Shiba Inu edition for the Japanese market. It offers the same addictive pet care gameplay with technical improvements for a better virtual ownership experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nippon-futsal-league-kounin---minna-no-ds-futsal-japan', 'NDS', 'Nippon Futsal League Kounin - Minna no DS Futsal (Japan)', '2009', 'Sports', 'Nintendo', '4', 'Futsal Simulation', 'Sports simulation.', 'Manage and play in a professional Futsal league.', 'Realistic indoor soccer (futsal) simulation.', 'Minna no DS Futsal brings the speed of indoor soccer to the DS. Use the stylus or buttons to perform quick passes and flashy goals, featuring officially licensed teams and a deep tournament mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nippon-shuzan-renmei-kanshuu---itsudemo-soroban-ds-japan', 'NDS', 'Nippon Shuzan Renmei Kanshuu - Itsudemo Soroban DS (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Abacus Training', 'Educational and math.', 'Master the Japanese abacus (soroban) for mental math.', 'Traditional abacus training and calculation tool.', 'Itsudemo Soroban DS teaches the ancient art of the abacus. Use the touch screen to manipulate virtual beads, improving your mental arithmetic speed and accuracy through traditional Japanese methods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nippon-suugaku-kentei-kyoukai-kounin---suken-ds---otona-ga-tokenai!-kodomo-no-sansuu-japan', 'NDS', 'Nippon Suugaku Kentei Kyoukai Kounin - Suken DS - Otona ga Tokenai! Kodomo no Sansuu (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Math Training', 'Educational and math.', 'Solve math problems that even adults find difficult.', 'Advanced math and logic trainer for all ages.', 'Suken DS challenges your mathematical thinking. Based on the Japanese Mathematics Certification, it features problems that test logic and creative problem-solving rather than just simple calculation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-no-yabou-ds-japan', 'NDS', 'Nobunaga no Yabou DS (Japan)', '2005', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy and historical simulation.', 'Unify Japan during the Sengoku period as a warlord.', 'Deep historical strategy and conquest for Japan.', 'Nobunaga no Yabou DS (Nobunaga''s Ambition) is a port of the legendary strategy series. Manage your fief, build an army, and engage in tactical turn-based battles to conquer the warring states of Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-no-yabou-ds-2-japan', 'NDS', 'Nobunaga no Yabou DS 2 (Japan)', '2007', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Grand strategy and historical simulation.', 'Unify Japan during the Sengoku period as a warlord.', 'The expanded sequel to the DS strategy hit.', 'Nobunaga no Yabou DS 2 features improved AI, new scenarios, and refined touch-screen controls. Experience the drama of the Sengoku era with more depth and strategic options than ever before.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nodame-cantabile---tanoshii-ongaku-no-jikan-desu-japan', 'NDS', 'Nodame Cantabile - Tanoshii Ongaku no Jikan Desu (Japan)', '2007', 'Music', 'Namco', '1', 'Music Learning', 'Rhythm and music simulation.', 'Play classical music and follow the story of Nodame.', 'Musical adventure based on the hit manga/anime.', 'Nodame Cantabile: Tanoshii Ongaku no Jikan Desu makes classical music accessible. Use the stylus to conduct an orchestra and play various instruments in rhythm-based challenges that follow the series'' story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nodame-cantabile-japan', 'NDS', 'Nodame Cantabile (Japan)', '2007', 'Music', 'Namco', '1', 'Music Adventure', 'Rhythm and music simulation.', 'Experience the world of classical music and romance.', 'The original Nodame Cantabile rhythm game for Japan.', 'Immerse yourself in the life of a music student in Nodame Cantabile. Complete rhythmic tasks to progress through the story, featuring a wide selection of famous classical pieces and charming character interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('noddy-in-toyland-europe-enfr', 'NDS', 'Noddy in Toyland (Europe) (En,Fr)', '2009', 'Adventure', 'Mindscape', '1', 'Kids Adventure', 'Educational adventure and mini-games.', 'Help Noddy solve mysteries and help his friends.', 'Preschool adventure based on the classic character.', 'Noddy in Toyland (Europe) is a gentle educational game for young children. Drive Noddy’s car, solve simple puzzles, and complete mini-games that teach basic shapes, colors, and problem-solving skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nolleooseyo-dongmurui-sup-korea', 'NDS', 'Nolleooseyo Dongmurui Sup (Korea)', '2008', 'Educational', 'Game Life', '1', 'Educational', 'Social simulation and life management.', 'Live a peaceful life in a village with animal neighbors.', 'Korean version of Animal Crossing: Wild World.', 'Nolleooseyo Dongmurui Sup brings the magic of Animal Crossing to Korea. Fish, catch bugs, and decorate your home in real-time, utilizing the DS Wi-Fi Connection to visit friends'' villages in this beloved social sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nori-nori-rilakkuma---hit-song-ongakusai-japan', 'NDS', 'Nori Nori Rilakkuma - Hit Song Ongakusai (Japan)', '2009', 'Music', 'Rocket Company', '1', 'Music Rhythm', 'Rhythm and music simulation.', 'Perform hit songs with Rilakkuma and friends.', 'Cute rhythm game featuring the popular bear mascot.', 'Nori Nori Rilakkuma features catchy Japanese pop hits. Use the touch screen to tap along with the beat while Rilakkuma and his friends dance and play, offering a relaxing yet challenging musical experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('norimono-oukoku-ds---you!-unten-shichainayo!-japan', 'NDS', 'Norimono Oukoku DS - You! Unten Shichainayo! (Japan)', '2007', 'Simulation', 'Success', '1', 'Vehicle Simulation', 'Driving and vehicle simulation.', 'Drive various vehicles from trains to construction trucks.', 'Multi-vehicle driving simulator for younger players.', 'Norimono Oukoku DS lets kids take the wheel of their favorite machines. From bullet trains to fire trucks, use the stylus to operate controls and complete simple transport missions in this colorful Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nos-voisins-les-hommes-france', 'NDS', 'Nos Voisins, les Hommes (France)', '2006', 'Adventure', 'Magic Pockets', '1', 'Point-and-Click', 'Action-adventure and stealth.', 'Help RJ and the gang steal food from the humans.', 'French release of "Over the Hedge".', 'Nos Voisins, les Hommes (France) follows the plot of the DreamWorks film. Use stealth and teamwork to navigate suburban backyards, set traps, and collect snacks in this fun, localized action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nostalgeo-no-kaze-japan', 'NDS', 'Nostalgeo no Kaze (Japan)', '2009', 'Role-Playing', 'Game Arts', '1', 'JRPG', 'Turn-based JRPG with airship combat.', 'Explore a steampunk 19th-century world and find your father.', 'Epic steampunk RPG with massive airship battles.', 'Nostalgeo no Kaze (Nostalgia) is a love letter to classic JRPGs. Customize your airship, explore a fantasy version of Earth, and engage in tactical turn-based combat both on foot and in the skies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nostalgia-usa', 'NDS', 'Nostalgia (USA)', '2009', 'Role-Playing', 'Matrix Software', '1', 'JRPG', 'Turn-based JRPG with airship combat.', 'Explore a steampunk 19th-century world and find your father.', 'North American release of the steampunk epic.', 'Experience the grand adventure of Nostalgia (USA). Travel from London to Cairo in your customizable airship, battling monsters and uncovering ancient mysteries in this visually stunning and deep role-playing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nounai-aesthe-iq-suppli-ds-japan', 'NDS', 'Nounai Aesthe IQ Suppli DS (Japan)', '2006', 'Educational', 'Spike', '1', 'Brain Training', 'Brain training and IQ puzzles.', 'Solve "IQ Suppli" brain teasers to improve mental agility.', 'Popular Japanese TV show-based puzzle collection.', 'Nounai Aesthe IQ Suppli DS offers a variety of logic and lateral thinking puzzles. Based on the hit Fuji TV show, it aims to "massage" your brain with fun, creative challenges for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nounai-aesthe-iq-suppli-ds-2---sukkiri-king-ketteisen-japan', 'NDS', 'Nounai Aesthe IQ Suppli DS 2 - Sukkiri King Ketteisen (Japan)', '2007', 'Educational', 'Spike', '1', 'Brain Training', 'Brain training and IQ puzzles.', 'Solve puzzles to become the "Sukkiri King".', 'Expanded sequel to the IQ brain trainer.', 'This sequel features more puzzle types and a competitive mode. IQ Suppli DS 2 continues the brain-massaging formula with hundreds of new challenges designed to test your wit and speed under pressure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nounai-kakusei-honeycomb-beat-japan', 'NDS', 'Nounai Kakusei Honeycomb Beat (Japan)', '2007', 'Educational', 'Spike', '1', 'Brain Training', 'Rhythm and puzzle hybrid.', 'Clear hexagonal tiles by matching them to the beat.', 'Unique rhythm-based logic puzzle game.', 'Honeycomb Beat combines musical timing with spatial reasoning. Flip tiles on a hexagonal grid to match patterns in sync with the soundtrack, featuring multiple modes and over 200 challenging levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nounenrei---nou-stress-kei-atama-scan-japan', 'NDS', 'Nounenrei - Nou Stress Kei Atama Scan (Japan)', '2008', 'Educational', 'Spike', '1', 'Brain Training', 'Brain training and stress assessment.', 'Scan your "brain age" and reduce mental stress.', 'Stress-focused brain training and analysis tool.', 'Nounenrei: Nou Stress Kei Atama Scan aims to measure your cognitive health while providing relaxing exercises. It combines standard logic puzzles with relaxation techniques to help balance your mental state.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nova-usagi-no-game-de-ryuugaku!-ds-japan', 'NDS', 'Nova Usagi no Game de Ryuugaku! DS (Japan)', '2006', 'Educational', 'Culture Brain', '1', 'Language Learning', 'Language learning mini-games.', 'Learn English with the Nova Usagi mascot.', 'Fun English language trainer for Japanese learners.', 'Nova Usagi no Game de Ryuugaku! makes English learning a game. Use the stylus to complete vocabulary and grammar mini-games led by the pink rabbit mascot of the famous Nova language school.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nrl-mascot-mania-australia', 'NDS', 'NRL Mascot Mania (Australia)', '2008', 'Sports', 'Sidhe Interactive', '4', 'Sports Arcade', 'Sports simulation and card collection.', 'Win the NRL Premiership with your favorite team mascot.', 'Australian rugby league game with a kid-friendly twist.', 'NRL Mascot Mania features all 16 official NRL mascots. Engage in fast-paced mini-games, collect over 100 cards, and battle through the season to win the grand final in this unique Australian sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nursery-mania-usa', 'NDS', 'Nursery Mania (USA)', '2009', 'Simulation', 'Game Life', '1', 'Life Simulation', 'Time management and simulation.', 'Care for multiple babies and keep the nursery running.', 'Frantic daycare management simulation.', 'Nursery Mania (USA) tasks you with the ultimate multitasking challenge. Feed, clean, and entertain a growing group of infants while managing your resources to upgrade your daycare facility.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---chiri-ds-japan', 'NDS', 'Obunsha Deru-jun - Chiri DS (Japan)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational geography study.', 'Master Japanese geography for middle school exams.', 'Targeted geography study guide for Japan.', 'Obunsha Deru-jun: Chiri DS focuses on the most frequent topics in entrance exams. Map out regions, learn local industries, and take mock tests to ensure mastery of Japanese and world geography.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---chiri-ds-japan-rev-1', 'NDS', 'Obunsha Deru-jun - Chiri DS (Japan) (Rev 1)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational geography study.', 'Master Japanese geography for middle school exams.', 'Revised edition of the geography trainer.', 'The Rev 1 edition of Chiri DS includes updated data and minor bug fixes, providing the most accurate study material for students preparing for competitive Japanese geography exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---kokugo-ds-japan', 'NDS', 'Obunsha Deru-jun - Kokugo DS (Japan)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational language study.', 'Improve Japanese grammar, kanji, and vocabulary.', 'Targeted Japanese language exam prep tool.', 'Obunsha Deru-jun: Kokugo DS is a comprehensive language arts trainer. It covers essential reading and writing skills, focusing on the high-yield questions most likely to appear in school entrance tests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---koumin-ds-japan', 'NDS', 'Obunsha Deru-jun - Koumin DS (Japan)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational social studies.', 'Learn about Japanese government and citizenship.', 'Targeted civics and social studies exam prep.', 'Obunsha Deru-jun: Koumin DS teaches the fundamentals of the Japanese political and economic systems. It’s an essential tool for students to master the "Civics" portion of their social studies exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---rekishi-ds-japan', 'NDS', 'Obunsha Deru-jun - Rekishi DS (Japan)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational history study.', 'Master the timeline of Japanese history.', 'Targeted history exam preparation for Japan.', 'Obunsha Deru-jun: Rekishi DS covers everything from ancient eras to modern history. Use interactive timelines and quizzes to memorize key figures and events crucial for academic success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---rika-ds-japan', 'NDS', 'Obunsha Deru-jun - Rika DS (Japan)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational science study.', 'Master biology, physics, and chemistry basics.', 'Targeted science exam prep for Japanese students.', 'Obunsha Deru-jun: Rika DS breaks down complex scientific concepts into digestible lessons. Focus on the most common exam questions across all branches of general science with interactive drills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('obunsha-deru-jun---sansuu-ds-japan', 'NDS', 'Obunsha Deru-jun - Sansuu DS (Japan)', '2006', 'Educational', 'Obunsha', '1', 'Study', 'Educational math study.', 'Master arithmetic and problem-solving for exams.', 'Targeted math exam prep for primary students.', 'Obunsha Deru-jun: Sansuu DS focuses on the core mathematical skills needed for junior high entrance exams. It provides step-by-step solutions and practice problems for geometry, fractions, and more.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-daibouken---honwaka-yumemiru-sekai-ryokou-japan', 'NDS', 'Ochaken no Daibouken - Honwaka Yumemiru Sekai Ryokou (Japan)', '2006', 'Adventure', 'MTO', '1', 'Casual Adventure', 'Action-adventure and mini-games.', 'Travel the world with the Tea Dogs and find happiness.', 'Adorable world-traveling adventure for Japan.', 'Ochaken no Daibouken features the famous Ochaken (Tea Dogs). Visit different countries, solve environmental puzzles, and play mini-games to collect items and decorate your room in this relaxing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-daibouken-2---yume-ippai-no-omocha-bako-japan', 'NDS', 'Ochaken no Daibouken 2 - Yume Ippai no Omocha Bako (Japan)', '2007', 'Adventure', 'MTO', '1', 'Casual Adventure', 'Action-adventure and mini-games.', 'Explore a toy box world with the Ochaken.', 'Whimsical toy-themed sequel to the Ochaken series.', 'Ochaken no Daibouken 2 takes the cute dogs into a fantasy world filled with toys. Use the stylus to navigate platforming segments and play with a variety of interactive gadgets in this charming sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-ds-japan', 'NDS', 'Ochaken no Heya DS (Japan)', '2006', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Social simulation and decoration.', 'Create the perfect room for your Tea Dogs.', 'Relaxation and interior design with Ochaken.', 'Ochaken no Heya DS allows you to raise and play with the adorable Tea Dogs. Decorate your room, collect cute furniture, and participate in mini-games to unlock new breeds and items in this peaceful sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-ds-2-japan', 'NDS', 'Ochaken no Heya DS 2 (Japan)', '2007', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Social simulation and decoration.', 'Expand your house and play with more Tea Dogs.', 'The expanded sequel to the room decoration sim.', 'Ochaken no Heya DS 2 introduces more dog breeds and new furniture sets. Interact with your pets using the touch screen and microphone, and enjoy new seasonal events in your virtual Ochaken house.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-ds-2-japan-rev-1', 'NDS', 'Ochaken no Heya DS 2 (Japan) (Rev 1)', '2007', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Social simulation and decoration.', 'Expand your house and play with more Tea Dogs.', 'Revised version of the second Ochaken room sim.', 'This Rev 1 edition of Ochaken no Heya 2 ensures a smooth experience for fans. It features technical optimizations while maintaining the addictive room-building and pet-care gameplay that defines the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-ds-3-japan', 'NDS', 'Ochaken no Heya DS 3 (Japan)', '2008', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Social simulation and decoration.', 'Manage a large garden and house for your Ochaken.', 'Third entry in the Ochaken room series.', 'Ochaken no Heya DS 3 focuses on outdoor activities and gardening. Plant flowers and create a beautiful park for your Tea Dogs to play in, alongside the classic room decoration and care mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-ds-3-japan-rev-1', 'NDS', 'Ochaken no Heya DS 3 (Japan) (Rev 1)', '2008', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Social simulation and decoration.', 'Manage a large garden and house for your Ochaken.', 'Revised version of the third Ochaken room sim.', 'The Rev 1 edition of the third installment provides minor updates to the gardening and decoration systems. It remains a fan-favorite for those who love the "healing" atmosphere of the Ochaken world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ochaken-no-heya-ds-4-japan', 'NDS', 'Ochaken no Heya DS 4 (Japan)', '2009', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Social simulation and decoration.', 'Complete your Ochaken collection and master the mini-games.', 'The fourth and most feature-rich Ochaken room sim.', 'Ochaken no Heya DS 4 is the definitive room-building experience. With the largest selection of items, dogs, and mini-games in the series, it offers endless hours of cute and cozy customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oden-kun---tanoshii-oden-mura-japan', 'NDS', 'Oden-kun - Tanoshii Oden Mura (Japan)', '2006', 'Adventure', 'Eighting', '1', 'Anime Adventure', 'Mini-game collection and social adventure.', 'Help Oden-kun solve problems in the Oden Village.', 'Quirky mini-game collection based on the surreal anime.', 'Oden-kun: Tanoshii Oden Mura features the characters from Lily Franky''s famous book and anime. Complete strange and funny mini-games to help the village residents in this unique Japanese experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('odoru-daisousa-sen---the-game---sensuikan-ni-sennyuu-seyo!-japan', 'NDS', 'Odoru Daisousa-sen - The Game - Sensuikan ni Sennyuu Seyo! (Japan)', '2007', 'Adventure', 'Banpresto', '1', 'Detective Adventure', 'Adventure and mystery.', 'Infiltrate a submarine and solve the case.', 'Detective adventure based on the hit Japanese film.', 'Odoru Daisousa-sen (Bayside Shakedown) brings the famous police drama to the DS. Use logic and investigation skills to navigate a high-stakes mission on a submarine, featuring iconic characters from the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oekaki-puzzle-battle!---yuusha-ou-gaogaigar-hen-japan', 'NDS', 'Oekaki Puzzle Battle! - Yuusha Ou GaoGaiGar Hen (Japan)', '2006', 'Puzzle', 'Bandai Namco', '1', 'Drawing Puzzle', 'Picture puzzle and strategy.', 'Solve Nonogram puzzles to battle GaoGaiGar enemies.', 'Nonogram (Picross) puzzle game with a mecha theme.', 'Oekaki Puzzle Battle! features the legendary King of Braves GaoGaiGar. Solve logic-based picture puzzles to launch attacks against mecha rivals, blending brain-teasing gameplay with classic anime action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ogwangui-darin-ds-korea', 'NDS', 'Ogwangui Darin DS (Korea)', '2007', 'Action', 'Sonokong', '1', 'Action Arcade', 'Card game and gambling simulation.', 'Master the game of Go-Stop and become a pro.', 'Korean Hwatu (Go-Stop) card game simulation.', 'Ogwangui Darin DS features the traditional Korean card game. Compete against various AI opponents in high-stakes matches, featuring realistic rules and a campaign mode to become the master of Go-Stop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oheya-o-kazarou---koinu-no-heya-japan', 'NDS', 'Oheya o Kazarou - Koinu no Heya (Japan)', '2006', 'Simulation', 'MTO', '1', 'Virtual Pet', 'Pet care and interior design.', 'Decorate rooms and raise adorable puppies.', 'Puppy-themed room decoration and care sim.', 'Oheya o Kazarou: Koinu no Heya focuses on the "cozy" side of pet ownership. Choose from various dog breeds, collect cute furniture, and design the perfect living space for your virtual puppy to play in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ohimesama-debut-japan', 'NDS', 'Ohimesama Debut (Japan)', '2008', 'Adventure', 'Starfish-SD', '1', 'Visual Novel', 'Rhythmic dancing and social sim.', 'Master ballroom dancing to find your prince.', 'Princess-themed rhythm and romance game.', 'Ohimesama Debut (Princess Debut) follows a girl sent to a magical kingdom. Use the stylus to trace dance patterns in time with the music while building relationships with charming princes in this unique otome-rhythm hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oide-yo-doubutsu-no-mori-japan', 'NDS', 'Oide yo Doubutsu no Mori (Japan)', '2005', 'Simulation', 'Nintendo', '4', 'Life Simulation', 'Social simulation and life management.', 'Build a peaceful life and make friends with animals.', 'Japanese original version of Animal Crossing: Wild World.', 'Oide yo Doubutsu no Mori is the seminal DS social sim. Fish, catch bugs, and interact with neighbors in real-time. This title defined the "slow life" genre on the handheld with its innovative 24-hour clock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oide-yo-doubutsu-no-mori-japan-rev-1', 'NDS', 'Oide yo Doubutsu no Mori (Japan) (Rev 1)', '2005', 'Simulation', 'Nintendo', '4', 'Life Simulation', 'Social simulation and life management.', 'Build a peaceful life and make friends with animals.', 'Revised Japanese edition of Animal Crossing.', 'This Revision 1 of the Japanese Animal Crossing includes technical fixes and improved stability for local wireless and Wi-Fi play, ensuring a smooth experience in your virtual village.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oishiku-kiwameru-shokutsuu-ds---otona-no-shuumatsu-henshuubu-gensen-no-osusume-omise-jouhou-iri-japan', 'NDS', 'Oishiku Kiwameru Shokutsuu DS - Otona no Shuumatsu Henshuubu Gensen no Osusume Omise Jouhou Iri (Japan)', '2008', 'Educational', 'Mainichi Communications', '1', 'Food Guide', 'Gourmet guide and database.', 'Find the best restaurants in Japan based on expert reviews.', 'Gourmet restaurant guide for food enthusiasts.', 'Oishiku Kiwameru Shokutsuu DS is a digital encyclopedia for foodies. It features curated recommendations from "Otona no Shuumatsu" editors, covering top-tier dining spots across Japan with photos and maps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oishinbo---ds-recipe-shuu-japan', 'NDS', 'Oishinbo - DS Recipe Shuu (Japan)', '2007', 'Educational', 'Access Games', '1', 'Cooking', 'Cooking simulation and recipes.', 'Learn to cook famous dishes from the Oishinbo manga.', 'Culinary guide based on the legendary gourmet manga.', 'Oishinbo: DS Recipe Shuu features over 100 recipes. Follow step-by-step instructions from the series'' protagonists to master traditional Japanese cuisine and gourmet secrets in your own kitchen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ojaru-maru-ds---ojaru-to-okeiko-aiueo-japan', 'NDS', 'Ojaru-Maru DS - Ojaru to Okeiko Aiueo (Japan)', '2006', 'Educational', 'Taito', '1', 'Children Learning', 'Educational mini-games.', 'Learn the Hiragana alphabet with Ojaru-Maru.', 'Preschool educational tool based on the anime.', 'Ojaru-Maru DS makes learning the basics of Japanese fun. Use the touch screen to trace letters and complete simple logic puzzles guided by the tiny prince and his friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ok!---first-for-celebrity-news---puzzle-stars-europe', 'NDS', 'OK! - First for Celebrity News - Puzzle Stars (Europe)', '2008', 'Puzzle', 'Ideaworks Game Studio', '1', 'Word Puzzle', 'Puzzle and celebrity trivia.', 'Solve puzzles to unlock celebrity gossip and news.', 'Celebrity-themed puzzle game based on OK! Magazine.', 'OK! Puzzle Stars features word searches, crosswords, and logic puzzles. As you clear levels, you unlock high-res photos and "breaking news" about world-famous stars in this casual European title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('okada-toshio-no-itsumademo-debu-to-omounayo---ds-de-recording-diet-japan', 'NDS', 'Okada Toshio no Itsumademo Debu to Omounayo - DS de Recording Diet (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Fitness', 'Health and diet management.', 'Track your daily food intake to lose weight.', 'Recording-based diet coach for health tracking.', 'Based on the famous "Recording Diet" method, this tool helps you log everything you eat. It provides calorie charts and motivational tips to help users maintain a healthy lifestyle on their DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('okaeri!-chibi-robo!---happy-rich-oosouji!-japan', 'NDS', 'Okaeri! Chibi-Robo! - Happy Rich Oosouji! (Japan)', '2009', 'Adventure', 'skip Ltd.', '1', 'Action Adventure', 'Action-adventure and cleaning.', 'Clean the house and collect "Happy Points" to get rich.', 'The charming Chibi-Robo''s return to the DS.', 'Okaeri! Chibi-Robo! tasks the tiny robot with cleaning a house using a vacuum and scrubbing brush. Manage your battery life, help the family with their problems, and earn money to buy upgrades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oktoberfest---the-official-game-europe-enfrdeesit', 'NDS', 'Oktoberfest - The Official Game (Europe) (En,Fr,De,Es,It)', '2010', 'Simulation', 'Independent Arts', '4', 'Party Game', 'Mini-game collection.', 'Participate in the world''s most famous beer festival.', 'Oktoberfest-themed arcade and party games.', 'Oktoberfest: The Official Game (Europe) features traditional festival challenges like beer-mug sliding, bratwurst cooking, and rhythmic folk dancing in a cheerful, multi-language carnival atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('omg-26---our-mini-games-usa', 'NDS', 'OMG 26 - Our Mini Games (USA)', '2011', 'Mini-Games', 'Frima Studio', '4', 'Party Mini-Games', 'Mini-game collection.', 'Play through 26 different casual challenges.', 'Diverse collection of simple arcade mini-games.', 'OMG 26 - Our Mini Games (USA) offers a variety of quick-play tasks. From racing to logic puzzles, this collection is designed for short bursts of gameplay using the DS touch-screen controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---gear-spirit-japan', 'NDS', 'One Piece - Gear Spirit (Japan)', '2008', 'Fighting', 'Ganbarion', '2', 'Anime Fighting', '2D fighting game.', 'Battle rival pirates using "Spirit" cards.', 'High-energy One Piece fighting game for Japan.', 'One Piece: Gear Spirit features fast 1v1 combat. Use the bottom screen to activate "Spirit Cards" that trigger special moves or summon allies from the Straw Hat crew in this colorful brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---gear-spirit-korea', 'NDS', 'One Piece - Gear Spirit (Korea)', '2008', 'Fighting', 'Ganbarion', '2', 'Anime Fighting', '2D fighting game.', 'Battle rival pirates using "Spirit" cards.', 'Korean localized version of Gear Spirit.', 'Fight for the title of Pirate King in Korean. This version brings the intense card-based combat and iconic anime attacks to Korean fans, featuring a robust cast of heroes and villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---gigant-battle!-europe', 'NDS', 'One Piece - Gigant Battle! (Europe)', '2010', 'Fighting', 'Ganbarion', '4', 'Anime Fighting', '2D arena fighting and strategy.', 'Form a crew and conquer the "Grand Line."', 'The massive crossover fighter for European fans.', 'One Piece: Gigant Battle! (Europe) allows you to build a team of your favorite characters. Battle across interactive stages and use the "Gigant" system to trigger massive ultimate attacks in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---gigant-battle!-france', 'NDS', 'One Piece - Gigant Battle! (France)', '2010', 'Fighting', 'Ganbarion', '4', 'Anime Fighting', '2D arena fighting and strategy.', 'Form a crew and conquer the "Grand Line."', 'French localized version of Gigant Battle.', 'Join Luffy in this French edition of the hit fighter. Featuring localized text and the full roster of Straw Hat pirates, it’s a must-have for the large One Piece fanbase in France.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---gigant-battle!-germany', 'NDS', 'One Piece - Gigant Battle! (Germany)', '2010', 'Fighting', 'Ganbarion', '4', 'Anime Fighting', '2D arena fighting and strategy.', 'Form a crew and conquer the "Grand Line."', 'German localized version of Gigant Battle.', 'Experience the explosive combat of Gigant Battle in German. Master the support system and unlock hidden characters by completing the deep "Pirate Grand Prix" world-map mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece---gigant-battle!-japan', 'NDS', 'One Piece - Gigant Battle! (Japan)', '2010', 'Fighting', 'Ganbarion', '4', 'Anime Fighting', '2D arena fighting and strategy.', 'Form a crew and conquer the "Grand Line."', 'The original Japanese release of Gigant Battle.', 'The first entry in the Gigant Battle series for Japan. Developed by Ganbarion, it sets the standard for handheld One Piece games with its high-quality sprites and chaotic, Smash-like gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('one-piece-gigant-battle-2---shin-sekai-japan', 'NDS', 'One Piece Gigant Battle 2 - Shin Sekai (Japan)', '2012', 'Fighting', 'Ganbarion', '4', 'Anime Fighting', '2D arena fighting and strategy.', 'Survive the New World and become the Pirate King.', 'The expanded and refined sequel for Japan.', 'Gigant Battle 2 - Shin Sekai (New World) features a massive roster including characters from the Marineford and Fish-Man Island arcs. It offers deeper customization and larger-scale battles than the first game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('onegai-my-melody---yume-no-kuni-no-daibouken-japan', 'NDS', 'Onegai My Melody - Yume no Kuni no Daibouken (Japan)', '2007', 'Adventure', 'Marvelous Interactive', '1', 'Anime Adventure', '2D platforming and adventure.', 'Help My Melody rescue her friends in the Land of Dreams.', 'Adorable platformer featuring the Sanrio character.', 'Onegai My Melody: Yume no Kuni no Daibouken is a colorful 2D adventure. Use My Melody’s magical umbrella to glide and defeat enemies across whimsical levels filled with Sanrio charm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oni-zero---sengoku-ranse-hyakka-ryouran-japan', 'NDS', 'Oni Zero - Sengoku Ranse Hyakka Ryouran (Japan)', '2009', 'Strategy', 'Compile Heart', '1', 'Tactical RPG', 'Tactical turn-based RPG.', 'Lead a team of warriors during the Sengoku period.', 'Dark fantasy tactical RPG for Japan.', 'Oni Zero features a unique blend of Japanese history and supernatural elements. Manage your units on a grid and use powerful "Oni" abilities to win the warring states'' conflicts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('onsei-kanjou-sokuteiki---kokoro-scan-japan', 'NDS', 'Onsei Kanjou Sokuteiki - Kokoro Scan (Japan)', '2008', 'Educational', 'TAITO', '1', 'Emotion Analysis', 'Voice analysis and social game.', 'Scan your voice to reveal your true emotions.', 'Unique emotional "scanning" tool for Japan.', 'Kokoro Scan uses the DS microphone to analyze the pitch and tone of your voice. Play social games with friends to see who is telling the truth or feeling stressed in this quirky experiment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ontama---onpu-tou-hen-japan', 'NDS', 'Ontama - Onpu-tou Hen (Japan)', '2007', 'Music', 'Success', '1', 'Rhythm', 'Rhythm and puzzle hybrid.', 'Tap spirits (Ontama) to the beat to play music.', 'Colorful rhythm game with a puzzle twist.', 'Ontama: Onpu-tou Hen tasks you with tapping "spirits" on the touch screen in time with the music. Orchestrate a symphony of sounds to defeat rivals in a musical duel across a magical island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ontamarama-usa', 'NDS', 'Ontamarama (USA)', '2008', 'Music', 'Milestone', '1', 'Rhythm', 'Rhythm and puzzle hybrid.', 'Tap spirits (Ontama) to the beat to play music.', 'North American release of Ontama.', 'Experience the frantic rhythm-action of Ontamarama (USA). Use the stylus and D-pad simultaneously to clear spirits and maintain your combo in one of the DS''s most unique musical challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ookami-den---chiisaki-taiyou-japan', 'NDS', 'Ookami Den - Chiisaki Taiyou (Japan)', '2010', 'Action', 'Clover Studio', '1', 'Action Adventure', 'Action-adventure and painting.', 'Guide Chibiterasu on a quest to save Nippon.', 'The beautiful sequel to the legendary Okami.', 'Ookami Den (Japan) stars a wolf pup named Chibiterasu. Use the "Celestial Brush" on the touch screen to draw objects, solve puzzles, and fight demons in a world inspired by Japanese ink-wash paintings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ookami-den-europe', 'NDS', 'Ookami Den (Europe)', '2011', 'Action', 'HexaDrive', '1', 'Action Adventure', 'Action-adventure and painting.', 'Guide Chibiterasu on a quest to save Nippon.', 'European release of the Okami sequel.', 'Experience the magic of Okamiden (Europe). Partner with diverse characters to navigate puzzles and engage in strategic combat, all rendered in the stunning cel-shaded style of the original series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ookami-den-usa', 'NDS', 'Ookami Den (USA)', '2011', 'Action', 'HexaDrive', '1', 'Action Adventure', 'Action-adventure and painting.', 'Guide Chibiterasu on a quest to save Nippon.', 'North American release of Okamiden.', 'Embark on a grand adventure in Okamiden (USA). This title perfectly adapts the "Celestial Brush" mechanics to the DS touch screen, offering a heartwarming and visually breathtaking journey for fans of Okami.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ookami-to-koushinryou---boku-to-holo-no-ichinen-japan', 'NDS', 'Ookami to Koushinryou - Boku to Holo no Ichinen (Japan)', '2008', 'Visual Novel', 'Imagin', '1', 'Light Novel', 'Visual novel and business simulation.', 'Travel with Holo the Wise Wolf and trade goods.', 'Trading and romance sim based on Spice and Wolf.', 'Ookami to Koushinryou (Japan) mixes light novel storytelling with economic strategy. Balance your inventory and negotiate prices while deepening your bond with Holo during your travels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ookami-to-koushinryou---umi-o-wataru-kaze-japan', 'NDS', 'Ookami to Koushinryou - Umi o Wataru Kaze (Japan)', '2009', 'Visual Novel', 'Imagin', '1', 'Light Novel', 'Visual novel and business simulation.', 'Cross the sea to new lands and find trade profits.', 'The second Spice and Wolf adventure for Japan.', 'Umi o Wataru Kaze (The Wind Over the Sea) expands the trading mechanics. Explore new maritime routes and face new challenges in this immersive blend of mercantile strategy and romantic visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ookiku-furikabutte---honto-no-ace-ni-nareru-kamo-japan', 'NDS', 'Ookiku Furikabutte - Honto no Ace ni Nareru kamo (Japan)', '2007', 'Sports', 'Namco Bandai', '1', 'Baseball', 'Baseball simulation and RPG.', 'Lead your team to victory in the national tournament.', 'Baseball game based on the Big Windup! anime.', 'Ookiku Furikabutte focuses on the psychological side of baseball. Manage team morale and strategy through dialogue choices and mini-games to help your ace pitcher lead the school to glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('open-season-europe-enesitnl', 'NDS', 'Open Season (Europe) (En,Es,It,Nl)', '2006', 'Platformer', 'Ubisoft', '4', 'Family Platformer', 'Action-adventure and mini-games.', 'Help Boog and Elliot survive the hunting season.', 'Multi-language European release of "Open Season".', 'Open Season (Europe) follows the plot of the animated film. Use Boog’s strength and Elliot’s speed to prank hunters, solve environmental puzzles, and participate in a variety of forest-themed mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('open-season-europe-enfrdeesitsvnodafi', 'NDS', 'Open Season (Europe) (En,Fr,De,Es,It,Sv,No,Da,Fi)', '2006', 'Platformer', 'Ubisoft', '4', 'Family Platformer', 'Action-adventure and mini-games.', 'Help Boog and Elliot survive the hunting season.', 'Nordic/European edition of the forest adventure.', 'This version of Open Season includes additional language support for Northern Europe. Experience the humorous quest to return the domesticated bear Boog to his home in the wild.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('open-season-usa-enfresnl', 'NDS', 'Open Season (USA) (En,Fr,Es,Nl)', '2006', 'Platformer', 'Ubisoft', '4', 'Family Platformer', 'Action-adventure and mini-games.', 'Help Boog and Elliot survive the hunting season.', 'North American release of Open Season.', 'Master the forest in Open Season (USA). Throw skunks, scare humans, and use "wild" abilities to complete missions in this colorful action game designed for younger fans of the movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation---vietnam-europe-enfresit', 'NDS', 'Operation - Vietnam (Europe) (En,Fr,Es,It)', '2003', 'Strategy', 'Pterodon', '1', 'Real-Time Tactics', 'Squad-based isometric shooter.', 'Lead a squad of soldiers through the jungles of Vietnam.', 'Tactical top-down jungle combat adventure.', 'Operation: Vietnam (Europe) puts you in command of a four-man squad. Navigate hostile territory, rescue POWs, and use the touch screen to issue orders and manage your team''s unique skills in this intense multi-language shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation---vietnam-germany', 'NDS', 'Operation - Vietnam (Germany)', '2003', 'Strategy', 'Pterodon', '1', 'Real-Time Tactics', 'Squad-based isometric shooter.', 'Lead a squad of soldiers through the jungles of Vietnam.', 'German edition of the tactical squad shooter.', 'Experience the tactical combat of Operation: Vietnam in German. Guide your squad through 20 missions, utilizing specialized weapons and environmental cover to survive the dangers of the jungle and complete your objectives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation---vietnam-usa', 'NDS', 'Operation - Vietnam (USA)', '2003', 'Strategy', 'Pterodon', '1', 'Real-Time Tactics', 'Squad-based isometric shooter.', 'Lead a squad of soldiers through the jungles of Vietnam.', 'North American release of the squad shooter.', 'Take command in Operation: Vietnam (USA). This top-down action game emphasizes strategy over mindless shooting, requiring you to carefully position your troops and manage ammunition to survive the conflict.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('orcs-&-elves-europe-enfrdeesit', 'NDS', 'Orcs & Elves (Europe) (En,Fr,De,Es,It)', '2006', 'RPG', 'id Software', '1', 'Dungeon RPG', 'First-person turn-based RPG.', 'Explore a dwarven fortress and defeat an ancient evil.', 'Old-school dungeon crawler from id Software.', 'Orcs & Elves (Europe) combines first-person exploration with tactical turn-based combat. Use your talking wand and legendary weapons to fight through levels of monsters, solve puzzles, and uncover secrets in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('orcs-&-elves-usa-enfrdeesit', 'NDS', 'Orcs & Elves (USA) (En,Fr,De,Es,It)', '2006', 'RPG', 'id Software', '1', 'Dungeon RPG', 'First-person turn-based RPG.', 'Explore a dwarven fortress and defeat an ancient evil.', 'North American release of the fantasy RPG.', 'Enter the world of Orcs & Elves (USA). Developed by the creators of DOOM, this DS title offers a streamlined and addictive RPG experience where every move and attack counts in your quest to save the dwarven king.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ore-ga-omae-o-mamoru-japan', 'NDS', 'Ore ga Omae o Mamoru (Japan)', '2006', 'Adventure', 'Alchemist', '1', 'Story Adventure', 'Side-scrolling action RPG.', 'Protect the heroine and explore dangerous dungeons.', 'High-speed action RPG with a romantic twist.', 'Ore ga Omae o Mamoru (I''ll Protect You) features fast-paced 2D combat. Explore a massive underground ruins system, upgrade your gear, and defend your companion in this stylish Japanese-exclusive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ore-no-sentouki-japan', 'NDS', 'Ore no Sentouki (Japan)', '2006', 'Shooter', 'SCEI', '1', 'Arcade Shooter', 'Flight combat simulation.', 'Pilot historic fighter jets and complete air missions.', 'Handheld flight combat and dogfighting sim.', 'Ore no Sentouki (My Fighter Plane) lets you experience the thrill of the cockpit. Engage in high-altitude dogfights, manage your radar, and complete diverse missions in this technical flight simulator for Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('original-frisbee-disc-sports---ultimate-&-golf-europe-enfrdeesit', 'NDS', 'Original Frisbee Disc Sports - Ultimate & Golf (Europe) (En,Fr,De,Es,It)', '2007', 'Sports', 'Deck13', '4', 'Disc Sports', 'Sports simulation.', 'Master the art of Frisbee in Ultimate and Golf modes.', 'Official Frisbee disc sports simulator for Europe.', 'Original Frisbee Disc Sports features two distinct modes. Use the stylus to flick and curve the disc with precision in "Ultimate" matches or "Disc Golf" courses across multiple beautiful environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('original-frisbee-disc-sports---ultimate-&-golf-usa', 'NDS', 'Original Frisbee Disc Sports - Ultimate & Golf (USA)', '2007', 'Sports', 'Deck13', '4', 'Disc Sports', 'Sports simulation.', 'Master the art of Frisbee in Ultimate and Golf modes.', 'North American release of the Frisbee sports sim.', 'Grab your disc in Original Frisbee Disc Sports (USA). This title utilizes the DS touch screen for intuitive flick-based controls, offering a relaxing yet competitive take on two of the world''s favorite disc sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('original-rummikub-the---brings-people-together-europe-enfrdeesitnl-dtp-entertainment-ag', 'NDS', 'Original Rummikub, The - Brings People Together (Europe) (En,Fr,De,Es,It,Nl) (DTP Entertainment AG)', '2007', 'Board Game', 'DTP Entertainment', '4', 'Tabletop', 'Digital board and tile game.', 'Be the first to play all your tiles in sets or runs.', 'Classic Rummikub experience for the NDS.', 'The Original Rummikub (Europe - DTP) brings the world-famous tile game to your handheld. Play against smart AI or friends in local multiplayer, featuring the official rules and a clean, easy-to-use interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('original-rummikub-the---brings-people-together-europe-enfrdeesitnl-games-factory-online', 'NDS', 'Original Rummikub, The - Brings People Together (Europe) (En,Fr,De,Es,It,Nl) (Games Factory Online)', '2007', 'Board Game', 'Games Factory Online', '4', 'Tabletop', 'Digital board and tile game.', 'Be the first to play all your tiles in sets or runs.', 'Alternative European release of Rummikub.', 'This version of The Original Rummikub by Games Factory Online offers the same addictive tile-matching gameplay. Focus on strategy and pattern recognition in this portable edition of the classic family board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('osawari-tantei---ozawa-rina---season-2-1-2---rina-wa-mita!-iya-mite-nai-japan', 'NDS', 'Osawari Tantei - Ozawa Rina - Season 2 1-2 - Rina wa Mita! Iya, Mite nai. (Japan)', '2007', 'Adventure', 'Success', '1', 'Detective Adventure', 'Point-and-click adventure.', 'Solve surreal mysteries with Mackenzie and Funghi.', 'Japanese version of Touch Detective 2 1/2.', 'Osawari Tantei - Ozawa Rina: Season 2 expands the quirky world of the first game. Investigate bizarre cases involving professional thieves and strange creatures using Mackenzie''s unique touch-based detective skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('osawari-tantei---ozawa-rina-japan', 'NDS', 'Osawari Tantei - Ozawa Rina (Japan)', '2006', 'Adventure', 'Success', '1', 'Detective Adventure', 'Point-and-click adventure.', 'Solve bizarre mysteries and find clues with touch.', 'The original Touch Detective for Japan.', 'Help Mackenzie solve strange cases in the quiet town of Oslow. This stylized adventure game relies on the DS touch screen for environmental interaction, creating a charming and occasionally eerie atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oscar-der-ballonfahrer---tierische-abenteuer-europe-ende', 'NDS', 'Oscar der Ballonfahrer - Tierische Abenteuer (Europe) (En,De)', '2007', 'Platformer', 'Shin''en', '1', 'Cartoon Platformer', 'Educational adventure and mini-games.', 'Explore nature and learn about animals with Oscar.', 'Nature-themed educational adventure for kids.', 'Oscar der Ballonfahrer features a balloon-flying hero who travels to find rare animals. Solve logic puzzles and participate in activities that teach young players about zoology and the environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshaberi-oumu-japan', 'NDS', 'Oshaberi Oumu (Japan)', '2007', 'Educational', 'IE Institute', '1', 'Voice Training', 'Virtual pet and speech simulation.', 'Teach a parrot to speak and interact with you.', 'Voice-activated parrot care simulation.', 'Oshaberi Oumu (Chatty Parrot) uses the DS microphone for its core gameplay. Train your virtual parrot to mimic your voice and phrases, and care for its needs in this unique Japanese pet-sim experiment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-majo-love-and-berry---ds-collection-japan', 'NDS', 'Oshare Majo Love and Berry - DS Collection (Japan)', '2006', 'Simulation', 'Hudson Soft', '2', 'Fashion Simulation', 'Card-based rhythm and fashion.', 'Collect cards and dance to win fashion contests.', 'Popular arcade card-game port for the NDS.', 'Oshare Majo Love and Berry brings the Japanese arcade phenomenon home. Customize your character''s outfit with digital cards and perform rhythmic dance routines in this fashion-forward social simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-na-koinu-ds-japan', 'NDS', 'Oshare na Koinu DS (Japan)', '2007', 'Simulation', 'Starfish-SD', '1', 'Pet Simulation', 'Pet care and fashion simulation.', 'Raise a cute puppy and dress them in stylish outfits.', 'Stylish puppy care and fashion game for Japan.', 'Oshare na Koinu DS combines the joy of having a pet with deep fashion customization. Choose from popular breeds, enter beauty contests, and design your puppy''s look with hundreds of items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess---oshare-ni-koishite-japan', 'NDS', 'Oshare Princess - Oshare ni Koishite (Japan)', '2008', 'Simulation', 'Tamsoft', '1', 'Fashion Adventure', 'Fashion simulation and romance.', 'Become a fashion expert and find your first love.', 'Fashion-focused social simulation for girls.', 'Oshare Princess tasks you with balancing your social life and your wardrobe. Participate in fashion shows, manage your daily schedule, and interact with various characters to find romance in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshare-princess---oshare-ni-koishite-2-japan', 'NDS', 'Oshare Princess - Oshare ni Koishite 2 (Japan)', '2009', 'Simulation', 'Tamsoft', '1', 'Fashion Adventure', 'Fashion simulation and romance.', 'Master the fashion world and enter grand contests.', 'The expanded sequel to Oshare Princess.', 'Oshare Princess 2 features more clothing options, improved graphics, and new social scenarios. Continue your journey to become the most stylish girl in school while managing your budding romances.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oshiri-kajiri-mushi-no-rhythm-lesson-ds---kawai-ongaku-kyoushitsu-kanshuu-japan', 'NDS', 'Oshiri Kajiri Mushi no Rhythm Lesson DS - Kawai Ongaku Kyoushitsu Kanshuu (Japan)', '2008', 'Music', 'Interchannel', '1', 'Rhythm', 'Rhythm and music simulation.', 'Learn music and rhythm with the Bottom Biter Bug.', 'Fun rhythm trainer based on the popular mascot.', 'Oshiri Kajiri Mushi (Bottom Biter Bug) offers a variety of musical mini-games. Guided by the famous mascot, players can improve their timing and musicality in a humorous and colorful Japanese environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('osu!-tatakae!-ouendan-japan', 'NDS', 'Osu! Tatakae! Ouendan (Japan)', '2005', 'Music', 'iNiS', '1', 'Rhythm Action', 'Rhythm and music action.', 'Tap and swipe to the beat to encourage others.', 'Legendary rhythm game and fan favorite.', 'Osu! Tatakae! Ouendan is a high-energy rhythm game where you lead a male cheer squad. Use the stylus to hit targets in time with J-pop hits to help citizens overcome their problems in this iconic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('othello-de-othello-ds-japan', 'NDS', 'Othello de Othello DS (Japan)', '2007', 'Board Game', 'SUCCESS', '2', 'Strategy Board', 'Classic board game simulation.', 'Outsmart the opponent and flip their tiles to your color.', 'Traditional Othello (Reversi) game for the NDS.', 'Othello de Othello DS provides a clean and professional way to play the classic strategy game. Featuring multiple AI difficulty levels and a local multiplayer mode, it''s the perfect digital board game for logic fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oto-o-tsunagou!-gunpey-rebirth-japan', 'NDS', 'Oto o Tsunagou! Gunpey-Rebirth (Japan)', '2006', 'Puzzle', 'Q-Games', '1', 'Action Puzzle', 'Rhythm and puzzle hybrid.', 'Connect lines to clear falling musical notes.', 'Musical puzzle game by the creator of Rez.', 'Oto o Tsunagou! Gunpey-Rebirth (Japan) is a stylized puzzle experience. Move line segments on a grid to create a continuous path across the screen, all while syncing your actions to a dynamic, evolving soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otogi-juushi-akazukin-japan', 'NDS', 'Otogi Juushi Akazukin (Japan)', '2006', 'RPG', 'KID', '1', 'Fantasy RPG', 'Visual novel and mini-games.', 'Follow the magical girl adventure based on the anime.', 'Fantasy visual novel with interactive segments.', 'Otogi Juushi Akazukin features the characters from the popular anime series. Experience the story through branching dialogue paths and participate in mini-games to help Akazukin and her friends save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otome-teki-koi-kakumei---love-revo!!-ds-japan', 'NDS', 'Otome-teki Koi Kakumei - Love Revo!! DS (Japan)', '2008', 'Simulation', 'Spike', '1', 'Dating Simulation', 'Romantic visual novel and simulation.', 'Lose weight and improve yourself to win your crush''s heart.', 'Humorous "weight loss" dating sim for Japan.', 'Love Revo!! DS is a unique otome game where you must manage your diet and exercise alongside your social interactions. Improve your stats to attract various handsome suitors in this addictive and funny RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otona-no-ds-golf-japan', 'NDS', 'Otona no DS Golf (Japan)', '2006', 'Sports', 'Nintendo', '4', 'Golf Simulation', 'Sports simulation.', 'Master the golf courses and win tournaments.', 'Realistic golf simulation for the "Adult" DS series.', 'Otona no DS Golf offers a mature approach to the sport. With detailed courses and a focus on technical play, it uses the touch screen for precise swing control, catering to fans of traditional golf games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otona-no-ds-mystery---izumi-jiken-file-japan', 'NDS', 'Otona no DS Mystery - Izumi Jiken File (Japan)', '2007', 'Adventure', 'Marvelous Interactive', '1', 'Mystery Adventure', 'Visual novel and mystery.', 'Solve a series of intricate murder mysteries.', 'Adult-oriented mystery and investigation game.', 'Otona no DS Mystery: Izumi Jiken File features mature themes and complex cases. Use your investigative skills to examine crime scenes, interview suspects, and piece together the truth behind a series of crimes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otona-no-onna-ryoku-kentei-japan', 'NDS', 'Otona no Onna Ryoku Kentei (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Life Skills', 'Educational quiz and social skill.', 'Test your social intelligence and feminine etiquette.', 'Etiquette and social skill trainer for women.', 'Otona no Onna Ryoku Kentei tests your knowledge of manners, communication, and lifestyle. It features quizzes designed to measure your "feminine power" in various professional and social scenarios in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otona-no-renai-shousetsu---ds-harlequin-selection-japan', 'NDS', 'Otona no Renai Shousetsu - DS Harlequin Selection (Japan)', '2008', 'Visual Novel', 'Alchemist', '1', 'Romance Novel', 'Digital novel collection.', 'Read classic Harlequin romance novels on your DS.', 'Interactive library of romance novels for adults.', 'DS Harlequin Selection turns your DS into an e-reader. It features several localized Harlequin novels with background music and atmospheric effects, perfect for fans of the world-famous romance series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otona-ryoku-kentei-japan', 'NDS', 'Otona Ryoku Kentei (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Educational quiz and trivia.', 'Test your common sense and adult social skills.', 'General knowledge and "adult power" certification.', 'Otona Ryoku Kentei measures your ability to navigate adult life. From business manners to daily common sense, this title provides scores and advice to help you improve your social standing in Japanese society.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('otoshi-deka---keiji-san-watashi-ga-yarimashita-japan', 'NDS', 'Otoshi Deka - Keiji-san, Watashi ga Yarimashita (Japan)', '2008', 'Adventure', 'Success', '1', 'Crime Adventure', 'Adventure and mystery.', 'Confess your "crimes" to solve the mystery.', 'Unique comedy-detective adventure for Japan.', 'Otoshi Deka features a detective who solves cases by getting people to confess. Use the touch screen to "pressure" suspects and piece together the story in this humorous take on the police procedural genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ougon-no-taiyou---shikkoku-naru-yoake-japan', 'NDS', 'Ougon no Taiyou - Shikkoku Naru Yoake (Japan)', '2010', 'RPG', 'Camelot Software Planning', '1', 'JRPG', 'Turn-based JRPG.', 'Prevent a new eclipse from destroying the world.', 'The epic third entry in the Golden Sun series.', 'Ougon no Taiyou: Shikkoku Naru Yoake (Golden Sun: Dark Dawn) features stunning 3D graphics and complex Psynergy puzzles. Lead a new generation of Adepts in a sprawling quest filled with tactical battles and Djinn collecting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('our-house-usa', 'NDS', 'Our House (USA)', '2008', 'Simulation', 'Budcat Creations', '4', 'Life Simulation', 'Creative simulation and mini-games.', 'Help remodel houses and manage household tasks.', 'Home improvement simulation for younger players.', 'Our House (USA) tasks you with fixing up a virtual home. Use the stylus for a variety of DIY tasks like painting, sawing, and tiling across numerous mini-games as you help families build their dream house.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ouran-koukou-host-club-ds-japan', 'NDS', 'Ouran Koukou Host Club DS (Japan)', '2006', 'Adventure', 'Alchemist', '1', 'Romance Visual Novel', 'Visual novel and dating simulation.', 'Manage the club and build relationships with the hosts.', 'High school romance based on the hit anime.', 'Ouran Koukou Host Club DS lets you play as Haruhi or a new protagonist. Manage the club''s budget, choose host outfits, and navigate social scenarios to win the hearts of the famous Host Club members in this charming Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('outlaws-paradise-remastered', 'NDS', 'Outlaw''s Paradise (Remastered)', '2011', 'Action', 'Konami', '1', 'Arcade Action', 'Open-world crime adventure (Romhack).', 'Rise through the criminal underworld in a custom city.', 'Fan-made remastered crime epic for the NDS.', 'Outlaw''s Paradise (Remastered) is a high-quality romhack that pushes the DS limits. Explore a custom open world, complete dangerous missions, and build your criminal empire in this enhanced fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('outlaws-paradise-remastered-espanol', 'NDS', 'Outlaw''s Paradise (Remastered) (Espanol)', '2011', 'Action', 'Konami', '1', 'Arcade Action', 'Open-world crime adventure (Romhack).', 'Rise through the criminal underworld in a custom city.', 'Spanish version of the remastered crime hack.', 'Experimenta la acción de Outlaw''s Paradise totalmente en español. Esta versión remasterizada ofrece misiones personalizadas y un mundo abierto lleno de detalles técnicos impresionantes para la comunidad de habla hispana.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---beesten-bij-de-buren-netherlands', 'NDS', 'Over the Hedge - Beesten bij de Buren (Netherlands)', '2006', 'Platformer', 'Edge of Reality', '1', 'Cartoon Platformer', 'Action-adventure and stealth.', 'Steal food from humans and avoid traps.', 'Dutch version of "Over the Hedge".', 'Beesten bij de Buren (Netherlands) follows the adventures of RJ and the gang. Use stealth to infiltrate suburban yards and collect snacks while avoiding the Verminator in this fully localized movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---hammy-goes-nuts!-europe', 'NDS', 'Over the Hedge - Hammy Goes Nuts! (Europe)', '2006', 'Platformer', 'Edge of Reality', '1', 'Cartoon Platformer', 'Action-adventure and mini-games.', 'Help Hammy save his friends through fast-paced levels.', 'Squirrel-focused spin-off of Over the Hedge.', 'Hammy Goes Nuts! (Europe) features the hyperactive squirrel in a series of speed-based missions. Slow down time to dodge obstacles and complete puzzles in this multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---hammy-goes-nuts!-europe-frdeesitnl', 'NDS', 'Over the Hedge - Hammy Goes Nuts! (Europe) (Fr,De,Es,It,Nl)', '2006', 'Platformer', 'Edge of Reality', '1', 'Cartoon Platformer', 'Action-adventure and mini-games.', 'Help Hammy save his friends through fast-paced levels.', 'Multi-language European edition of Hammy''s game.', 'Join Hammy in this localized edition for France, Germany, Spain, and Italy. Utilize "Hammy Time" to solve environmental puzzles and outsmart the humans in this frantic and funny adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge---hammy-goes-nuts!-usa', 'NDS', 'Over the Hedge - Hammy Goes Nuts! (USA)', '2006', 'Platformer', 'Edge of Reality', '1', 'Cartoon Platformer', 'Action-adventure and mini-games.', 'Help Hammy save his friends through fast-paced levels.', 'North American release of Hammy Goes Nuts!', 'Launch into a crazy quest in Hammy Goes Nuts! (USA). Control Hammy and his friends through dozens of levels, using their unique abilities to retrieve the gang''s stolen items from the suburban neighborhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge-europe', 'NDS', 'Over the Hedge (Europe)', '2006', 'Platformer', 'Edge of Reality', '1', 'Cartoon Platformer', 'Action-adventure and stealth.', 'Guide the forest animals on their food-raiding quest.', 'European release of the original movie game.', 'Over the Hedge (Europe) blends platforming and stealth. Switch between RJ, Verne, and Hammy to utilize their specific strengths and complete high-stakes food heists in this faithful adaptation of the DreamWorks film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('over-the-hedge-usa', 'NDS', 'Over the Hedge (USA)', '2006', 'Platformer', 'Edge of Reality', '1', 'Cartoon Platformer', 'Action-adventure and stealth.', 'Guide the forest animals on their food-raiding quest.', 'North American release of Over the Hedge.', 'Master the art of suburban infiltration in Over the Hedge (USA). Fight off aggressive pets, set traps for humans, and enjoy various mini-games as you help the forest crew survive the winter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('overlord-minions-europe-enfrdeesit', 'NDS', 'Overlord Minions (Europe) (En,Fr,De,Es,It)', '2010', 'Action', 'RuneStorm', '1', 'Action Strategy', 'Action-puzzle and strategy.', 'Command a squad of minions to defeat the Kindred.', 'Minion-management tactical game for Europe.', 'Overlord Minions (Europe) uses a unique touch-screen control scheme. Guide your loyal, destructive minions through puzzles and combat, utilizing different minion types to conquer enemies and solve environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('overlord-minions-usa-enfres', 'NDS', 'Overlord Minions (USA) (En,Fr,Es)', '2010', 'Action', 'RuneStorm', '1', 'Action Strategy', 'Action-puzzle and strategy.', 'Command a squad of minions to defeat the Kindred.', 'North American release of the Overlord spin-off.', 'Unleash your evil side in Overlord Minions (USA). Command Brown, Red, Green, and Blue minions with the stylus to pillage, solve riddles, and serve your dark will in this creative action-puzzle adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('oyako-de-asoberu-ds-ehon---ukkari-penelope-japan', 'NDS', 'Oyako de Asoberu DS Ehon - Ukkari Penelope (Japan)', '2007', 'Educational', 'IE Institute', '1', 'Interactive Storybook', 'Educational and digital storybook.', 'Read and interact with Penelope the koala.', 'Interactive digital picture book for kids.', 'Ukkari Penelope (Japan) is an adorable educational tool. Young children can listen to stories, play simple mini-games, and learn basic daily routines through the charming world of Penelope the koala.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paard-&-pony---mijn-paardenstal-netherlands-ennl', 'NDS', 'Paard & Pony - Mijn Paardenstal (Netherlands) (En,Nl)', '2008', 'Simulation', 'Amaze Entertainment', '1', 'Horse Simulation', 'Horse simulation and management.', 'Manage a stable and train your horses for competition.', 'Dutch horse care and riding simulation.', 'Mijn Paardenstal (Netherlands) lets you live the dream of owning a stable. Feed, groom, and train your horses to compete in show jumping and dressage events in this bilingual Dutch/English title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-world-3-europe', 'NDS', 'Pac-Man World 3 (Europe)', '2005', 'Platformer', 'Blitz Games', '1', '3D Platformer', '3D platforming and action.', 'Save the world from the Spectral Realm.', 'Pac-Man''s 25th-anniversary adventure for Europe.', 'Pac-Man World 3 (Europe) combines classic pellet-eating with 3D combat. Use various power-ups and explore massive levels as Pac-Man fights to stop an evil genius from tearing apart the fabric of reality.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-world-3-usa', 'NDS', 'Pac-Man World 3 (USA)', '2005', 'Platformer', 'Blitz Games', '1', '3D Platformer', '3D platforming and action.', 'Save the world from the Spectral Realm.', 'North American release of the 3D platformer.', 'Experience the evolution of the yellow icon in Pac-Man World 3 (USA). Featuring voice acting and a deeper combat system, this title celebrates Pac-Man''s legacy while offering a modern, handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-pix-europe-enfrdeesit', 'NDS', 'Pac-Pix (Europe) (En,Fr,De,Es,It)', '2005', 'Puzzle', 'Namco', '1', 'Drawing Puzzle', 'Drawing-based action puzzle.', 'Draw Pac-Man to eat ghosts on the screen.', 'Innovative drawing-based Pac-Man for Europe.', 'Pac-Pix (Europe) is a technical showcase for the DS. Use the stylus to draw Pac-Man directly on the screen; once drawn, he comes to life and follows the direction you sketched to devour ghosts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-pix-japan', 'NDS', 'Pac-Pix (Japan)', '2005', 'Puzzle', 'Namco', '1', 'Drawing Puzzle', 'Drawing-based action puzzle.', 'Draw Pac-Man to eat ghosts on the screen.', 'The original Japanese release of Pac-Pix.', 'Pac-Pix (Japan) reinvented a classic for the touch screen. Master the art of drawing Pac-Man, arrows, and bombs to solve dynamic puzzles and clear the screen of spectral enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-pix-korea', 'NDS', 'Pac-Pix (Korea)', '2005', 'Puzzle', 'Namco', '1', 'Drawing Puzzle', 'Drawing-based action puzzle.', 'Draw Pac-Man to eat ghosts on the screen.', 'Korean localized version of Pac-Pix.', 'Experience the magic of "Sketch and Action" in Korea. Pac-Pix (Korea) utilizes the DS stylus in a way that feels natural and magical, challenging players to draw their way through increasingly difficult levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-pix-usa', 'NDS', 'Pac-Pix (USA)', '2005', 'Puzzle', 'Namco', '1', 'Drawing Puzzle', 'Drawing-based action puzzle.', 'Draw Pac-Man to eat ghosts on the screen.', 'North American release of the sketching hit.', 'Unleash your inner artist in Pac-Pix (USA). Draw circles to create Pac-Man and lines to create barriers, guiding your hand-drawn hero to clear the screen in this creative and addictive puzzle-action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacn-ball-korea', 'NDS', 'Pac''n Ball (Korea)', '2004', 'Puzzle', 'Namco', '1', 'Action Puzzle', 'Rolling action and platforming.', 'Roll Pac-Man through 3D courses to reach the goal.', 'Korean version of the rolling Pac-Man game.', 'Pac''n Ball brings the innovative rolling mechanics to Korea. Use the touch screen to "swipe" Pac-Man like a trackball, navigating treacherous 3D environments and collecting pellets to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacn-roll-europe-enfrdeesit', 'NDS', 'Pac''n Roll (Europe) (En,Fr,De,Es,It)', '2005', 'Action', 'Namco', '1', 'Physics Platformer', 'Rolling action and platforming.', 'Roll Pac-Man through 3D courses to reach the goal.', 'European release of the 3D rolling adventure.', 'Pac''n Roll (Europe) offers a fresh perspective on the series. Control Pac-Man with the stylus as he rolls through vibrant worlds, using different "weight" power-ups to solve physics-based puzzles and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacn-roll-japan', 'NDS', 'Pac''n Roll (Japan)', '2005', 'Action', 'Namco', '1', 'Physics Platformer', 'Rolling action and platforming.', 'Roll Pac-Man through 3D courses to reach the goal.', 'Original Japanese release of Pac''n Roll.', 'Master the physics of the roll in Pac''n Roll (Japan). This title uses the bottom screen as a giant trackball, providing precise control as you navigate Pac-Land and fight against the ghost army.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pacn-roll-usa', 'NDS', 'Pac''n Roll (USA)', '2005', 'Action', 'Namco', '1', 'Physics Platformer', 'Rolling action and platforming.', 'Roll Pac-Man through 3D courses to reach the goal.', 'North American release of the rolling hit.', 'Roll to victory in Pac''n Roll (USA). With its intuitive touch-screen controls and creative level design, it''s a unique arcade experience that perfectly captures the spirit of Pac-Man in a 3D space.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pachi-&-slot-hisshoubon-ds-japan', 'NDS', 'Pachi & Slot Hisshoubon DS (Japan)', '2006', 'Gambling', 'Koei', '1', 'Pachinko Simulation', 'Pachinko and Slot simulation.', 'Master the latest Pachinko and Slot machines.', 'Authentic Japanese gambling simulator.', 'Pachi & Slot Hisshoubon DS features realistic recreations of popular Japanese parlor machines. Study the odds, practice your timing, and win virtual credits in this deep simulation for enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paint-by-ds---classic-masterpieces-europe-enfrit', 'NDS', 'Paint by DS - Classic Masterpieces (Europe) (En,Fr,It)', '2008', 'Educational', 'O-Games', '1', 'Art Coloring', 'Digital painting and art.', 'Paint recreations of world-famous masterpieces.', 'Fine art painting simulation for Europe.', 'Paint by DS: Classic Masterpieces (Europe) lets you color-by-number the works of Van Gogh, Monet, and more. Use various virtual brushes and palettes to recreate legendary art on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paint-by-ds---military-vehicles-europe-enfrdeesit', 'NDS', 'Paint by DS - Military Vehicles (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'O-Games', '1', 'Art Coloring', 'Digital painting and art.', 'Paint detailed models of military vehicles.', 'Military-themed art and painting game.', 'Paint by DS: Military Vehicles (Europe) features tanks, planes, and ships. Use the stylus to carefully apply camouflage and details to historically accurate machines in this specialized artistic simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paint-by-ds-europe-enfrdeesit', 'NDS', 'Paint by DS (Europe) (En,Fr,De,Es,It)', '2007', 'Educational', 'O-Games', '1', 'Art Coloring', 'Digital painting and art.', 'Create and color various artistic illustrations.', 'The original creative painting tool for Europe.', 'Paint by DS (Europe) is a relaxing creative experience. Choose from multiple templates, mix your own colors, and learn digital painting techniques using the DS touch-screen interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panda-san-nikki-japan', 'NDS', 'Panda-san Nikki (Japan)', '2008', 'Simulation', 'Takuyo', '1', 'Daily Life Simulation', 'Virtual pet and diary simulation.', 'Spend daily life with a cute panda and keep a diary.', 'Adorable panda care and social simulation.', 'Panda-san Nikki (Panda''s Diary) lets you raise a baby panda in real-time. Interact with your pet, play mini-games, and record your daily activities in a digital diary in this charming Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panel-de-pon-ds-japan', 'NDS', 'Panel de Pon DS (Japan)', '2007', 'Puzzle', 'Nintendo', '2', 'Competitive Puzzle', 'Competitive block-matching puzzle.', 'Clear the screen by swapping blocks to match three.', 'The classic Nintendo puzzle series for Japan.', 'Panel de Pon DS (known in the West as Puzzle League) offers fast-paced competitive action. Match colored blocks vertically or horizontally to launch attacks and climb the ranks in this addictive puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panpaka-panya-san-japan', 'NDS', 'Panpaka Panya-san (Japan)', '2009', 'Simulation', 'Success', '1', 'Shop Management', 'Bakery management and cooking.', 'Run a successful bread shop and serve customers.', 'Charming bakery and management simulation.', 'Panpaka Panya-san (Panpaka Bakery) tasks you with kneading, baking, and selling a variety of breads. Manage your shop''s inventory and satisfy customer requests to become the best baker in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panzer-tactics-ds-europe-enfrdeesit', 'NDS', 'Panzer Tactics DS (Europe) (En,Fr,De,Es,It)', '2002007', 'Strategy', '10tacle Studios', '2', 'Turn-Based Tactics', 'Turn-based tactical strategy.', 'Win historical battles during World War II.', 'Deep hex-based WWII strategy game for Europe.', 'Panzer Tactics DS (Europe) is a hardcore tactical simulation. Command the Axis, Allied, or Soviet forces across 30 missions, managing fuel, ammo, and terrain to outmaneuver your opponents in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panzer-tactics-ds-usa-enfrdeesit', 'NDS', 'Panzer Tactics DS (USA) (En,Fr,De,Es,It)', '2007', 'Strategy', '10tacle Studios', '2', 'Turn-Based Tactics', 'Turn-based tactical strategy.', 'Win historical battles during World War II.', 'North American release of the tactical WWII sim.', 'Engage in grand-scale warfare in Panzer Tactics DS (USA). With over 150 different units and a deep turn-based system, it offers a challenging experience for strategy fans looking for historical accuracy on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('partouche-poker-tour---poker-texas-holdem-no-limit-france', 'NDS', 'Partouche Poker Tour - Poker Texas Hold''em No Limit (France)', '2009', 'Board Game', 'Spin2Win', '4', 'Poker Simulation', 'Poker simulation and tournament.', 'Win the Partouche Poker Tour championship.', 'Professional Texas Hold''em poker for France.', 'Partouche Poker Tour brings the excitement of the casino to the DS. Learn advanced strategies, participate in high-stakes tournaments, and master the art of the bluff in this specialized French poker sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('party-carnival-europe', 'NDS', 'Party Carnival (Europe)', '2008', 'Party', 'GameMill Entertainment', '4', 'Party Minigames', 'Mini-game and party collection.', 'Win a variety of casual party games.', 'Family-friendly party game collection for Europe.', 'Party Carnival features dozens of quick-play mini-games. From racing to logic challenges, it’s designed for local multiplayer fun, making it a great title for social gaming sessions on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pass-the-pigs---let-the-good-swines-roll!-europe', 'NDS', 'Pass the Pigs - Let the Good Swines Roll! (Europe)', '2008', 'Board Game', 'Hudson Soft', '4', 'Dice Party Game', 'Dice-style board game with pigs.', 'Score points by throwing pigs and landing specific poses.', 'Digital version of the classic "Pass the Pigs" game.', 'Pass the Pigs (Europe) brings the quirky tabletop game to the DS. Use the stylus to "toss" the pigs and hope for a ''Leaning Jowler'' or ''Double Snouter'' to rack up points in this fun, portable gambling-style game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pass-the-pigs---let-the-good-swines-roll!-usa', 'NDS', 'Pass the Pigs - Let the Good Swines Roll! (USA)', '2008', 'Board Game', 'Hudson Soft', '4', 'Dice Party Game', 'Dice-style board game with pigs.', 'Score points by throwing pigs and landing specific poses.', 'North American release of the swine-tossing game.', 'Roll the pigs in Pass the Pigs (USA). Featuring various game modes and multiplayer options, it’s a faithful digital recreation of the classic game of chance where your luck depends on how the pigs land.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pass-your-driving-theory-test-europe', 'NDS', 'Pass Your Driving Theory Test (Europe)', '2009', 'Educational', 'Digital Leisure', '1', 'Driving Theory Training', 'Educational quiz and simulation.', 'Pass the official driving theory mock exams.', 'Driving test preparation tool for Europe.', 'Pass Your Driving Theory Test (Europe) is an essential study aid. It includes thousands of official questions, hazard perception clips, and mock exams to help students prepare for their license in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('passeport-du-ce1-au-ce2-france', 'NDS', 'Passeport du CE1 au CE2 (France)', '2008', 'Educational', 'Mindscape', '1', 'School Training', 'Educational school review.', 'Review French, Math, and Science to prep for CE2.', 'Summer bridge educational game for French students.', 'Passeport du CE1 au CE2 (France) makes summer studying fun. Through interactive exercises and mini-games, students review the curriculum to ensure they are ready for the next grade level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('passeport-du-ce2-au-cm1-france', 'NDS', 'Passeport du CE2 au CM1 (France)', '2008', 'Educational', 'Mindscape', '1', 'School Training', 'Educational school review.', 'Review the 3rd-year primary curriculum for CM1.', 'French educational trainer for primary school.', 'Passeport du CE2 au CM1 helps children maintain their academic skills. It covers all core subjects of the French national curriculum with a rewarding system that keeps students engaged.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('passeport-du-cm1-au-cm2-france', 'NDS', 'Passeport du CM1 au CM2 (France)', '2008', 'Educational', 'Mindscape', '1', 'School Training', 'Educational school review.', 'Review the 4th-year primary curriculum for CM2.', 'Advanced primary school educational tool for France.', 'Prepare for the final year of elementary school with Passeport du CM1 au CM2. This title offers specialized drills in grammar, complex math, and history tailored to the French educational system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('passeport-du-cm2-a-la-6eme-france', 'NDS', 'Passeport du CM2 a la 6eme (France)', '2008', 'Educational', 'Mindscape', '1', 'School Training', 'Educational school review.', 'Prepare for the transition to middle school (6ème).', 'Comprehensive French middle-school prep tool.', 'Passeport du CM2 a la 6eme is designed for the big leap to "Collège." It reinforces fundamental knowledge while introducing students to the logic and organization required for middle school success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('passeport-du-cp-au-ce1-france', 'NDS', 'Passeport du CP au CE1 (France)', '2008', 'Educational', 'Mindscape', '1', 'School Training', 'Educational school review.', 'Review the first year of primary school for CE1.', 'Foundational educational game for young students.', 'Passeport du CP au CE1 focuses on basic reading, writing, and arithmetic. Use the DS touch screen to practice letters and numbers in a playful environment designed by educational experts in France.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('patto-tokeru!---india-suugaku-drill-ds---jiman-shitaku-naru-anzan-hou-japan', 'NDS', 'Patto Tokeru! - India Suugaku Drill DS - Jiman Shitaku Naru Anzan Hou (Japan)', '2007', 'Educational', 'IE Institute', '1', 'Mental Math Training', 'Educational math drills.', 'Master Indian mental arithmetic techniques.', 'Advanced mental math trainer for Japan.', 'Patto Tokeru! India Suugaku Drill teaches rapid calculation methods. Improve your brain power by learning "magic" math shortcuts that allow you to solve complex multiplications in seconds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pawly-pets---my-pet-hotel-europe-enfr', 'NDS', 'Pawly Pets - My Pet Hotel (Europe) (En,Fr)', '2008', 'Simulation', 'Tivola', '1', 'Pet Hotel Management', 'Animal management and simulation.', 'Run a successful hotel for cats, dogs, and horses.', 'Pet hotel management simulation for Europe.', 'Pawly Pets: My Pet Hotel (Europe) puts you in charge of a luxury animal resort. Groom, feed, and play with your guests to keep them happy and grow your business into the best pet hotel in the country.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pawly-pets---my-vet-practice-europe', 'NDS', 'Pawly Pets - My Vet Practice (Europe)', '2009', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Animal care and medical simulation.', 'Diagnose and treat sick animals in your clinic.', 'Veterinary practice simulation for Europe.', 'Pawly Pets: My Vet Practice (Europe) allows you to become a veterinarian. Use the stylus to perform check-ups, administer medicine, and nurse pets back to health in this realistic and educational sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pawly-pets---my-vet-practice-europe-enesit', 'NDS', 'Pawly Pets - My Vet Practice (Europe) (En,Es,It)', '2009', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Animal care and medical simulation.', 'Diagnose and treat sick animals in your clinic.', 'Multi-language European edition of My Vet Practice.', 'Step into the clinic in this localized edition for Spain and Italy. Manage your daily schedule as a vet, upgrade your facilities, and care for everything from hamsters to horses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pawly-pets---my-vet-practice-europe-enfrde', 'NDS', 'Pawly Pets - My Vet Practice (Europe) (En,Fr,De)', '2009', 'Simulation', 'Tivola', '1', 'Veterinary Simulation', 'Animal care and medical simulation.', 'Diagnose and treat sick animals in your clinic.', 'North-European edition of the veterinary sim.', 'This version of My Vet Practice includes French and German language support. Balance your clinic''s finances while providing top-tier medical care to a variety of adorable animals in need.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---best-friends---dogs-&-cats-usa', 'NDS', 'Paws & Claws - Best Friends - Dogs & Cats (USA)', '2006', 'Simulation', 'THQ', '1', 'Pet Care Simulation', 'Animal care and simulation.', 'Care for puppies and kittens and find them homes.', 'Double-pack pet simulation for North America.', 'Paws & Claws: Best Friends (USA) features two of the most popular pets. Learn the responsibilities of owning a dog or cat, from grooming and feeding to training them for show competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---pampered-pets-usa', 'NDS', 'Paws & Claws - Pampered Pets (USA)', '2007', 'Simulation', 'THQ', '1', 'Pet Care Simulation', 'Animal grooming and fashion.', 'Pamper and style pets for the ultimate beauty show.', 'Pet spa and beauty salon simulation.', 'Paws & Claws: Pampered Pets (USA) focuses on high-end animal care. Use the stylus to style fur, pick out accessories, and provide spa treatments to make your pets look their best for the judges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---pet-resort-usa', 'NDS', 'Paws & Claws - Pet Resort (USA)', '2008', 'Simulation', 'THQ', '1', 'Pet Resort Management', 'Animal management and simulation.', 'Build and manage a world-class resort for pets.', 'Pet-focused resort management sim for the USA.', 'Paws & Claws: Pet Resort (USA) challenges you to create the ultimate vacation spot for animals. Design the layout, manage the staff, and ensure every furry guest has a five-star experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---pet-vet---australian-adventures-usa', 'NDS', 'Paws & Claws - Pet Vet - Australian Adventures (USA)', '2007', 'Simulation', 'THQ', '1', 'Veterinary Simulation', 'Animal care and exploration.', 'Rescue and treat unique animals in the Australian outback.', 'Veterinary adventure set in Australia.', 'Paws & Claws: Pet Vet - Australian Adventures (USA) takes the vet series down under. Treat kangaroos, wombats, and koalas while exploring the unique environments of the Australian wild.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---pet-vet-usa', 'NDS', 'Paws & Claws - Pet Vet (USA)', '2006', 'Simulation', 'THQ', '1', 'Veterinary Simulation', 'Animal care and medical simulation.', 'Build a successful veterinary clinic from the ground up.', 'The original Pet Vet simulation for North America.', 'Become the best vet in town in Paws & Claws: Pet Vet (USA). Diagnose illnesses, perform surgeries, and expand your clinic as you gain a reputation for excellence in animal care.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---pet-vet-2-usa', 'NDS', 'Paws & Claws - Pet Vet 2 (USA)', '2007', 'Simulation', 'THQ', '1', 'Veterinary Simulation', 'Animal care and medical simulation.', 'Expand your practice and treat more animal species.', 'The comprehensive sequel to Pet Vet.', 'Paws & Claws: Pet Vet 2 (USA) introduces more complex medical cases and new animal breeds. Manage your time efficiently to treat all your patients and maintain a thriving veterinary practice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paws-&-claws---regal-resort-usa', 'NDS', 'Paws & Claws - Regal Resort (USA)', '2008', 'Simulation', 'THQ', '1', 'Pet Resort Management', 'Animal management and simulation.', 'Manage a high-end luxury resort for royal pets.', 'High-society pet resort simulation for the USA.', 'Paws & Claws: Regal Resort (USA) adds a touch of class to the series. Cater to the needs of pampered pets, providing them with the most expensive toys and gourmet treats in a lavish setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pdc-world-championship-darts---the-official-video-game-europe-enfrdeesitnl', 'NDS', 'PDC World Championship Darts - The Official Video Game (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Sports', 'Oxygen Studios', '4', 'Darts Simulation', 'Sports simulation.', 'Win the world darts championship as a pro player.', 'Officially licensed PDC darts game for Europe.', 'PDC World Championship Darts features the world''s top players. Use the touch screen to mimic the throwing motion for maximum precision, competing in various tournament modes and classic pub games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pdc-world-championship-darts-usa-enfresitnl', 'NDS', 'PDC World Championship Darts (USA) (En,Fr,Es,It,Nl)', '2009', 'Sports', 'Oxygen Studios', '4', 'Darts Simulation', 'Sports simulation.', 'Win the world darts championship as a pro player.', 'North American release of the official darts game.', 'Take aim in PDC World Championship Darts (USA). With realistic physics and multiple difficulty levels, it offers an authentic darts experience including the full PDC tournament roster and commentary.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peggle-dual-shot-usa', 'NDS', 'Peggle Dual Shot (USA)', '2009', 'Puzzle', 'PopCap Games', '2', 'Physics Puzzle', 'Puzzle and arcade action.', 'Clear all the orange pegs to complete each level.', 'The addictive puzzle hit with exclusive DS content.', 'Peggle Dual Shot (USA) combines the original game and "Peggle Nights." Use the stylus to aim your ball, trigger "Extreme Fever," and unlock 10 different Peggle Masters in this definitive handheld version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pekin-express---la-route-de-lhimalaya-france', 'NDS', 'Pekin Express - La Route de l''Himalaya (France)', '2009', 'Adventure', 'Blue Tongue Entertainment', '1', 'Reality TV Adventure', 'Adventure and mini-games.', 'Complete the race across the Himalayas to win.', 'Reality show adaptation for French players.', 'Pekin Express: La Route de l''Himalaya (France) follows the hit TV show. Manage your budget, find transport, and complete cultural challenges across Asia to reach the finish line first.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pen1-grand-prix---penguin-no-mondai-special-japan', 'NDS', 'Pen1 Grand Prix - Penguin no Mondai Special (Japan)', '2008', 'Puzzle', 'Nintendo', '1', 'Comedy Puzzle', 'Platforming and combat.', 'Win the Grand Prix and become the top penguin.', 'Wacky action-adventure based on the manga.', 'Pen1 Grand Prix features the bizarre and hilarious characters from "Penguin no Mondai." Use your penguin transformations and combat skills to win a series of absurd challenges and battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguin-no-mondai---saikyou-penguin-densetsu!-japan', 'NDS', 'Penguin no Mondai - Saikyou Penguin Densetsu! (Japan)', '2008', 'Puzzle', 'Nintendo', '1', 'Comedy Puzzle', 'Platforming and combat.', 'Build your legend and defeat rival penguins.', 'The first DS title in the Penguin no Mondai series.', 'Saikyou Penguin Densetsu! (Japan) lets you customize your penguin hero. Explore various levels, collect items, and use "G-G-G-G" powers to defeat enemies in this high-energy 2D platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguin-no-mondai---the-world-japan', 'NDS', 'Penguin no Mondai - The World (Japan)', '2009', 'Puzzle', 'Nintendo', '1', 'Comedy Puzzle', 'Open-world action and customization.', 'Explore the world and solve the penguin crisis.', 'The second entry in the Penguin no Mondai series.', 'Penguin no Mondai: The World (Japan) offers more exploration and hundreds of customization parts. Interact with a large cast of characters and engage in rhythmic and action-based mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguin-no-mondai-x---tenkuu-no-7-senshi-japan', 'NDS', 'Penguin no Mondai X - Tenkuu no 7 Senshi (Japan)', '2010', 'Puzzle', 'Nintendo', '1', 'Comedy Puzzle', 'Action RPG and platforming.', 'Defeat the 7 Warriors of the Sky to save the world.', 'The "X" series installment for Penguin no Mondai.', 'Tenkuu no 7 Senshi features a more story-driven adventure. With improved combat and new flight mechanics, help Becky and his friends protect the skies in this content-packed Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguins-of-madagascar-the-europe-enfr-ndsi-enhanced', 'NDS', 'Penguins of Madagascar, The (Europe) (En,Fr) (NDSi Enhanced)', '2010', 'Action', 'WayForward', '2', 'Cartoon Action Platformer', 'Stealth and action platforming.', 'Complete secret missions using elite penguin skills.', 'DSi Enhanced adventure featuring the Madagascar crew.', 'The Penguins of Madagascar (Europe) takes you on covert operations. Switch between Skipper, Kowalski, Rico, and Private to solve puzzles and use gadgets in this visually impressive, multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguins-of-madagascar-the-usa-enfr-ndsi-enhanced', 'NDS', 'Penguins of Madagascar, The (USA) (En,Fr) (NDSi Enhanced)', '2010', 'Action', 'WayForward', '2', 'Cartoon Action Platformer', 'Stealth and action platforming.', 'Complete secret missions using elite penguin skills.', 'North American DSi Enhanced penguin adventure.', 'Join the commandos of the Central Park Zoo in The Penguins of Madagascar (USA). Use the DSi camera features to solve puzzles and lead the team through a series of hilarious and tactical missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peppa-pig---fun-and-games-europe', 'NDS', 'Peppa Pig - Fun and Games (Europe)', '2008', 'Educational', 'P2 Games', '1', 'Children Minigames', 'Educational mini-games and puzzles.', 'Play and learn with Peppa and her friends.', 'Fun-filled activity collection for toddlers.', 'Peppa Pig: Fun and Games (Europe) offers a variety of simple, touch-based activities. From making pizza to playing hide and seek, it’s designed to help young children develop basic coordination and logic skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peppa-pig---the-game-europe', 'NDS', 'Peppa Pig - The Game (Europe)', '2009', 'Educational', 'P2 Games', '1', 'Children Minigames', 'Educational mini-games and puzzles.', 'Join Peppa in her daily adventures and games.', 'The first Peppa Pig title for the Nintendo DS.', 'Peppa Pig: The Game (Europe) features the iconic art style and voices from the show. Children can participate in various activities like jumping in muddy puddles and flying a kite in this gentle and educational experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('percy-jackson-&-the-lightning-thief-europe-enfrdeesit', 'NDS', 'Percy Jackson & the Lightning Thief (Europe) (En,Fr,De,Es,It)', '2010', 'Action RPG', 'Griptonite Games', '1', 'Story-Driven Adventure', 'Tactical turn-based RPG.', 'Defeat mythological foes and reach Mount Olympus.', 'Movie-based tactical RPG with Greek myths.', 'Percy Jackson & the Lightning Thief (Europe) features strategic combat. Assemble a team of demigods, manage their special abilities, and battle legendary monsters in a quest that follows the hit film''s storyline across Europe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('percy-jackson-and-the-olympians---the-lightning-thief-usa-enfr', 'NDS', 'Percy Jackson and the Olympians - The Lightning Thief (USA) (En,Fr)', '2010', 'Action RPG', 'Griptonite Games', '1', 'Story-Driven Adventure', 'Tactical turn-based RPG.', 'Defeat mythological foes and reach Mount Olympus.', 'North American release of the Percy Jackson RPG.', 'Experience the legend in Percy Jackson (USA). Master the elemental powers of Poseidon''s son in grid-based tactical battles, upgrading your equipment and skills to survive the ultimate clash of gods and titans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-fitness-for-men-usa-enfres', 'NDS', 'Personal Fitness for Men (USA) (En,Fr,Es)', '2009', 'Fitness', 'Ubisoft', '1', 'Fitness Training', 'Fitness and workout simulation.', 'Improve physical health through structured exercises.', 'Personalized workout coach designed for men.', 'Personal Fitness for Men (USA) offers a tailored exercise program. Use the DS to track your progress, follow animated routines, and receive nutritional advice to reach your specific fitness goals in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-fitness-for-women-usa-enfres', 'NDS', 'Personal Fitness for Women (USA) (En,Fr,Es)', '2009', 'Fitness', 'Ubisoft', '1', 'Fitness Training', 'Fitness and workout simulation.', 'Improve physical health through structured exercises.', 'Personalized workout coach designed for women.', 'Personal Fitness for Women (USA) focuses on yoga, cardio, and strength training. Featuring a digital trainer and weight tracking, it provides a balanced health regimen that fits easily into a daily schedule.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-trainer---cooking-usa', 'NDS', 'Personal Trainer - Cooking (USA)', '2008', 'Educational', 'Ubisoft', '1', 'Cooking Training', 'Digital cookbook and guide.', 'Master over 245 international recipes step-by-step.', 'Interactive kitchen assistant and recipe guide.', 'Personal Trainer: Cooking (USA) turns your DS into a chef. Use voice commands to turn pages while cooking, watch instructional videos for techniques, and search for recipes by region, calorie count, or ingredients.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-trainer---math-usa-enfres', 'NDS', 'Personal Trainer - Math (USA) (En,Fr,Es)', '2008', 'Educational', 'Ubisoft', '1', 'Math Training', 'Educational math training.', 'Master arithmetic through the "Kageyama Method."', 'High-speed math trainer for all skill levels.', 'Personal Trainer: Math (USA) uses repetitive, fast-paced drills to improve mental calculation. From basic addition to complex divisions, it tracks your daily performance to build a strong mathematical foundation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-trainer---walking-usa-enfres', 'NDS', 'Personal Trainer - Walking (USA) (En,Fr,Es)', '2008', 'Fitness', 'Ubisoft', '1', 'Walking Training', 'Health and activity tracking.', 'Track your daily steps and set lifestyle goals.', 'Pedometer-based health and walking simulation.', 'Personal Trainer: Walking (USA) connects to the DS Life Rhythm Meter. Monitor your activity levels, compare results with family members, and unlock world maps as you walk your way to a healthier lifestyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-trainer-ds-for-men-europe-enfrdeesit', 'NDS', 'Personal Trainer DS for Men (Europe) (En,Fr,De,Es,It)', '2009', 'Fitness', 'Ubisoft', '1', 'Fitness Training', 'Fitness and workout simulation.', 'Complete daily workouts and track calorie burn.', 'European fitness coach for male users.', 'Personal Trainer DS for Men (Europe) provides a virtual gym experience. With localized multi-language support, it offers various intensity levels and a digital calendar to keep your training on track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-trainer-ds-for-women-europe-enfrdeesit', 'NDS', 'Personal Trainer DS for Women (Europe) (En,Fr,De,Es,It)', '2009', 'Fitness', 'Ubisoft', '1', 'Fitness Training', 'Fitness and workout simulation.', 'Complete daily workouts and track calorie burn.', 'European fitness coach for female users.', 'Personal Trainer DS for Women (Europe) focuses on flexibility and toning. Follow the on-screen coach through various routines and use the built-in tracking tools to visualize your health journey across Europe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('personal-yoga-training---learn-in-15-minutes-a-day-europe-enfrdeesit', 'NDS', 'Personal Yoga Training - Learn in 15 Minutes a Day (Europe) (En,Fr,De,Es,It)', '2009', 'Fitness', 'Aerosoft', '1', 'Yoga Training', 'Yoga simulation and training.', 'Learn and master yoga poses in 15-minute sessions.', 'Accessible daily yoga coach for beginners.', 'Personal Yoga Training (Europe) makes wellness easy. With clear 3D animations and voice guidance, you can practice dozens of asanas at home, focusing on breathing, relaxation, and physical alignment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-adoption-center-usa-enfrdenl', 'NDS', 'Pet Adoption Center (USA) (En,Fr,De,Nl)', '2008', 'Simulation', 'Artefacts Studio', '1', 'Pet Care Simulation', 'Animal care simulation.', 'Rescue, rehabilitate, and find homes for pets.', 'Pet shelter management and care simulation.', 'Pet Adoption Center (USA) tasks you with running a shelter. Provide medical care, grooming, and training for various animals to ensure they find the perfect "forever home" in this rewarding simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-alien---an-intergalactic-puzzlepalooza-usa-enfres', 'NDS', 'Pet Alien - An Intergalactic Puzzlepalooza (USA) (En,Fr,Es)', '2005', 'Puzzle', 'Game Arts', '1', 'Cartoon Puzzle', 'Puzzle-adventure and strategy.', 'Use five different aliens to solve complex puzzles.', 'Tactical puzzle game based on the TV show.', 'Pet Alien (USA) features a unique "Puzzlepalooza" mechanic. Switch between five distinct aliens, each with special abilities like strength or levitation, to navigate 3D environments and stop an invasion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-alien-europe-enfrdeesit', 'NDS', 'Pet Alien (Europe) (En,Fr,De,Es,It)', '2005', 'Puzzle', 'Game Arts', '1', 'Cartoon Puzzle', 'Puzzle-adventure and strategy.', 'Use five different aliens to solve complex puzzles.', 'European release of the intergalactic puzzler.', 'Join the Pet Alien crew in this European multi-language edition. Solve over 80 brain-teasing levels by coordinating the skills of your alien friends in a vibrant and humorous 3D world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-pals---animal-doctor-usa', 'NDS', 'Pet Pals - Animal Doctor (USA)', '2007', 'Simulation', 'Playlogic Game Factory', '1', 'Veterinary Simulation', 'Veterinary medical simulation.', 'Diagnose and treat a variety of animal patients.', 'Realistic veterinary clinic simulation for the DS.', 'Pet Pals: Animal Doctor (USA) lets you perform surgeries and medical exams. Use the touch screen to operate medical tools, treat 35 different animal species, and manage your reputation as a top-tier vet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-pals---new-leash-on-life-usa', 'NDS', 'Pet Pals - New Leash on Life (USA)', '2009', 'Simulation', 'Playlogic Game Factory', '1', 'Veterinary Simulation', 'Animal rescue and training.', 'Rescue pets and train them for their new owners.', 'Adventure-focused pet care simulation.', 'Pet Pals: New Leash on Life (USA) combines medical treatment with social responsibility. Rehabilitate neglected animals and use the stylus to train them in basic commands before they are adopted.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-shop-monogatari-ds-japan', 'NDS', 'Pet Shop Monogatari DS (Japan)', '2008', 'Simulation', 'Amusement Vision', '1', 'Shop Management', 'Pet shop management simulation.', 'Run a successful pet store and care for animals.', 'Japanese pet shop management adventure.', 'Pet Shop Monogatari DS (Pet Shop Story) tasks you with matching the right pet to the right owner. Manage your shop''s inventory, groom the animals, and keep your customers happy to grow your business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-shop-monogatari-ds-2-japan', 'NDS', 'Pet Shop Monogatari DS 2 (Japan)', '2009', 'Simulation', 'Amusement Vision', '1', 'Shop Management', 'Pet shop management simulation.', 'Expand your shop and care for even more breeds.', 'The deeper and expanded pet shop sequel for Japan.', 'Pet Shop Monogatari DS 2 offers more animals and deeper customization. Interact with cute puppies and kittens using the touch screen and build a pet empire in this heartwarming Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-jacksons-king-kong---the-official-game-of-the-movie-europe-enfrdeesitnlsvnodafi-rev-1', 'NDS', 'Peter Jackson''s King Kong - The Official Game of the Movie (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi) (Rev 1)', '2005', 'Action Adventure', 'Ubisoft', '1', 'Movie Tie-In Action', '3D action-adventure.', 'Survive Skull Island and battle ancient creatures.', 'Epic movie-based action game (Revised Edition).', 'King Kong: The Official Game (Europe) Rev 1 lets you play as both Jack Driscoll and the mighty Kong. Fight off raptors with primitive weapons or use Kong''s brute strength to dominate the jungle in this cinematic 3D title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-jacksons-king-kong---the-official-game-of-the-movie-japan', 'NDS', 'Peter Jackson''s King Kong - The Official Game of the Movie (Japan)', '2005', 'Action Adventure', 'Ubisoft', '1', 'Movie Tie-In Action', '3D action-adventure.', 'Survive Skull Island and battle ancient creatures.', 'Japanese release of the King Kong movie game.', 'Experience the scale of Skull Island in Japan. This version features the same high-stakes survival gameplay, pitting man and ape against prehistoric threats in a technical showcase for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-jacksons-king-kong---the-official-game-of-the-movie-usa-enfrdeesitnlsvnodafi', 'NDS', 'Peter Jackson''s King Kong - The Official Game of the Movie (USA) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi)', '2005', 'Action Adventure', 'Ubisoft', '1', 'Movie Tie-In Action', '3D action-adventure.', 'Survive Skull Island and battle ancient creatures.', 'North American release of the King Kong game.', 'King Kong: The Official Game (USA) brings the 2005 film to life. Experience intense first-person survival segments and epic third-person brawls, utilizing the DS dual screens to manage your resources and map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('peter-pans-playground-europe', 'NDS', 'Peter Pan''s Playground (Europe)', '2006', 'Educational', 'Creat Studios', '1', 'Children Playground', 'Educational mini-games.', 'Play and learn with Peter Pan in Neverland.', 'Preschool activity collection for European kids.', 'Peter Pan''s Playground features classic characters like Tinker Bell and Captain Hook. Children can engage in simple drawing, counting, and logic puzzles designed to develop early learning skills in a magical setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petit-eva---evangelion@game-japan', 'NDS', 'Petit Eva - Evangelion@Game (Japan)', '2006', 'Adventure', 'Gainax', '1', 'Visual Novel', 'Mini-game collection and comedy.', 'Play wacky games with the "chibi" Evangelion cast.', 'Surreal comedy game based on the spin-off anime.', 'Petit Eva: Evangelion@Game features the cast of NGE in bizarre and funny situations. Complete school-themed mini-games and social scenarios in this lighthearted and satirical take on the legendary series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petit-fute-travel-and-play-france', 'NDS', 'Petit Fute Travel and Play (France)', '2009', 'Educational', 'Microids', '1', 'Travel Guide', 'Travel guide and puzzle.', 'Explore travel destinations through games and trivia.', 'Travel-themed educational game for French speakers.', 'Petit Fute Travel and Play (France) combines tourism info with puzzles. Learn about different countries and cultures while solving word and logic games in this unique digital travel guide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---bunnyz-usa-enfrdeesitnl', 'NDS', 'Petz - Bunnyz (USA) (En,Fr,De,Es,It,Nl)', '2006', 'Simulation', 'Ubisoft', '1', 'Pet Care Simulation', 'Pet care simulation.', 'Raise and play with a variety of cute rabbits.', 'Dedicated bunny care and training simulation.', 'Petz: Bunnyz (USA) lets you adopt and nurture different breeds of rabbits. Use the stylus to pet and feed them, and watch as they develop their own personalities and learn to recognize your voice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---catz---koneko-to-issho-ni-tanoshiku-asobou-japan', 'NDS', 'Petz - Catz - Koneko to Issho ni Tanoshiku Asobou (Japan)', '2006', 'Simulation', 'Ubisoft', '1', 'Pet Care Simulation', 'Pet care simulation.', 'Raise, groom, and play with your virtual kitten.', 'Japanese edition of the Catz series.', 'Petz: Catz (Japan) focuses on the bond between owner and kitten. Interact with your cat in a 3D home environment, providing toys and treats to keep your feline friend happy and healthy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---catz-2-usa-enfres', 'NDS', 'Petz - Catz 2 (USA) (En,Fr,Es)', '2007', 'Simulation', 'Ubisoft', '1', 'Pet Care Simulation', 'Pet care simulation.', 'Choose from various breeds and care for your kitten.', 'The second installment of the North American Catz series.', 'Petz: Catz 2 (USA) features more breeds and environments. Discover your kitten''s unique personality as you play together, and dress them up in adorable accessories in this expanded pet simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---catz-clan-usa-enfrdeesitnlsvnoda', 'NDS', 'Petz - Catz Clan (USA) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2007', 'Simulation', 'Ubisoft', '1', 'Pet Care Simulation', 'Pet care and family simulation.', 'Raise a whole family of cats and watch them grow.', 'Multi-generational cat care and breeding sim.', 'Petz: Catz Clan (USA) allows you to manage a group of cats. Watch them interact with each other, raise kittens, and explore a variety of indoor and outdoor environments in this feature-rich pet game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dog-superstar-europe-enfrdeesit', 'NDS', 'Petz - Dog Superstar (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Ubisoft', '1', 'Dog Training', 'Pet talent and fashion show.', 'Train your dog to become a world-famous superstar.', 'Competitive dog talent show simulation for Europe.', 'Petz: Dog Superstar (Europe) tasks you with training your pup for the spotlight. Master tricks and fashion shows to earn fame and unlock new items for your talented canine companion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dogz---koinu-to-issho-ni-tanoshiku-asobou-japan', 'NDS', 'Petz - Dogz - Koinu to Issho ni Tanoshiku Asobou (Japan)', '2006', 'Simulation', 'Ubisoft', '1', 'Dog Care Simulation', 'Pet care simulation.', 'Raise, groom, and play with your virtual puppy.', 'Japanese edition of the Dogz series.', 'Petz: Dogz (Japan) brings the joy of puppy ownership to the DS. Use the touch screen to pet your dog and the mic to give commands, creating a realistic and portable pet experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dogz-2-usa-enfrdeesit', 'NDS', 'Petz - Dogz 2 (USA) (En,Fr,De,Es,It)', '2007', 'Simulation', 'Ubisoft', '1', 'Dog Care Simulation', 'Pet care simulation.', 'Raise and train your puppy in a 3D world.', 'The second North American Dogz title.', 'Petz: Dogz 2 (USA) offers a wider variety of breeds and activities. From playing fetch in the park to entering beauty contests, it provides a comprehensive puppy-raising experience for dog lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dogz-fashion-usa', 'NDS', 'Petz - Dogz Fashion (USA)', '2008', 'Simulation', 'Ubisoft', '1', 'Dog Fashion Simulation', 'Pet care and fashion.', 'Dress up your dogs and enter fashion competitions.', 'Fashion-focused dog care simulation.', 'Petz: Dogz Fashion (USA) emphasizes style. Customize your puppies with hundreds of clothing items and accessories, then hit the runway to prove your dog has the best fashion sense in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dogz-pack-usa-enfrdeesitnlsvnoda', 'NDS', 'Petz - Dogz Pack (USA) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2008', 'Simulation', 'Ubisoft', '1', 'Dog Care Compilation', 'Pet care and group management.', 'Manage a whole pack of dogs and their social lives.', 'Multi-dog pack simulation for the USA.', 'Petz: Dogz Pack (USA) lets you raise several dogs at once. Observe their pack dynamics, manage their different personalities, and ensure every member of the group is well-fed and happy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dogz-talent-show-usa-enfrdeesit', 'NDS', 'Petz - Dogz Talent Show (USA) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Ubisoft', '1', 'Dog Talent Simulation', 'Pet talent and trick simulation.', 'Train your dogs for the ultimate talent competition.', 'Trick-focused dog simulation for the USA.', 'Petz: Dogz Talent Show (USA) focuses on precision and training. Teach your dogs complex tricks using the stylus and microphone to win trophies and become the top trainer in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---dolphinz-encounter-usa-enfres-ndsi-enhanced', 'NDS', 'Petz - Dolphinz Encounter (USA) (En,Fr,Es) (NDSi Enhanced)', '2010', 'Simulation', 'Ubisoft', '1', 'Dolphin Interaction', 'Marine life simulation.', 'Interact with and train dolphins in an ocean resort.', 'DSi Enhanced dolphin care and adventure game.', 'Petz: Dolphinz Encounter (USA) takes the series underwater. Use the DSi camera to bring items into the game as you rescue marine life, perform shows, and explore a beautiful aquatic world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---fantasy-europe-enfrdeesitnlsvnoda-ndsi-enhanced', 'NDS', 'Petz - Fantasy (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da) (NDSi Enhanced)', '2010', 'Simulation', 'Ubisoft', '1', 'Fantasy Pet Simulation', 'Fantasy pet simulation.', 'Hatch and raise legendary creatures like unicorns and dragons.', 'DSi Enhanced fantasy creature simulator.', 'Petz: Fantasy (Europe) lets you discover and care for 20 mythical pets. Use the DSi camera to unlock new items and nurture your magical friends as they grow from eggs to adults in floating islands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---fashion-stars-europe-enfrdeesitnl', 'NDS', 'Petz - Fashion Stars (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Simulation', 'Ubisoft', '1', 'Fashion Simulation', 'Fashion and career simulation.', 'Rise from a junior stylist to a global fashion star.', 'Modeling and styling simulation for Europe.', 'Petz: Fashion Stars (Europe) puts you in the glitzy world of high fashion. Design outfits, manage your model''s photoshoots, and climb the ranks of the industry in this stylish career sim.');
