INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---hamsterz-life-2-usa', 'NDS', 'Petz - Hamsterz Life 2 (USA)', '2011', 'Simulation', 'Ubisoft', '1', 'Pet Care Simulation', 'Hamster care simulation.', 'Build a home and raise a happy hamster family.', 'Cozy hamster life simulator for North America.', 'Petz: Hamsterz Life 2 (USA) expands on the pet care formula. Decorate cages, breed different varieties, and explore a world through the eyes of your tiny, furry friends with touch-screen interaction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('petz---hamsterz-superstars-usa-enfrdeesitnlsvnoda', 'NDS', 'Petz - Hamsterz Superstars (USA) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2011', 'Simulation', 'Ubisoft', '1', 'Pet Care Simulation', 'Hamster care and training.', 'Lead your hamster to victory in talent shows.', 'North American release of Hamster Superstar.', 'Put your pet in the spotlight with Petz: Hamsterz Superstars (USA). Focus on training and grooming to ensure your hamster is the most talented and stylish contestant on the stage.');
