INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---best-friends---mein-pferd-germany', 'NDS', 'Pferd & Pony - Best Friends - Mein Pferd (Germany)', '2008', 'Simulation', 'Independent Arts', '1', 'Horse Care Simulation', 'Horse care and friendship.', 'Bond with your horse and become best friends.', 'German horse care and riding simulation.', 'Mein Pferd (Germany) is part of the "Pferd & Pony" series. Focus on the emotional bond with your animal through daily grooming, feeding, and peaceful rides through the countryside.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---die-reitakademie---das-entscheidende-turnier-europe-ende', 'NDS', 'Pferd & Pony - Die Reitakademie - Das Entscheidende Turnier (Europe) (En,De)', '2009', 'Simulation', 'Independent Arts', '1', 'Horse Riding Simulation', 'Equestrian competition.', 'Win the final tournament of the riding academy.', 'Professional riding simulation and tournament.', 'Die Reitakademie: Das Entscheidende Turnier (Europe) is for serious fans. Master dressage and jumping to win the ultimate prize in this German-developed equestrian hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---die-reitakademie-europe-ende', 'NDS', 'Pferd & Pony - Die Reitakademie (Europe) (En,De)', '2008', 'Simulation', 'Independent Arts', '1', 'Horse Riding Simulation', 'Equestrian academy simulation.', 'Train at a prestigious academy and become a pro rider.', 'Academic horse riding simulation for Europe.', 'Die Reitakademie (Europe) follows your journey as a student. Manage your studies and your horse''s training to climb the ranks of the academy and enter major competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---mein-gestuet---ein-leben-fuer-die-pferde-europe-enfrdeesit', 'NDS', 'Pferd & Pony - Mein Gestuet - Ein Leben fuer die Pferde (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Horse Breeding Simulation', 'Stud farm management.', 'Run your own stud farm and breed champion horses.', 'Business and breeding horse simulation for Europe.', 'Mein Gestuet (Europe) offers a deep management experience. Build new stables, attract guests, and breed the finest horses to create a world-renowned equestrian estate.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---mein-gestuet-germany-ende', 'NDS', 'Pferd & Pony - Mein Gestuet (Germany) (En,De)', '2008', 'Simulation', 'Independent Arts', '1', 'Horse Breeding Simulation', 'Stud farm management.', 'Run your own stud farm and breed champion horses.', 'German release of the stud farm manager.', 'Experience the challenge of managing a horse farm in Germany. Mein Gestuet focuses on the balance between professional breeding and the daily care required for healthy animals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferd-&-pony---mein-westernpferd-europe-ende', 'NDS', 'Pferd & Pony - Mein Westernpferd (Europe) (En,De)', '2009', 'Simulation', 'Independent Arts', '1', 'Western Horse Simulation', 'Western riding simulation.', 'Master the art of Western-style horse riding.', 'Specialized Western equestrian simulation.', 'Mein Westernpferd (Europe) focuses on barrel racing and reining. Learn the unique techniques of Western riding and compete in themed events to become a rodeo star.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pferdefreunde-puzzle---echter-puzzlespass-fuer-unterwegs-europe-enfrdeesit', 'NDS', 'Pferdefreunde Puzzle - Echter Puzzlespass fuer Unterwegs (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Tivola', '1', 'Puzzle', 'Jigsaw puzzle.', 'Complete various horse-themed puzzles.', 'Horse-themed puzzle collection for Europe.', 'Pferdefreunde Puzzle offers dozens of high-quality images of horses and foals. Choose your difficulty level and assemble puzzles using the stylus in this relaxing, portable experience for animal lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-0-europe', 'NDS', 'Phantasy Star 0 (Europe)', '2009', 'Role-Playing Game', 'Sega', '1', 'Anime', 'Action JRPG.', 'Explore ruins and defeat enemies to uncover Earth''s past.', 'SEGA''s classic online-capable JRPG for Europe.', 'Phantasy Star 0 (Europe) brings the legendary sci-fi RPG to DS. Choose from 3 races and multiple classes, featuring a robust single-player story and the "Visual Chat" system for local or online cooperative play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-0-japan', 'NDS', 'Phantasy Star 0 (Japan)', '2009', 'Role-Playing Game', 'Sega', '1', 'Anime', 'Action JRPG.', 'Explore ruins and defeat enemies to uncover Earth''s past.', 'Original Japanese release of Phantasy Star 0.', 'Phantasy Star 0 (Japan) features fast-paced real-time combat and a massive array of loot. Customize your character and explore beautifully rendered 3D environments in this portable entry of the iconic series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-0-usa', 'NDS', 'Phantasy Star 0 (USA)', '2009', 'Role-Playing Game', 'Sega', '1', 'Anime', 'Action JRPG.', 'Explore ruins and defeat enemies to uncover Earth''s past.', 'North American release of Phantasy Star 0.', 'Dive into the sci-fi adventure of Phantasy Star 0 (USA). Master the touch-screen combat and team up with friends to tackle massive bosses in one of the most technically impressive RPGs on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb---2-disney-games-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Phineas and Ferb - 2 Disney Games (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2011', 'Action / Adventure', 'Altron', '1', 'Cartoon', 'Action-adventure & Mini-games.', 'Complete various inventions and missions with the boys.', 'Disney double-pack featuring Phineas and Ferb.', 'This Phineas and Ferb 2-in-1 collection includes their greatest DS hits. Build wacky inventions, play as Agent P, and enjoy NDSi enhanced features in this multi-language European bundle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb---across-the-2nd-dimension-europe-enfrdeesitnl', 'NDS', 'Phineas and Ferb - Across the 2nd Dimension (Europe) (En,Fr,De,Es,It,Nl)', '2011', 'Action / Platformer', 'High Impact Games', '1', 'Cartoon', 'Action-adventure & Platformer.', 'Navigate through alternate dimensions to stop Doofenshmirtz.', 'Movie-based interdimensional adventure for Europe.', 'Across the 2nd Dimension (Europe) lets you play as Phineas, Ferb, and Perry. Use gadgets like the Carbonator and Ninja Gloves to battle through 5 alternate worlds in this action-packed tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb---across-the-2nd-dimension-usa-enfres', 'NDS', 'Phineas and Ferb - Across the 2nd Dimension (USA) (En,Fr,Es)', '2011', 'Action / Platformer', 'High Impact Games', '1', 'Cartoon', 'Action-adventure & Platformer.', 'Navigate through alternate dimensions to stop Doofenshmirtz.', 'North American release of the 2nd Dimension.', 'Join the resistance in Phineas and Ferb (USA). Battle across dimensions, upgrade your gadgets, and stop the evil Dr. Doofenshmirtz''s alternate-reality army in this colorful and humorous platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb---quest-for-cool-stuff-usa', 'NDS', 'Phineas and Ferb - Quest for Cool Stuff (USA)', '2013', 'Action / Adventure', 'Behaviour Interactive', '1', 'Cartoon', 'Action-adventure & Platformer.', 'Explore your backyard and beyond to find cool stuff.', 'Backyard exploration and gadget-building fun.', 'Quest for Cool Stuff (USA) tasks the brothers with building the ultimate "Cool Stuff" museum. Explore diverse environments and find hidden treasures using the boys'' latest crazy inventions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb---ride-again-europe-endeesitnl-ndsi-enhanced', 'NDS', 'Phineas and Ferb - Ride Again (Europe) (En,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Action / Platformer', 'High Impact Games', '1', 'Cartoon', 'Action-adventure & Racing.', 'Race through various tracks and stop evil plots.', 'NDSi Enhanced sequel to the original game.', 'Phineas and Ferb: Ride Again (Europe) features improved vehicle customization and new levels. Play as Perry in secret agent missions or race custom-built karts in this high-energy sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb---ride-again-usa-enes-ndsi-enhanced', 'NDS', 'Phineas and Ferb - Ride Again (USA) (En,Es) (NDSi Enhanced)', '2010', 'Action / Platformer', 'High Impact Games', '1', 'Cartoon', 'Action-adventure & Racing.', 'Race through various tracks and stop evil plots.', 'North American NDSi Enhanced sequel.', 'Get ready for more summer fun in Ride Again (USA). Build even crazier vehicles and take on new challenges, utilizing the NDSi camera for extra features in this fan-favorite adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb-europe-enfrdeesit', 'NDS', 'Phineas and Ferb (Europe) (En,Fr,De,Es,It)', '2009', 'Action / Platformer', 'Altron', '1', 'Cartoon', 'Action-adventure & Mini-games.', 'Build a massive rollercoaster and complete challenges.', 'The first Phineas and Ferb game for Europe.', 'Phineas and Ferb (Europe) follows the boys as they try to build the world''s best rollercoaster. Play as Perry to thwart Doofenshmirtz and help the boys avoid getting busted by Candace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phineas-and-ferb-usa', 'NDS', 'Phineas and Ferb (USA)', '2009', 'Action / Platformer', 'Altron', '1', 'Cartoon', 'Action-adventure & Mini-games.', 'Build a massive rollercoaster and complete challenges.', 'North American release of the first game.', 'Summer lasts forever in Phineas and Ferb (USA). Use the stylus to construct complex rides and engage in stealth missions as Agent P in this faithful adaptation of the hit Disney show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---justice-for-all-europe-enfrde', 'NDS', 'Phoenix Wright - Ace Attorney - Justice for All (Europe) (En,Fr,De)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Defend your clients in court and find the true killer.', 'The second Phoenix Wright title (En,Fr,De).', 'Justice for All (Europe) continues the saga of Phoenix Wright. Introduce the "Psyche-Lock" mechanic to break down witness secrets and navigate four intense new cases in this legal thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---justice-for-all-europe-esit', 'NDS', 'Phoenix Wright - Ace Attorney - Justice for All (Europe) (Es,It)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Defend your clients in court and find the true killer.', 'Spanish/Italian localized version of Justice for All.', '¡Protesto! (Objection!) Experience the high-stakes legal battles of Justice for All in Spanish and Italian. Piece together evidence and cross-examine eccentric witnesses to save your clients.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---justice-for-all-usa', 'NDS', 'Phoenix Wright - Ace Attorney - Justice for All (USA)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Defend your clients in court and find the true killer.', 'North American release of Justice for All.', 'Phoenix Wright returns in Justice for All (USA). With higher stakes and the introduction of Maya''s cousin Pearl, you must use your logic and the new "Magatama" to uncover lies in the courtroom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---trials-and-tribulations-europe', 'NDS', 'Phoenix Wright - Ace Attorney - Trials and Tribulations (Europe)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Uncover the past and win the ultimate trial.', 'The epic conclusion to the original trilogy.', 'Trials and Tribulations (Europe) features the final showdown between Phoenix and his rivals. Play through cases in both the present and the past to uncover the truth behind the Fey family legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---trials-and-tribulations-europe-esit', 'NDS', 'Phoenix Wright - Ace Attorney - Trials and Tribulations (Europe) (Es,It)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Uncover the past and win the ultimate trial.', 'Spanish/Italian release of Trials and Tribulations.', 'The legal drama reaches its peak in this localized European edition. Help Phoenix and Mia Fey navigate their most personal cases yet in this acclaimed visual novel masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---trials-and-tribulations-europe-frde', 'NDS', 'Phoenix Wright - Ace Attorney - Trials and Tribulations (Europe) (Fr,De)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Uncover the past and win the ultimate trial.', 'French/German release of Trials and Tribulations.', 'Solve the mysteries of the past in this French and German edition. Featuring a gripping script and memorable characters, this title concludes the initial Phoenix Wright arc in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney---trials-and-tribulations-usa', 'NDS', 'Phoenix Wright - Ace Attorney - Trials and Tribulations (USA)', '2007', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Uncover the past and win the ultimate trial.', 'North American release of the trilogy finale.', 'Trials and Tribulations (USA) is widely considered the best in the series. Battle the mysterious Godot in court and solve a decade-spanning mystery in this emotionally charged conclusion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney-europe-deesit', 'NDS', 'Phoenix Wright - Ace Attorney (Europe) (De,Es,It)', '2005', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Investigate crime scenes and win courtroom battles.', 'The game that started the legal drama craze (De,Es,It).', 'Phoenix Wright: Ace Attorney (Europe) introduces the legendary defense attorney. Use the touch screen to present evidence and shout "Objection!" in this unique and addictive investigation game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney-europe-enfr', 'NDS', 'Phoenix Wright - Ace Attorney (Europe) (En,Fr)', '2005', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Investigate crime scenes and win courtroom battles.', 'English/French release of the first Ace Attorney.', 'Join Phoenix Wright in his first four cases, plus a DS-exclusive fifth chapter that utilizes the microphone and touch screen for forensic investigation and 3D evidence analysis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phoenix-wright---ace-attorney-usa', 'NDS', 'Phoenix Wright - Ace Attorney (USA)', '2005', 'Adventure / Visual Novel', 'Capcom', '1', 'Anime', 'Legal drama / Visual novel.', 'Investigate crime scenes and win courtroom battles.', 'North American release of Ace Attorney.', 'Step into the courtroom in Phoenix Wright: Ace Attorney (USA). This classic visual novel blends humor, mystery, and high-stakes drama as you fight for justice for your innocent clients.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pic-pic---toku-to-e-ni-naru-3-tsu-no-puzzle-japan', 'NDS', 'Pic Pic - Toku to E ni Naru 3-tsu no Puzzle (Japan)', '2008', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle.', 'Solve three different types of logic drawing puzzles.', 'Japanese logic puzzle collection.', 'Pic Pic features three addictive modes: Maze Paint, Magipix, and Drawing. Connect dots and fill in grids to reveal hidden images in this minimalist and satisfying Japanese puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pic-pic-europe', 'NDS', 'Pic Pic (Europe)', '2008', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle.', 'Solve three different types of logic drawing puzzles.', 'European release of the minimalist puzzle hit.', 'Pic Pic (Europe) offers hundreds of logic challenges. With its clean art style and intuitive touch controls, it’s a perfect "pick-up-and-play" title for fans of Sudoku and Picross.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pic-pic-france', 'NDS', 'Pic Pic (France)', '2008', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle.', 'Solve three different types of logic drawing puzzles.', 'French localized version of Pic Pic.', 'Solve intricate logic puzzles in French. Use your deductive skills to uncover hidden pictures across three unique game modes that will test your spatial reasoning and patience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pic-pic-italy', 'NDS', 'Pic Pic (Italy)', '2008', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle.', 'Solve three different types of logic drawing puzzles.', 'Italian localized version of Pic Pic.', 'Experience the brain-teasing fun of Pic Pic in Italian. Each mode offers a different perspective on the "drawing by logic" genre, providing hours of calm, intellectual gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-3d-europe-enfrdeesit', 'NDS', 'Picross 3D (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'HAL Laboratory', '1', 'Puzzle', '3D logic puzzle.', 'Chisel away blocks to reveal a 3D object.', 'The 3D evolution of the Picross series for Europe.', 'Picross 3D (Europe) takes the puzzle genre into a new dimension. Use logic to determine which blocks to keep and which to smash, uncovering over 350 hidden 3D models in this addictive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-3d-usa-enfres', 'NDS', 'Picross 3D (USA) (En,Fr,Es)', '2009', 'Puzzle', 'HAL Laboratory', '1', 'Puzzle', '3D logic puzzle.', 'Chisel away blocks to reveal a 3D object.', 'North American release of Picross 3D.', 'Think in 3D with Picross 3D (USA). Featuring a deep tutorial and hundreds of puzzles ranging from easy to mind-bending, it’s a brilliant reimagining of the classic nonogram formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-ds-europe-enfrdeesit', 'NDS', 'Picross DS (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle (Nonogram).', 'Fill in the grid based on numbers to reveal a picture.', 'The definitive 2D Picross experience for Europe.', 'Picross DS (Europe) features over 300 puzzles. Use the stylus for precise grid filling, participate in "Daily Picross" to track your skill, and create your own puzzles to share with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-ds-japan', 'NDS', 'Picross DS (Japan)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle (Nonogram).', 'Fill in the grid based on numbers to reveal a picture.', 'Original Japanese release of Picross DS.', 'Picross DS (Japan) brought the classic "Mario''s Picross" gameplay to the modern era. With various difficulty levels and classic Nintendo-themed puzzles, it’s a must-have for logic game enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-ds-korea', 'NDS', 'Picross DS (Korea)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle (Nonogram).', 'Fill in the grid based on numbers to reveal a picture.', 'Korean localized version of Picross DS.', 'Enjoy the calming and rewarding logic of Picross in Korean. This version includes all the features of the original, including the Nintendo Wi-Fi Connection modes for downloading new puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picross-ds-usa-enfres', 'NDS', 'Picross DS (USA) (En,Fr,Es)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Logic puzzle (Nonogram).', 'Fill in the grid based on numbers to reveal a picture.', 'North American release of Picross DS.', 'Picross DS (USA) is the ultimate version of the classic nonogram. Featuring a clean interface, robust tutorial, and the ability to play against others, it’s the gold standard for handheld puzzle games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pictionary-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Pictionary (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2009', 'Board Game / Puzzle', 'Griptonite Games', '1', 'Board Game', 'Drawing and guessing.', 'Draw clues on the touch screen for others to guess.', 'Digital version of the classic party game (NDSi Enhanced).', 'Pictionary (Europe) brings the famous board game to DS. Use the stylus to sketch clues while your friends guess. The NDSi features allow you to snap photos and use them as drawing backgrounds for extra fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picto-image-ds-japan', 'NDS', 'Picto Image DS (Japan)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Drawing and guessing.', 'Sketch images and guess what others have drawn.', 'Japanese version of the "Sketch and Guess" game.', 'Picto Image DS is a creative party game for Japan. It utilizes the DS''s local wireless to let groups of friends play together, challenging their artistic skills and intuition in a fun, quick-play format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pictoimage---sketch-and-guess-on-your-ds!-europe-enfrdeesit', 'NDS', 'PictoImage - Sketch and Guess on Your DS! (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Drawing and guessing.', 'Draw images and guess their meaning to win.', 'Creative sketch-based party game for Europe.', 'PictoImage (Europe) features hundreds of words to draw. Play solo through various modes or challenge up to 8 friends via wireless play, even with just one game card using the "Download Play" feature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pictoimage-usa-enfrdeesit', 'NDS', 'PictoImage (USA) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Drawing and guessing.', 'Draw images and guess their meaning to win.', 'North American release of the sketching game.', 'Unleash your inner artist in PictoImage (USA). The game tracks your drawing speed and accuracy, offering a wide variety of tools and colors to make your sketches come to life on the dual screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('picture-puzzle-collection-europe-enfrdeesitnl', 'NDS', 'Picture Puzzle Collection (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Puzzle / Compilation', 'Various', '1', 'Puzzle', 'Logic puzzle (Nonogram).', 'Solve grid-based puzzles to reveal hidden pictures.', 'Clean and accessible nonogram collection.', 'Picture Puzzle Collection (Europe) offers hundreds of logic challenges. Similar to Picross, players use numbers to fill in squares, slowly revealing pixel-art images in a relaxing, brain-teasing environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pimp-my-ride---street-racing-europe-enfrdeesit', 'NDS', 'Pimp My Ride - Street Racing (Europe) (En,Fr,De,Es,It)', '2006', 'Racing', 'Eutechnyx', '1', 'Realistic', 'Racing and car customization.', 'Win street races and "pimp" your ride with upgrades.', 'Crossover of street racing and the hit MTV show.', 'Pimp My Ride: Street Racing (Europe) tasks you with winning races to earn cash for crazy car modifications. Customize your car''s look and performance to become the king of the urban racing scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pimp-my-ride---street-racing-usa-enfr', 'NDS', 'Pimp My Ride - Street Racing (USA) (En,Fr)', '2006', 'Racing', 'Eutechnyx', '1', 'Realistic', 'Racing and car customization.', 'Win street races and "pimp" your ride with upgrades.', 'North American release of the MTV racing game.', 'Burn rubber in Pimp My Ride (USA). This version features high-speed arcade racing combined with a deep customization system, allowing you to turn basic cars into flashy, high-performance machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-deluxe-europe-enfrdeesit', 'NDS', 'Pinball Deluxe (Europe) (En,Fr,De,Es,It)', '2006', 'Pinball', 'Gamebridge', '1', 'Arcade', 'Pinball simulation.', 'Achieve high scores on various themed pinball tables.', 'Classic pinball action for the Nintendo DS.', 'Pinball Deluxe (Europe) features multiple tables with unique themes and physics. Use the triggers to control the flippers and master skill shots to unlock bonuses and climb the global high-score leaderboard.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ping-pals-europe', 'NDS', 'Ping Pals (Europe)', '2006', 'Communication / Social', 'Jupiter', '1', 'Casual', 'Social chat and mini-games.', 'Chat with friends and play mini-games using avatars.', 'Early social networking and chat tool for DS.', 'Ping Pals (Europe) was designed to turn the DS into a communication device. Create a custom avatar, trade items, and chat with nearby friends via local wireless in a fun, stylized environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ping-pals-france', 'NDS', 'Ping Pals (France)', '2006', 'Communication / Social', 'Jupiter', '1', 'Casual', 'Social chat and mini-games.', 'Chat with friends and play mini-games using avatars.', 'French localized version of the social chat game.', 'Experience the social world of Ping Pals in French. Beyond chatting, players can participate in variety of mini-games to earn "Ping Points" to buy new clothes and accessories for their avatars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ping-pals-germany', 'NDS', 'Ping Pals (Germany)', '2006', 'Communication / Social', 'Jupiter', '1', 'Casual', 'Social chat and mini-games.', 'Chat with friends and play mini-games using avatars.', 'German localized version of the social chat game.', 'Connect with friends in German-speaking territories. Ping Pals offers a safe and colorful way for kids to message each other and express their personality through deep avatar customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ping-pals-usa', 'NDS', 'Ping Pals (USA)', '2006', 'Communication / Social', 'Jupiter', '1', 'Casual', 'Social chat and mini-games.', 'Chat with friends and play mini-games using avatars.', 'North American release of the social tool.', 'Ping Pals (USA) maximize the DS''s wireless capabilities. It features a large selection of items to unlock and trade, making it a digital hangout spot for gamers in the mid-2000s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pingu-no-waku-waku-carnival!-japan', 'NDS', 'Pingu no Waku Waku Carnival! (Japan)', '2006', 'Action / Mini-Games', 'Asmik Ace', '1', 'Cartoon', 'Party games and mini-games.', 'Help Pingu and friends during the carnival.', 'Adorable mini-game collection based on the claymation.', 'Pingu no Waku Waku Carnival! (Japan) captures the charm of the TV series. Complete various tasks like fishing, cooking, and racing to ensure the carnival is a success for Pingu and his family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinky-street---kira-kira-music-hour---sinnaneun-dance-battle-korea', 'NDS', 'Pinky Street - Kira Kira Music Hour - Sinnaneun Dance Battle (Korea)', '2008', 'Music / Rhythm', 'Tose', '1', 'Anime', 'Rhythm and fashion.', 'Win dance battles and customize your Pinky character.', 'Korean version of the stylish rhythm game.', 'Kira Kira Music Hour brings the Pinky:St fashion dolls to life. Use the stylus to hit notes in rhythm battles and earn new outfits to create the most stylish character in Korea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinky-street---kira-kira-music-hour-japan', 'NDS', 'Pinky Street - Kira Kira Music Hour (Japan)', '2008', 'Music / Rhythm', 'Tose', '1', 'Anime', 'Rhythm and fashion.', 'Win dance battles and customize your Pinky character.', 'The first Pinky:St rhythm game for Japan.', 'Pinky Street: Kira Kira Music Hour features catchy J-pop tunes and a deep wardrobe system. Win "Dance Battles" against rivals to unlock rare clothing pieces and accessories for your Pinky doll.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinky-street---kira-kira-music-night-japan', 'NDS', 'Pinky Street - Kira Kira Music Night (Japan)', '2009', 'Music / Rhythm', 'Tose', '1', 'Anime', 'Rhythm and fashion.', 'Perform rhythmic dances and explore the night life.', 'The "Night" themed sequel to the Pinky rhythm hit.', 'Kira Kira Music Night (Japan) offers more challenging songs and a new nighttime aesthetic. Continue your fashion journey with even more customization options and refined rhythm-action gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pipe-mania-europe-enfrdeesitnl', 'NDS', 'Pipe Mania (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Puzzle', 'The Code Monkeys', '1', 'Puzzle', 'Strategy and puzzle.', 'Connect pipes to transport liquid before time runs out.', 'Modern remake of the classic "Pipe Dream" puzzle.', 'Pipe Mania (Europe) features over 300 levels across multiple modes. Plan your plumbing carefully to prevent leaks and master the flow in this addictive, high-pressure strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pipe-mania-usa-enfr', 'NDS', 'Pipe Mania (USA) (En,Fr)', '2008', 'Puzzle', 'The Code Monkeys', '1', 'Puzzle', 'Strategy and puzzle.', 'Connect pipes to transport liquid before time runs out.', 'North American release of the pipe-laying puzzler.', 'Put your logic to the test in Pipe Mania (USA). With new themes, refined mechanics, and challenging boss levels, it''s a comprehensive update to one of the most famous puzzle formulas in gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pippa-funnell-europe-enfrdeesnl', 'NDS', 'Pippa Funnell (Europe) (En,Fr,De,Es,Nl)', '2007', 'Simulation / Adventure', 'Tate Interactive', '1', 'Realistic', 'Horse care and adventure.', 'Train your horse and win equestrian competitions.', 'Horse riding simulation featuring Pippa Funnell.', 'Pippa Funnell (Europe) lets you manage a stable and bond with your horse. Master dressage, cross-country, and show jumping while managing your horse''s health and happiness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pippa-funnell-europe-enfrdees', 'NDS', 'Pippa Funnell (Europe) (En,Fr,De,Es)', '2007', 'Simulation / Adventure', 'Tate Interactive', '1', 'Realistic', 'Horse care and adventure.', 'Train your horse and win equestrian competitions.', 'Alternative European edition of the horse sim.', 'This multi-language version of Pippa Funnell provides the same deep equestrian experience, focusing on the realistic training techniques endorsed by the world-famous rider.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pippa-funnell-2---farm-adventures-europe-enfrdeesitnlsvnoda', 'NDS', 'Pippa Funnell 2 - Farm Adventures (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Simulation / Adventure', 'Tate Interactive', '1', 'Realistic', 'Horse care and adventure.', 'Manage a farm and raise foals in the countryside.', 'Adventure-focused horse sequel for Europe.', 'Pippa Funnell 2: Farm Adventures expands the series with new farming mechanics. Help your grandfather manage the farm, rescue horses in need, and explore a vast rural environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates---duels-on-the-high-seas-europe-enfrdeesit', 'NDS', 'Pirates - Duels on the High Seas (Europe) (En,Fr,De,Es,It)', '2008', 'Action / Strategy', 'Akella', '1', 'Realistic', 'Action and ship combat.', 'Command a pirate ship and defeat your rivals.', 'Top-down naval combat and pirate adventure.', 'Pirates: Duels on the High Seas (Europe) features intense ship-to-ship battles. Customize your vessel, recruit a crew, and explore dangerous waters in a quest for gold and legendary treasures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates---duels-on-the-high-seas-usa', 'NDS', 'Pirates - Duels on the High Seas (USA)', '2008', 'Action / Strategy', 'Akella', '1', 'Realistic', 'Action and ship combat.', 'Command a pirate ship and defeat your rivals.', 'North American release of the naval combat game.', 'Set sail in Pirates: Duels on the High Seas (USA). Use the dual screens to manage your map and combat, taking down rival captains in a series of challenging naval skirmishes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-boarding-europe-enfrdeesnl', 'NDS', 'Pirates Boarding (Europe) (En,Fr,De,Es,Nl)', '2007', 'Action / Adventure', 'Hitmaker', '1', 'Realistic', 'Action and mini-games.', 'Board enemy ships and win sword-fighting duels.', 'Pirate-themed action and platforming game.', 'Pirates Boarding (Europe) focuses on the excitement of ship invasions. Swing across ropes, engage in stylus-based sword fights, and loot enemy galleons in this high-seas adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---at-worlds-end-europe-enfrdeesitnl', 'NDS', 'Pirates of the Caribbean - At World''s End (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Action / Adventure', 'Eurocom', '1', 'Movie', '3D action-adventure.', 'Follow Jack Sparrow''s quest to defeat Davy Jones.', 'The epic movie tie-in for European fans.', 'Pirates of the Caribbean: At World''s End (Europe) features fast-paced combat and platforming. Play as Jack, Will, and Elizabeth, using unique moves and secondary weapons to survive the supernatural threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---at-worlds-end-japan', 'NDS', 'Pirates of the Caribbean - At World''s End (Japan)', '2007', 'Action / Adventure', 'Griptonite Games', '1', 'Movie', '3D action-adventure.', 'Follow Jack Sparrow''s quest to defeat Davy Jones.', 'Japanese release of the movie adventure.', 'Experience the blockbuster action of At World''s End in Japan. This version features impressive 3D character models and environments, capturing the cinematic feel of the Disney franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---at-worlds-end-usa-enfrdeesitnl', 'NDS', 'Pirates of the Caribbean - At World''s End (USA) (En,Fr,De,Es,It,Nl)', '2007', 'Action / Adventure', 'Eurocom', '1', 'Movie', '3D action-adventure.', 'Follow Jack Sparrow''s quest to defeat Davy Jones.', 'North American release of At World''s End.', 'Battle across diverse locations in Pirates of the Caribbean (USA). Master the "Dueling" system and solve environmental puzzles to thwart the plans of the East India Trading Company.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---dead-mans-chest-europe-enfrdeesit', 'NDS', 'Pirates of the Caribbean - Dead Man''s Chest (Europe) (En,Fr,De,Es,It)', '2006', 'Action / Adventure', 'Amaze Entertainment', '1', 'Movie', '2D side-scrolling action.', 'Escape the Kraken and recover the Dead Man''s Chest.', 'Action-platformer based on the second movie.', 'Dead Man''s Chest (Europe) offers classic 2D combat. Fight through jungle and cave levels as Jack Sparrow, utilizing various gadgets and sword combos to defeat the cursed crew of the Flying Dutchman.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---dead-mans-chest-japan', 'NDS', 'Pirates of the Caribbean - Dead Man''s Chest (Japan)', '2006', 'Action / Adventure', 'Amaze Entertainment', '1', 'Movie', '2D side-scrolling action.', 'Escape the Kraken and recover the Dead Man''s Chest.', 'Japanese release of Dead Man''s Chest.', 'Navigate the dangers of the Caribbean in this Japanese edition. The game features vibrant sprites and challenging boss fights, including a massive encounter with the legendary Kraken.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pirates-of-the-caribbean---dead-mans-chest-usa-enfrdeesit', 'NDS', 'Pirates of the Caribbean - Dead Man''s Chest (USA) (En,Fr,De,Es,It)', '2006', 'Action / Adventure', 'Amaze Entertainment', '1', 'Movie', '2D side-scrolling action.', 'Escape the Kraken and recover the Dead Man''s Chest.', 'North American release of Dead Man''s Chest.', 'Dead Man''s Chest (USA) brings the humor and action of the film to the DS. Collect hidden treasures and upgrade your skills to survive the quest for Davy Jones''s heart.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('piraty-karibskogo-morja---na-kraju-sveta-russia', 'NDS', 'Piraty Karibskogo Morja - Na Kraju Sveta (Russia)', '2007', 'Action / Adventure', 'Unknown', '1', 'Movie', '3D action-adventure.', 'Follow Jack Sparrow''s quest to defeat Davy Jones.', 'Russian localized version of At World''s End.', 'The pirate epic comes to Russia with full localization. Experience the same high-seas adventure and 3D combat as Jack Sparrow in his quest to unite the Pirate Lords.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pixeline---magi-i-pixieland-denmark', 'NDS', 'Pixeline - Magi i Pixieland (Denmark)', '2007', 'Educational / Adventure', 'Knudsen', '1', 'Educational', 'Adventure and mini-games.', 'Explore Pixieland and help the magical residents.', 'Danish educational adventure for children.', 'Pixeline: Magi i Pixieland (Denmark) features the popular Danish mascot. Solve puzzles and complete mini-games that encourage creativity and logic in a colorful, fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pixeline-og-droemmespejlet-denmark', 'NDS', 'Pixeline og Droemmespejlet (Denmark)', '2008', 'Educational / Adventure', 'Knudsen', '1', 'Educational', 'Adventure and mini-games.', 'Find the pieces of the Dream Mirror to save the land.', 'Story-driven educational adventure for Denmark.', 'Pixeline og Droemmespejlet follows Pixeline on a magical quest. The game blends entertainment with early learning, focusing on problem-solving and social interaction for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pixeline-skolehjaelp---dansk---kaos-i-kommakoebing-denmark', 'NDS', 'Pixeline Skolehjaelp - Dansk - Kaos i Kommakoebing (Denmark)', '2008', 'Educational', 'Edugames', '1', 'Educational', 'Educational language study.', 'Solve mysteries using Danish grammar and spelling.', 'Danish language trainer for school-age kids.', 'Kaos i Kommakoebing makes learning Danish fun. Students help Pixeline restore order to a town by completing exercises on punctuation, word classes, and sentence structure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pixeline-skolehjaelp---matematik---taager-over-talstrup-denmark', 'NDS', 'Pixeline Skolehjaelp - Matematik - Taager over Talstrup (Denmark)', '2009', 'Educational', 'Edugames', '1', 'Educational', 'Educational math study.', 'Solve math problems to clear the fog over Talstrup.', 'Danish mathematics trainer for primary students.', 'Taager over Talstrup focuses on core math skills. Join Pixeline to solve addition, subtraction, and logic puzzles, helping children build confidence in their mathematical abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-51---the-game-europe-enfrdeesit', 'NDS', 'Planet 51 - The Game (Europe) (En,Fr,De,Es,It)', '2009', 'Action / Adventure', 'Pyro Studios', '1', 'Cartoon', 'Creature collection RPG.', 'Become the Champion of the Unova region.', 'North American release of Pokémon Black.', 'Pokémon Black Version (USA) features the legendary Zekrom. It introduced a completely new cast of 156 Pokémon and dynamic seasons, revolutionizing the series with a more mature storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-51---the-game-usa-enfres', 'NDS', 'Planet 51 - The Game (USA) (En,Fr,Es)', '2009', 'Action / Adventure', 'Pyro Studios', '1', 'Cartoon', 'Creature collection RPG.', 'Become the Champion of the Unova region.', 'European release of Pokémon Black.', 'Experience the Unova region in multiple languages. Pokémon Black (Europe) includes the C-Gear for wireless connectivity and the innovative Triple Battles, offering a fresh tactical challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-puzzle-league-usa', 'NDS', 'Planet Puzzle League (USA)', '2007', 'Puzzle', 'Nintendo', '2', 'Puzzle', 'Creature collection RPG.', 'Conquer Sinnoh and complete the Pokédex.', 'North American release of Pokémon Diamond.', 'Pokémon Diamond Version (USA) brought Pokémon into the 3D era on DS. Featuring the legendary Dialga, it introduced the Global Trade Station (GTS) and the underground exploration system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-rescue---animal-emergency-europe-enfrdeesitnlptsvnoda', 'NDS', 'Planet Rescue - Animal Emergency (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da)', '2009', 'Simulation / Educational', 'Independent', '1', 'Casual', 'Creature collection RPG.', 'Conquer Sinnoh and complete the Pokédex.', 'European release of Pokémon Diamond.', 'Pokémon Diamond (Europe) lets you explore the vast Sinnoh region. Master the new physical/special move split and use the Pokétch on the bottom screen to manage your adventure in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-rescue---endangered-island-europe-enfrdeesitnlsvnoda', 'NDS', 'Planet Rescue - Endangered Island (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Simulation / Educational', 'Independent', '1', 'Casual', 'Creature collection RPG.', 'Catch Ho-Oh and explore the Johto region.', 'North American remake of Pokémon Gold.', 'Pokémon HeartGold (USA) is the definitive remake of the GBC classic. With updated graphics and the ability to have any Pokémon follow you, it’s a nostalgic journey through Johto and Kanto.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('planet-rescue---ocean-patrol-europe-enfrdeesitnlsvnoda', 'NDS', 'Planet Rescue - Ocean Patrol (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2009', 'Simulation / Educational', 'Independent', '1', 'Casual', 'Creature collection RPG.', 'Catch Ho-Oh and explore the Johto region.', 'European remake of Pokémon Gold.', 'Return to Johto in Pokémon HeartGold (Europe). This version features the Pokéathlon mini-games and full compatibility with the Pokéwalker accessory for training on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plants-vs-zombies-usa', 'NDS', 'Plants vs. Zombies (USA)', '2011', 'Strategy / Puzzle', 'PopCap Games', '1', 'Casual', 'Creature collection RPG.', 'Conquer Sinnoh and catch Palkia.', 'North American release of Pokémon Pearl.', 'Pokémon Pearl Version (USA) features the master of space, Palkia. Explore the Sinnoh region, participate in Super Contests, and battle friends worldwide via the Nintendo Wi-Fi Connection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('platinum-sudoku-europe-enfrdeesit', 'NDS', 'Platinum Sudoku (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Gameloft', '1', 'Puzzle', 'Creature collection RPG.', 'Conquer Sinnoh and catch Palkia.', 'European release of Pokémon Pearl.', 'Journey through Sinnoh in Pokémon Pearl (Europe). Collect all 8 gym badges and stop Team Galactic''s plan to rewrite the universe in this landmark Fourth Generation RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('platinum-sudoku-usa-enfres', 'NDS', 'Platinum Sudoku (USA) (En,Fr,Es)', '2007', 'Puzzle', 'Gameloft', '1', 'Puzzle', 'Creature collection RPG.', 'Catch Giratina and stop the Distortion World crisis.', 'North American release of the expanded Sinnoh game.', 'Pokémon Platinum Version (USA) is the enhanced version of Diamond and Pearl. It features the Battle Frontier, the spooky Distortion World, and new forms for legendary Pokémon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('play-gardens-europe-enfrdeesitnl', 'NDS', 'Play Gardens (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Educational / Mini-Games', 'Microïds', '1', 'Casual', 'Creature collection RPG.', 'Catch Giratina and stop the Distortion World crisis.', 'European release of the expanded Sinnoh game.', 'Experience the ultimate Sinnoh adventure in Pokémon Platinum (Europe). With faster gameplay and an expanded Pokédex, it provides the most complete experience of the Fourth Generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playmobil-interactive---knight---hero-of-the-kingdom-europe-enfrdeesnl', 'NDS', 'Playmobil Interactive - Knight - Hero of the Kingdom (Europe) (En,Fr,De,Es,Nl)', '2009', 'Action / Adventure', 'Playmobil Interactive', '1', 'Cartoon', 'Creature collection RPG.', 'Catch Lugia and conquer the Johto league.', 'North American remake of Pokémon Silver.', 'Pokémon SoulSilver (USA) brings the legendary Lugia to the DS. Explore two full regions, battle 16 Gym Leaders, and experience one of the most content-packed entries in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playmobil-interactive---knight---hero-of-the-kingdom-europe-enitsvnofi', 'NDS', 'Playmobil Interactive - Knight - Hero of the Kingdom (Europe) (En,It,Sv,No,Fi)', '2009', 'Action / Adventure', 'Playmobil Interactive', '1', 'Cartoon', 'Creature collection RPG.', 'Catch Lugia and conquer the Johto league.', 'European remake of Pokémon Silver.', 'Relive the magic of the Johto region in Pokémon SoulSilver (Europe). Featuring beautifully remixed music and 3D-enhanced environments, it’s a masterpiece of handheld RPG design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playmobil-interactive---knights-usa-enfrdeesnl', 'NDS', 'Playmobil Interactive - Knights (USA) (En,Fr,De,Es,Nl)', '2009', 'Action / Adventure', 'Playmobil Interactive', '1', 'Cartoon', 'Creature collection RPG.', 'Become the Champion of the Unova region.', 'North American release of Pokémon White.', 'Pokémon White Version (USA) features the legendary Reshiram. It offers a unique experience compared to Black, with the exclusive White Forest area and different aesthetic changes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playmobil-interactive---pirates-usa-enfrdeesnl', 'NDS', 'Playmobil Interactive - Pirates (USA) (En,Fr,De,Es,Nl)', '2009', 'Action / Adventure', 'Playmobil Interactive', '1', 'Cartoon', 'Creature collection RPG.', 'Become the Champion of the Unova region.', 'European release of Pokémon White.', 'Explore the industrial and natural beauty of Unova in Pokémon White (Europe). Use the DS''s dual screens to manage high-stakes battles and navigate the first-ever 3D city in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('playmobil-interactive---top-agents-europe-enfrdeesit', 'NDS', 'Playmobil Interactive - Top Agents (Europe) (En,Fr,De,Es,It)', '2009', 'Action / Adventure', 'Playmobil Interactive', '1', 'Cartoon', 'Mini-game collection.', 'Win classic Pogo games to save the island.', 'Puzzle and arcade collection based on Pogo.com.', 'Pogo Island (Europe) features five classic games: Word Whomp, Poppit!, Phlinx, Tri-Peaks Solitaire, and Squelchies. Solve puzzles to help a stranded crew repair their boat in this casual hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plop-en-de-pinguin-netherlands', 'NDS', 'Plop en de Pinguin (Netherlands)', '2006', 'Action / Adventure', 'Unknown', '1', 'Cartoon', 'Mini-game collection.', 'Win classic Pogo games to save the island.', 'North American release of the Pogo puzzle game.', 'Play your favorite online games anywhere in Pogo Island (USA). Earn tokens and badges while playing through a charming adventure mode designed for quick, addictive puzzle sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plus-belle-la-vie---le-secret-du-dr-livia-france', 'NDS', 'Plus Belle la Vie - Le Secret du Dr Livia (France)', '2008', 'Adventure', 'Studio Canal', '1', 'Drama', 'Digital board game.', 'Solve puzzles and play through the story of the film.', 'Interactive board game based on the movie.', 'Polar Express (USA) follows the journey to the North Pole. Use the stylus to navigate through various themed mini-games and puzzles that capture the magical atmosphere of the holiday film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plus-belle-la-vie-2---le-mysterieux-passe-de-vincent-france', 'NDS', 'Plus Belle la Vie 2 - Le Mysterieux Passe de Vincent (France)', '2009', 'Adventure', 'Studio Canal', '1', 'Drama', 'Mini-game collection.', 'Train and play with the cute Polarium tiles.', 'Japanese version of the Polarium puzzle spin-off.', 'Polarium Advance (Japan) on DS (as Kunio-kun''s Polarium) offers a variety of tile-flipping puzzles. Match colors to clear rows in this minimalist and challenging logic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('plushees-usa', 'NDS', 'Plushees (USA)', '2007', 'Simulation / Casual', 'Ubisoft', '1', 'Casual', 'Puzzle action.', 'Clear the screen by flipping tiles to match colors.', 'The iconic launch-window puzzle game for Europe.', 'Polarium (Europe) uses the DS stylus to its full potential. Draw a single line to flip tiles and clear rows in "Puzzle" mode or survive as long as possible in the frantic "Challenge" mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-book---mein-geheimes-tagebuch-germany-enfrdeesitnl', 'NDS', 'Pocket Book - Mein Geheimes Tagebuch (Germany) (En,Fr,De,Es,It,Nl)', '2008', 'Educational', 'Ubisoft', '1', 'Casual', 'Puzzle action.', 'Clear the screen by flipping tiles to match colors.', 'North American release of the tile-flipping hit.', 'Test your logic in Polarium (USA). With its minimalist black-and-white aesthetic and clever puzzles, it challenges you to clear complex patterns with just one continuous stroke of the stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-chikyuugi-ds---sawatte-tanoshimu-jinrui-5000-nen-no-ayumi-japan-rev-1', 'NDS', 'Pocket Chikyuugi DS - Sawatte Tanoshimu Jinrui 5000 Nen no Ayumi (Japan) (Rev 1)', '2005', 'Educational', 'Nintendo', '1', 'Educational', 'Educational mini-games.', 'Complete school-themed tasks with the PopCutie cast.', 'Quirky Japanese educational game.', 'PopCutie! (Japan) features various mini-games designed to test memory, logic, and speed. Its colorful, pop-art style makes learning and practicing basic skills an entertaining experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---black-japan-ndsi-enhanced', 'NDS', 'Pocket Monsters - Black (Japan) (NDSi Enhanced)', '2010', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Fashion and business simulation.', 'Manage a boutique and become a fashion mogul.', 'Quirky shop management sim for North America.', 'PopCutie! Street Fashion (USA) tasks you with designing clothes and managing your own store. Scout for models, compete in "Fashion Battles," and set the trends in this addictive business sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---diamond-japan', 'NDS', 'Pocket Monsters - Diamond (Japan)', '2006', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Arcade and mini-games.', 'Help Popeye rescue Olive Oyl from Bluto.', 'Classic arcade action featuring the famous sailor.', 'Popeye: Saved by the Spinach (USA) features several mini-games based on the cartoon. Use the stylus to punch through obstacles and collect spinach to gain super strength.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---heartgold-japan', 'NDS', 'Pocket Monsters - HeartGold (Japan)', '2009', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Music and rhythm simulation.', 'Perform catchy songs with the Pop''n Music cast.', 'Portable version of the hit Konami rhythm series.', 'Pop''n Music (Japan) brings the vibrant arcade experience to the DS. Tap the colorful icons in time with the beat to clear a variety of J-pop and anime tracks in this high-energy musical game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---heartgold-korea', 'NDS', 'Pocket Monsters - HeartGold (Korea)', '2009', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Action-adventure & Beat ''em up.', 'Stop the Armada and save the world.', 'Sentai-style action based on the Power Rangers.', 'Power Rangers: Super Legends (Europe) features 2D side-scrolling combat. Play as different Rangers from throughout history, utilizing unique combos and special moves to defeat the evil Lord Zedd.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---pearl-japan', 'NDS', 'Pocket Monsters - Pearl (Japan)', '2006', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Action-adventure & Beat ''em up.', 'Stop the Armada and save the world.', 'North American release of the Ranger crossover.', 'Celebrate 15 years of the franchise in Power Rangers: Super Legends (USA). Team up with a friend in co-op mode to battle through time and space in this fast-paced action-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---pearl-japan-rev-5', 'NDS', 'Pocket Monsters - Pearl (Japan) (Rev 5)', '2006', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Strategy and turn-based combat.', 'Use cards to battle and summon powerful creatures.', 'Card-based strategy game for European fans.', 'Power Rangers: Super Samurai (Europe) combines tactical planning with Ranger action. Build your deck and engage in strategic battles to protect the Earth from the Nighlok threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---pearl-japan-rev-6', 'NDS', 'Pocket Monsters - Pearl (Japan) (Rev 6)', '2006', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Strategy and turn-based combat.', 'Use cards to battle and summon powerful creatures.', 'North American release of the Samurai card game.', 'Unleash the power of the Symbol Power in Power Rangers: Super Samurai (USA). Use the touch screen to draw symbols and activate special abilities in this unique blend of card strategy and action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---platinum-japan', 'NDS', 'Pocket Monsters - Platinum (Japan)', '2008', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Action-adventure & Beat ''em up.', 'Protect the city and defeat the Nighlok monsters.', 'Action-packed adventure based on the Samurai season.', 'Power Rangers Samurai (USA) lets you control the Red, Blue, Pink, Green, and Yellow Rangers. Master the ancient Samurai symbols to unlock powerful weapons and Megazord battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---soulsilver-japan', 'NDS', 'Pocket Monsters - SoulSilver (Japan)', '2009', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Action-adventure & Beat ''em up.', 'Protect the city and defeat the Nighlok monsters.', 'European release of the Samurai action game.', 'Join the Samurai Rangers in their quest to save humanity. This European edition features localized text and intense martial arts combat, culminating in epic giant robot showdowns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---soulsilver-korea', 'NDS', 'Pocket Monsters - SoulSilver (Korea)', '2009', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Action-adventure & Platformer.', 'Use prehistoric powers to stop the evil Mesogog.', 'Dinosaurs-themed Power Rangers action for Europe.', 'Power Rangers: Dino Thunder (Europe) features both Zord racing and on-foot action. Switch between the Red, Blue, and Yellow Rangers to navigate levels and fight off the Tyrannodrones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters---white-japan-ndsi-enhanced', 'NDS', 'Pocket Monsters - White (Japan) (NDSi Enhanced)', '2010', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Action-adventure & Platformer.', 'Use prehistoric powers to stop the evil Mesogog.', 'North American release of Dino Thunder.', 'Go Dino in Power Rangers: Dino Thunder (USA). This action-platformer utilizes the DS''s dual screens for navigation and combat, offering a variety of missions including puzzle-solving and boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters-dp---dialga-korea', 'NDS', 'Pocket Monsters DP - Dialga (Korea)', '2006', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Stop Team Galactic and catch the legendary Dialga.', 'Korean version of Pokémon Diamond.', 'Pocket Monsters DP: Dialga (Korea) brings the Sinnoh region to Korean players. Experience the fourth generation of Pokémon with fully localized text and Wi-Fi features for trading and battling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters-dp---palkia-korea', 'NDS', 'Pocket Monsters DP - Palkia (Korea)', '2006', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Stop Team Galactic and catch the legendary Palkia.', 'Korean version of Pokémon Pearl.', 'Pocket Monsters DP: Palkia (Korea) features the legendary master of space. This Korean localization includes the full Sinnoh adventure and compatible features for the DS wireless system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-monsters-pt---giratina-korea', 'NDS', 'Pocket Monsters Pt - Giratina (Korea)', '2008', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Enter the Distortion World and catch Giratina.', 'Korean version of Pokémon Platinum.', 'Pocket Monsters Pt: Giratina (Korea) is the definitive Sinnoh experience in Korean. It includes the expanded Pokédex, new story elements, and the challenging Battle Frontier.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-scenario-series---harukanaru-toki-no-naka-de---mai-hitoyo-japan', 'NDS', 'Pocket Scenario Series - Harukanaru Toki no Naka de - Mai Hitoyo (Japan)', '2009', 'Adventure / Visual Novel', 'Koei', '1', 'Anime', 'Visual novel.', 'Navigate ancient Japan and build relationships.', 'Story-driven visual novel based on the anime series.', 'Pocket Scenario Series: Harukanaru Toki no Naka de (Japan) is a romantic adventure set in the Heian period. Use the touch screen to progress through dialogue and influence the story''s outcome.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocoyo-racing-europe-enfrdeesit', 'NDS', 'Pocoyo Racing (Europe) (En,Fr,De,Es,It)', '2011', 'Racing', 'Zinkia Entertainment', '4', 'Cartoon', 'Racing simulation.', 'Win races and play mini-games with Pocoyo.', 'Child-friendly racing game based on the TV show.', 'Pocoyo Racing (Europe) features the beloved characters in a series of colorful tracks. Designed for younger players, it includes simple controls and educational mini-games between races.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pogo-island-europe', 'NDS', 'Pogo Island (Europe)', '2009', 'Puzzle / Adventure', 'Independent', '1', 'Casual', 'Mini-game collection.', 'Play classic Pogo puzzles to save the islanders.', 'European release of the Pogo.com collection.', 'Pogo Island (Europe) brings the casual fun of the web to the DS. Solve word games and puzzles like Poppit! and Word Whomp to earn badges and unlock secret island areas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pogo-island-usa', 'NDS', 'Pogo Island (USA)', '2009', 'Puzzle / Adventure', 'Independent', '1', 'Casual', 'Mini-game collection.', 'Play classic Pogo puzzles to save the islanders.', 'North American release of the Pogo puzzle game.', 'Pogo Island (USA) is a portable collection of addictive arcade puzzles. Compete in different modes to repair your ship and enjoy hours of casual "pick-up-and-play" gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('point-blank-ds-europe-enfrdees', 'NDS', 'Point Blank DS (Europe) (En,Fr,De,Es)', '2006', 'Shooter', 'Namco', '2', 'Arcade', 'Arcade shooting.', 'Hit targets and complete mini-games with speed.', 'Stylus-based port of the arcade shooter classic.', 'Point Blank DS (Europe) replaces the light gun with the DS stylus. Complete hundreds of quick-fire shooting challenges across various difficulty levels in this frantic and funny arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('point-blank-ds-usa', 'NDS', 'Point Blank DS (USA)', '2006', 'Shooter', 'Namco', '2', 'Arcade', 'Arcade shooting.', 'Hit targets and complete mini-games with speed.', 'North American release of Point Blank DS.', 'Sharpen your reflexes in Point Blank DS (USA). Use the touch screen to shoot targets, solve quick puzzles, and compete with friends in this faithful port of the Namco classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---edicion-blanca-spain-ndsi-enhanced', 'NDS', 'Pokemon - Edicion Blanca (Spain) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'Spanish version of Pokémon White (NDSi Enhanced).', 'Pokémon: Edición Blanca (Spain) lets Spanish players experience the Unova region. As an NDSi Enhanced title, it features improved wireless security and camera integration for avatars.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---edicion-negra-spain-ndsi-enhanced', 'NDS', 'Pokemon - Edicion Negra (Spain) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'Spanish version of Pokémon Black (NDSi Enhanced).', 'Pokémon: Edición Negra (Spain) features the legendary Zekrom. Explore the industrial side of Unova and battle through a deeper, more narrative-focused Pokémon adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---platinum-version-usa-rev-1', 'NDS', 'Pokemon - Platinum Version (USA) (Rev 1)', '2009', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Enter the Distortion World and catch Giratina.', 'Revised North American edition of Pokémon Platinum.', 'Pokémon: Platinum Version (USA) Rev 1 includes minor bug fixes and technical stability improvements over the initial launch, providing the ultimate Fourth Gen experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---schwarze-edition-germany-ndsi-enhanced', 'NDS', 'Pokemon - Schwarze Edition (Germany) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'German version of Pokémon Black (NDSi Enhanced).', 'Pokémon: Schwarze Edition (Germany) brings the fifth generation to German trainers. Master the new Triple and Rotation battles in this feature-packed NDSi enhanced title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---version-blanche-france-ndsi-enhanced', 'NDS', 'Pokemon - Version Blanche (France) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'French version of Pokémon White (NDSi Enhanced).', 'Pokémon: Version Blanche (France) features the legendary Reshiram. Discover the beauty of the Unova region and engage in a story about truth vs. ideals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---version-noire-france-ndsi-enhanced', 'NDS', 'Pokemon - Version Noire (France) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'French version of Pokémon Black (NDSi Enhanced).', 'Pokémon: Version Noire (France) allows players to catch Zekrom and stop Team Plasma. Includes NDSi-specific features for a more modern handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---versione-bianca-italy-ndsi-enhanced', 'NDS', 'Pokemon - Versione Bianca (Italy) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'Italian version of Pokémon White (NDSi Enhanced).', 'Pokémon: Versione Bianca (Italy) delivers the complete Unova journey. Trade and battle with players worldwide and experience the changing seasons of the region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---versione-nera-italy-ndsi-enhanced', 'NDS', 'Pokemon - Versione Nera (Italy) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'Italian version of Pokémon Black (NDSi Enhanced).', 'Pokémon: Versione Nera (Italy) features the dark hero Zekrom. This NDSi Enhanced edition provides a stable and visually polished experience for Italian Pokémon fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon---weisse-edition-germany-ndsi-enhanced', 'NDS', 'Pokemon - Weisse Edition (Germany) (NDSi Enhanced)', '2011', 'Role-Playing', 'Game Freak', '1', 'JRPG', 'Creature collection RPG.', 'Conquer Unova and stop Team Plasma.', 'German version of Pokémon White (NDSi Enhanced).', 'Pokémon: Weisse Edition (Germany) focuses on the legendary Reshiram. Explore the "White Forest" and complete the Unova Pokédex in this localized German masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-blaze-black-2-redux', 'NDS', 'Pokemon Blaze Black 2 Redux', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Complete a harder version of Unova with all Pokémon.', 'Modernized ROM hack of Pokémon Black 2.', 'Pokémon Blaze Black 2 Redux is a comprehensive hack that allows you to catch all 649 Pokémon. It features revamped trainer battles, new items, and a much higher difficulty curve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-bloody-platinum', 'NDS', 'Pokemon Bloody Platinum', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Survive a darker, harder version of Sinnoh.', 'Challenging ROM hack of Pokémon Platinum.', 'Pokémon Bloody Platinum increases the game''s difficulty significantly. It features modified wild Pokémon encounters and trainers with competitive-level teams to test veteran players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-bloody-platinum-redux', 'NDS', 'Pokemon Bloody Platinum Redux', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Experience the ultimate challenge in Sinnoh.', 'Enhanced version of the Bloody Platinum hack.', 'Bloody Platinum Redux refines the original hack with better balance and additional features, making it one of the most punishing yet rewarding ways to play the fourth generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-darkdiamond-beta-21', 'NDS', 'Pokemon DarkDiamond Beta 2.1', '2015', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Explore an early beta version of a Sinnoh hack.', 'Fan-made beta hack of Pokémon Diamond.', 'Pokémon DarkDiamond Beta 2.1 is an early look at a fan project aiming to modernize Diamond. It includes custom sprites, new events, and modified map layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-flawless-platinum-v301', 'NDS', 'Pokemon Flawless Platinum v3.01', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Battle a perfectly balanced Sinnoh roster.', 'Refined difficulty ROM hack for Pokémon Platinum.', 'Flawless Platinum v3.01 focuses on balance. It allows players to obtain every Pokémon through gameplay and provides a steady difficulty increase without being unfair to the player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---algernon-xs', 'NDS', 'Pokemon Mystery Dungeon - Algernon XS', '2014', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Explore random dungeons with custom stories.', 'Fan-made expansion for Mystery Dungeon.', 'PMD: Algernon XS is a custom ROM hack that introduces new story chapters and tweaked mechanics to the classic Mystery Dungeon: Explorers of Sky engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---ark-of-reveries-crystalline-cradle-english', 'NDS', 'Pokemon Mystery Dungeon - Ark of Reverie''s Crystalline Cradle (English)', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Find the mysterious Ark in a crystalline world.', 'Story-heavy fan game for Mystery Dungeon (English).', 'Ark of Reverie''s Crystalline Cradle (English) features a brand-new narrative. Guide your Pokémon team through beautiful but dangerous crystal-themed dungeons in this fan creation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---ark-of-reveries-crystalline-cradle-german', 'NDS', 'Pokemon Mystery Dungeon - Ark of Reverie''s Crystalline Cradle (German)', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Find the mysterious Ark in a crystalline world.', 'German localization of the Ark of Reverie fan game.', 'This German version of Ark of Reverie''s Crystalline Cradle brings the custom story and dungeons to German-speaking fans of the Mystery Dungeon series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---blorg', 'NDS', 'Pokemon Mystery Dungeon - B.L.O.R.G.', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Complete a unique mission with a custom script.', 'Short-form ROM hack for Mystery Dungeon.', 'PMD: B.L.O.R.G. is a creative hack known for its unique writing and experimental gameplay elements within the standard dungeon-crawling framework.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---blooming-silence', 'NDS', 'Pokemon Mystery Dungeon - Blooming Silence', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Survive in a world where sound has vanished.', 'Concept-driven fan hack for Mystery Dungeon.', 'Blooming Silence features a custom story focused on a world without sound. It includes new dialogue, modified dungeons, and a unique atmosphere for PMD fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---blue-rescue-team-prologue', 'NDS', 'Pokemon Mystery Dungeon - Blue Rescue Team Prologue', '2015', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Play through a prologue of a new rescue story.', 'Early access/prologue hack for Blue Rescue Team.', 'PMD: Blue Rescue Team Prologue is a fan project that adds an intro chapter to the original GBA/DS title, setting the stage for a new, expanded narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---bouquet-of-the-past', 'NDS', 'Pokemon Mystery Dungeon - Bouquet Of The Past', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Recover memories from a past shrouded in flowers.', 'Story-focused ROM hack for Mystery Dungeon.', 'Bouquet Of The Past is a fan-made chapter that explores the history of certain Pokémon characters through challenging dungeons and emotional storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---city-of-light', 'NDS', 'Pokemon Mystery Dungeon - City of Light', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Reach the mythical City of Light.', 'Exploration-heavy fan hack for Mystery Dungeon.', 'PMD: City of Light features custom maps and a quest to find a legendary city. It tests the player''s management of items and team members in long-form dungeons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---corrupted-core---prologue', 'NDS', 'Pokemon Mystery Dungeon - Corrupted Core - Prologue', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Investigate the corruption at the world''s core.', 'Intro chapter for a dark Mystery Dungeon story.', 'Corrupted Core - Prologue is a darker take on the PMD universe. It introduces a new threat and modified gameplay mechanics that focus on survival and mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---cryptic-conundrum', 'NDS', 'Pokemon Mystery Dungeon - Cryptic Conundrum', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Solve the riddles of the cryptic dungeons.', 'Puzzle-focused ROM hack for Mystery Dungeon.', 'Cryptic Conundrum emphasizes the puzzle-solving aspects of PMD. Navigate complex floor layouts and use your items wisely to solve the "conundrums" of each dungeon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---divided-spirits', 'NDS', 'Pokemon Mystery Dungeon - Divided Spirits', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Reunite spirits across fragmented worlds.', 'Multi-character fan hack for Mystery Dungeon.', 'Divided Spirits features a narrative that follows two separate paths. Experience how the actions of one team affect the other in this innovative and complex fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---exploration', 'NDS', 'Pokemon Mystery Dungeon - Exploration', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Explore new lands in a custom story.', 'Fan-made expansion for Mystery Dungeon.', 'PMD: Exploration is a creative hack that adds new dungeons and items to the classic engine, offering veteran players a fresh perspective on the rescue team formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---explorers-of-fortune', 'NDS', 'Pokemon Mystery Dungeon - Explorers of Fortune', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Seek your fortune in dangerous new ruins.', 'Wealth-focused Mystery Dungeon ROM hack.', 'PMD: Explorers of Fortune introduces a specialized economy and rare loot tables, challenging players to build the wealthiest and most powerful rescue team in the region.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---explorers-of-heaven-23', 'NDS', 'Pokemon Mystery Dungeon - Explorers of Heaven 2.3', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Conquer the divine trials of the heavens.', 'High-difficulty "Heaven" version ROM hack.', 'Explorers of Heaven 2.3 is the "lighter" counterpart to the Hell version. It features rebalanced Pokémon, new starters, and a significant difficulty spike for experienced players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---explorers-of-hell-23', 'NDS', 'Pokemon Mystery Dungeon - Explorers of Hell 2.3', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Survive the most brutal dungeons ever created.', 'Ultra-hard "Hell" version ROM hack.', 'Explorers of Hell 2.3 is designed for the ultimate challenge. Featuring aggressive AI and punishing level design, it tests the limits of strategy in the Mystery Dungeon universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---explorers-of-pain', 'NDS', 'Pokemon Mystery Dungeon - Explorers of Pain', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Endure the suffering of the ultimate gauntlet.', 'Endurance-focused Mystery Dungeon challenge.', 'PMD: Explorers of Pain lives up to its name with limited resources and high enemy density. It is a test of attrition and careful item management for hardcore fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---explorers-of-the-spirit', 'NDS', 'Pokemon Mystery Dungeon - Explorers of the Spirit', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Uncover the mystery of the spiritual realm.', 'Story-heavy ROM hack with a deep narrative.', 'Explorers of the Spirit features a completely original script and custom cutscenes. Follow a spiritual journey that questions the nature of being a Pokémon in this acclaimed hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---explorers-of-the-spirit-espanol', 'NDS', 'Pokemon Mystery Dungeon - Explorers of the Spirit (Espanol)', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Uncover the mystery of the spiritual realm.', 'Spanish localization of Explorers of the Spirit.', 'Vive la épica historia de Explorers of the Spirit totalmente en español. Esta traducción permite a los fans hispanohablantes disfrutar de uno de los mejores guiones de la comunidad.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---fantariem', 'NDS', 'Pokemon Mystery Dungeon - Fantariem', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Journey through a dreamlike fantasy world.', 'Surreal and artistic Mystery Dungeon hack.', 'PMD: Fantariem stands out with its unique atmosphere and custom music. It offers a shorter but more experimental narrative experience within the Sky engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---fount-of-victory', 'NDS', 'Pokemon Mystery Dungeon - Fount of Victory', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Reach the Fount of Victory to save your team.', 'Mission-based custom story hack.', 'PMD: Fount of Victory focuses on a specific quest across several new biomes. It features unique boss encounters and a tight, focused storyline.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---future-of-hope', 'NDS', 'Pokemon Mystery Dungeon - Future of Hope', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Restore hope to a decaying future world.', 'Future-themed narrative expansion.', 'PMD: Future of Hope explores the "Dark Future" timeline with new perspectives. Help a group of resistance Pokémon change destiny in this emotional fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---futures-gifts', 'NDS', 'Pokemon Mystery Dungeon - Future''s Gifts', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Collect the gifts of the future to fix the present.', 'Narrative sequel to the Future arc.', 'PMD: Future''s Gifts acts as an epilogue to the main game''s special episodes. It provides closure for several fan-favorite characters through challenging new dungeons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---let-the-music-play!', 'NDS', 'Pokemon Mystery Dungeon - Let The Music Play!', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Solve a mystery centered around musical notes.', 'Rhythm and sound-themed Mystery Dungeon hack.', 'Let The Music Play! is a creative hack where sound plays a key role in the story. It features a curated soundtrack and puzzles based on musical themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---memories-official-demo-v211', 'NDS', 'Pokemon Mystery Dungeon - Memories Official Demo v.2.1.1', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Experience the beginning of a grand memory.', 'Official demo for an upcoming massive hack.', 'Memories (Demo v.2.1.1) showcases advanced technical features, including new UI elements and custom portraits, setting a new standard for Pokémon fan games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---meowstics-tale', 'NDS', 'Pokemon Mystery Dungeon - Meowstic''s Tale', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Follow Meowstic''s journey in a custom tale.', 'Character-focused side story hack.', 'PMD: Meowstic''s Tale tells a personal story centered on the psychic cat Pokémon. It features specialized move-pools and a narrative that explores the character''s psyche.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---nocturne-of-a-presumed-prodigy', 'NDS', 'Pokemon Mystery Dungeon - NOCTURNE OF A PRESUMED PRODIGY', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Unmask the truth behind a rising star.', 'Gothic and mysterious Mystery Dungeon hack.', 'NOCTURNE OF A PRESUMED PRODIGY features a dark, operatic story. Its unique writing style and atmospheric dungeon design offer a mature take on the Pokémon world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---nymbles-story', 'NDS', 'Pokemon Mystery Dungeon - Nymble''s Story', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Help Nymble find his place in the world.', 'Story focused on a small bug Pokémon.', 'PMD: Nymble''s Story is a heartwarming tale about growth and bravery. It restricts the player to specific Pokémon to create a unique tactical experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---otherworld', 'NDS', 'Pokemon Mystery Dungeon - Otherworld', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Find a way back from a strange new world.', 'Isekai-style Mystery Dungeon adventure.', 'PMD: Otherworld places the protagonist in a bizarre dimension where the rules of the Pokémon world are warped. Survive and find the portal home in this strange hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---phantasime-english', 'NDS', 'Pokemon Mystery Dungeon - Phantasime (English)', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Stop the phantasms from consuming the world.', 'Ghost-themed mystery adventure (English).', 'PMD: Phantasime features custom ghost-type mechanics and a spooky narrative. Solve the mystery of the vanishing spirits in this highly polished fan game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---phantasime-german', 'NDS', 'Pokemon Mystery Dungeon - Phantasime (German)', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Stop the phantasms from consuming the world.', 'German localization of Phantasime.', 'Phantasime (German) brings this hauntingly beautiful mystery to German-speaking players, featuring full translation of the complex custom script.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---sands-of-time', 'NDS', 'Pokemon Mystery Dungeon - Sands of Time', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Navigate the shifting deserts of time.', 'Desert-themed tactical ROM hack.', 'PMD: Sands of Time focuses on endurance in harsh environments. Navigate heat-based mechanics and sandstorm dungeons in this challenging thematic expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---seal-of-ancients', 'NDS', 'Pokemon Mystery Dungeon - Seal of Ancients', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Unlock the ancient seal before it''s too late.', 'Lore-heavy ancient history ROM hack.', 'Seal of Ancients explores the prehistoric era of the Pokémon world. Battle ancient forms and discover the origins of the mystery dungeons themselves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---shallow-shindig', 'NDS', 'Pokemon Mystery Dungeon - Shallow Shindig', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Enjoy a festive but dangerous celebration.', 'Event-based Mystery Dungeon mini-hack.', 'PMD: Shallow Shindig is a shorter, more lighthearted adventure focused on a festival gone wrong. It’s perfect for a quick, engaging playthrough with unique rewards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---soul-secrets', 'NDS', 'Pokemon Mystery Dungeon - Soul Secrets', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Protect the secrets of the soul.', 'Philosophical and narrative-driven hack.', 'Soul Secrets features a deep, dialogue-heavy story that branches based on player choices, a rare feature in the Mystery Dungeon hacking scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---special-episode-0:-in-a-dark-past', 'NDS', 'Pokemon Mystery Dungeon - Special Episode 0: In A Dark Past', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Explore the origins of a villainous past.', 'Prequel story focused on a dark history.', 'Special Episode 0: In A Dark Past gives players a chance to see the world from a different perspective, filling in gaps in the original Explorers of Sky lore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---speedrun-mod', 'NDS', 'Pokemon Mystery Dungeon - Speedrun Mod', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Complete the game in record time.', 'Specialized mod for the speedrunning community.', 'The PMD Speedrun Mod streamlines cutscenes, optimizes text speed, and adds a timer, making it the essential tool for competitive Mystery Dungeon players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---team-misfits', 'NDS', 'Pokemon Mystery Dungeon - Team Misfits', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Lead a group of outcasts to redemption.', 'Team-focused character study hack.', 'Team Misfits follows a group of unlikely heroes who don''t fit the standard rescue team mold. It features great character development and custom team tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---the-bright-future', 'NDS', 'Pokemon Mystery Dungeon - The Bright Future', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Ensure a peaceful future for all Pokémon.', 'Optimistic and heroic narrative hack.', 'The Bright Future is a story of rebuilding after the events of the main game. Focus on community building and clearing out the remaining threats to the peace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---the-experiment', 'NDS', 'Pokemon Mystery Dungeon - The Experiment', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Escape the lab and find your true identity.', 'Sci-fi themed Mystery Dungeon experiment.', 'The Experiment starts with the player as a lab subject. Use unique, "glitched" abilities to battle your way through artificial dungeons to find freedom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---the-perfect-mix', 'NDS', 'Pokemon Mystery Dungeon - The Perfect Mix', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Find the perfect balance between two worlds.', 'Crossover-style Mystery Dungeon hack.', 'The Perfect Mix blends elements from different Pokémon generations and spin-offs into one cohesive experience, featuring a massive roster of available recruits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---the-phantom-thief', 'NDS', 'Pokemon Mystery Dungeon - The Phantom Thief', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Catch the elusive thief before they disappear.', 'Stealth and pursuit-focused ROM hack.', 'The Phantom Thief introduces "chase" mechanics where players must track a recurring boss through changing floors, adding a layer of urgency to the gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---the-weather-up-there', 'NDS', 'Pokemon Mystery Dungeon - The Weather Up There', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Investigate the strange weather anomalies.', 'Weather-focused tactical simulation hack.', 'The Weather Up There revolves around the weather-altering legendary Pokémon. Each dungeon has extreme weather conditions that the player must counter with specific strategies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---trials-of-the-person', 'NDS', 'Pokemon Mystery Dungeon - Trials of the Person', '2016', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Overcome trials designed for a human heart.', 'Meta-narrative focused Mystery Dungeon hack.', 'Trials of the Person deals with the psychological aspects of a human turned into a Pokémon, featuring difficult moral choices and challenging solo-runs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---turnabout-dimension', 'NDS', 'Pokemon Mystery Dungeon - Turnabout Dimension', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Solve a mystery across multiple dimensions.', 'Crossover mystery adventure for PMD.', 'Turnabout Dimension takes inspiration from the Ace Attorney series. It features investigation phases and "trial" dungeons where logic is as important as combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---unwanted-attention', 'NDS', 'Pokemon Mystery Dungeon - Unwanted Attention', '2017', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Avoid the gaze of an overwhelming force.', 'Stealth and survival-based ROM hack.', 'PMD: Unwanted Attention is a unique hack where combat is often discouraged. Use items and positioning to avoid powerful "Stalker" enemies that roam the floors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---vantasma', 'NDS', 'Pokemon Mystery Dungeon - Vantasma', '2018', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Defeat the vampire-like entity of the shadows.', 'Horror-themed Mystery Dungeon expansion.', 'PMD: Vantasma features a gothic horror story with "blood" mechanics and life-stealing enemies, creating a tense and dark atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-mystery-dungeon---waves-of-nostalgia', 'NDS', 'Pokemon Mystery Dungeon - Waves Of Nostalgia', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Dungeon crawler RPG.', 'Relive the classic era with modern twists.', 'Nostalgia-driven Mystery Dungeon celebration.', 'Waves Of Nostalgia remakes classic Red/Blue Rescue Team missions within the superior Sky engine, featuring updated graphics and mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-origin-platinum-v14', 'NDS', 'Pokemon Origin Platinum V1.4', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Complete the ultimate Sinnoh Pokédex.', 'Enhanced version of Pokémon Platinum.', 'Origin Platinum V1.4 is a major overhaul that allows you to catch all 493 Pokémon in a single playthrough. It features increased difficulty, faster text speeds, and updated movesets for a modern feel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-pearl---slotmod', 'NDS', 'Pokemon Pearl - Slotmod', '2010', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Find rare items and Pokémon through slots.', 'Slot-machine focused mod for Pokémon Pearl.', 'Pokémon Pearl: Slotmod revamps the Game Corner and item distribution. It focuses on luck-based progression and high-stakes rewards, offering a unique twist on the classic Sinnoh journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-perfect-heart', 'NDS', 'Pokemon Perfect Heart', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Experience the perfect Johto adventure.', '"Vanilla Plus" ROM hack of HeartGold.', 'Perfect Heart allows you to obtain all Pokémon without trading. It keeps the original story intact but rebalances gym leaders and wild encounters to provide a smooth, complete experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-perfect-soul', 'NDS', 'Pokemon Perfect Soul', '2019', 'Role-Playing', 'Fan Made', '1', 'JRPG', 'Creature collection RPG.', 'Experience the perfect Johto adventure.', '"Vanilla Plus" ROM hack of SoulSilver.', 'Perfect Soul is the companion hack to Perfect Heart. It ensures every Pokémon is obtainable in-game and fixes minor bugs, making it the definitive way to play the classic remake.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-ranger---guardian-signs-europe-enfrdeesit', 'NDS', 'Pokemon Ranger - Guardian Signs (Europe) (En,Fr,De,Es,It)', '2010', 'Action-Adventure', 'Nintendo', '1', 'Action Adventure', 'Action RPG.', 'Protect nature and capture Pokémon using the Capture Styler.', 'The third installment of the Ranger series for Europe.', 'Guardian Signs (Europe) introduces "Ranger Signs" to summon legendary Pokémon. Use the stylus to draw circles and capture Pokémon to solve environmental puzzles and stop the Pokémon Pinchers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-ranger---guardian-signs-usa', 'NDS', 'Pokemon Ranger - Guardian Signs (USA)', '2010', 'Action-Adventure', 'Nintendo', '1', 'Action Adventure', 'Action RPG.', 'Protect nature and capture Pokémon using the Capture Styler.', 'North American release of Guardian Signs.', 'Team up with Ukulele Pichu in Pokémon Ranger: Guardian Signs (USA). With local wireless co-op and a deep story involving the Oblivia region, it''s a unique departure from the main series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokerdome-poker-master---no-limit-texas-holdem-poker-australia', 'NDS', 'PokerDome Poker Master - No Limit Texas Hold''em Poker (Australia)', '2008', 'Board / Card', 'GameMill', '1', 'Poker', 'Poker simulation.', 'Win the PokerDome tournament and become a master.', 'Professional Texas Hold''em for Australia.', 'PokerDome Poker Master offers a realistic tournament experience. Study your opponents'' tells and master "No Limit" strategies to climb the ranks and win the grand prize in this Australian edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polar-bowler-usa', 'NDS', 'Polar Bowler (USA)', '2004', 'Arcade', 'WildTangent', '1', 'Arcade', 'Sports / Arcade.', 'Bowl across icy tracks and get a strike.', 'Wacky arctic-themed bowling game.', 'Polar Bowler (USA) features a polar bear in an inner tube. Aim, power up, and launch your bear down the ice to knock over pins in this humorous and addictive arcade sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polar-rampage-europe-enfrdeesitpt', 'NDS', 'Polar Rampage (Europe) (En,Fr,De,Es,It,Pt)', '2009', 'Arcade', 'WildTangent', '1', 'Arcade', 'Action / Arcade.', 'Cause chaos as a polar bear on the run.', 'Frantic arcade destruction game.', 'Polar Rampage (Europe) puts you in control of an escaped polar bear. Smash through obstacles, avoid capture, and complete challenges across multiple levels in this high-energy multi-language title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polarium-europe-enfrdeesit', 'NDS', 'Polarium (Europe) (En,Fr,De,Es,It)', '2005', 'Puzzle', 'Nintendo', '1', 'Puzzle', 'Logic puzzle.', 'Clear tiles by flipping them to match colors.', 'Minimalist and addictive puzzle hit for Europe.', 'Polarium (Europe) challenges your spatial logic. Use the stylus to flip black and white tiles in a single stroke to clear the board in this classic and elegant DS launch-window title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('polarium-usa', 'NDS', 'Polarium (USA)', '2005', 'Puzzle', 'Nintendo', '1', 'Puzzle', 'Logic puzzle.', 'Clear tiles by flipping them to match colors.', 'North American release of the puzzle classic.', 'Master the art of the "one-stroke" puzzle in Polarium (USA). With hundreds of puzzles and a creative custom-puzzle maker, it''s a must-have for fans of minimalist brain-teasers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pons-englisch---vokabel-buddy-europe-frdeit', 'NDS', 'PONS Englisch - Vokabel Buddy (Europe) (Fr,De,It)', '2008', 'Educational', 'PONS', '1', 'Educational', 'Educational / Language.', 'Improve your English vocabulary through games.', 'Interactive English vocabulary trainer.', 'PONS Vokabel Buddy (Europe) uses the dual screens to make learning English engaging. Featuring multiple difficulty levels and progress tracking, it''s a perfect study tool for on-the-go learning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pons-franzoesisch---vokabel-buddy-germany', 'NDS', 'PONS Franzoesisch - Vokabel Buddy (Germany)', '2008', 'Educational', 'PONS', '1', 'Educational', 'Educational / Language.', 'Improve your French vocabulary through games.', 'French language trainer for German speakers.', 'PONS Franzoesisch Buddy (Germany) focuses on essential French words and phrases. Use interactive quizzes and audio examples to perfect your pronunciation and expand your vocabulary.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-friends-europe-enfrdeesitnl', 'NDS', 'Pony Friends (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Horse care simulation.', 'Groom, feed, and race your pony friends.', 'The first entry of the popular pony series.', 'Pony Friends (Europe) lets you create and customize your perfect pony. Take photos of wildlife, go on trail rides, and ensure your stable is the best in the land in this heartwarming sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-friends-europe-enfrdeesitnl-rev-1', 'NDS', 'Pony Friends (Europe) (En,Fr,De,Es,It,Nl) (Rev 1)', '2006', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Horse care simulation.', 'Groom, feed, and race your pony friends.', 'Revised European version of Pony Friends.', 'This Revision 1 of Pony Friends (Europe) includes minor technical fixes and improved stability, ensuring a smooth experience for young riders managing their virtual stables.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-friends-usa-enfrdeesitnl', 'NDS', 'Pony Friends (USA) (En,Fr,De,Es,It,Nl)', '2006', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Horse care simulation.', 'Groom, feed, and race your pony friends.', 'North American release of Pony Friends.', 'Adopt a pony and become its best friend in Pony Friends (USA). Use the touch screen to groom their coat and the microphone to call them, creating a deep bond with your digital pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-friends-usa-enfrdeesitnl-rev-1', 'NDS', 'Pony Friends (USA) (En,Fr,De,Es,It,Nl) (Rev 1)', '2006', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Horse care simulation.', 'Groom, feed, and race your pony friends.', 'Revised North American version of Pony Friends.', 'This Rev 1 edition for the USA market optimizes the mini-games and item management, providing the most polished version of the original pony-care hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-friends-2-europe-enfrdeesit', 'NDS', 'Pony Friends 2 (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Horse care simulation.', 'Compete in races and customize your ponies.', 'Feature-packed sequel to the pony hit.', 'Pony Friends 2 (Europe) adds new breeds, more accessories, and expanded trail rides. Compete in international competitions and manage every aspect of your pony''s life in this multi-language sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-friends-2-usa-enfrdeesit', 'NDS', 'Pony Friends 2 (USA) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Horse care simulation.', 'Compete in races and customize your ponies.', 'North American release of Pony Friends 2.', 'Experience the joy of horse ownership in Pony Friends 2 (USA). Featuring more realistic animations and a wider variety of environments, it''s the ultimate sequel for fans of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-life-europe-enfrdeesit', 'NDS', 'Pony Life (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Eidos', '1', 'Life Simulation', 'Pet simulation.', 'Raise and nurture a variety of cute ponies.', 'Simple and accessible pony simulator.', 'Pony Life (Europe) is designed for younger children. Focus on basic care tasks like washing, feeding, and dressing up your ponies in a colorful and friendly environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-luv-europe-enfrde', 'NDS', 'Pony Luv (Europe) (En,Fr,De)', '2008', 'Simulation', 'Deep Silver', '1', 'Life Simulation', 'Pet simulation.', 'Adopt, raise, and love your very own pony.', 'Budget-friendly pony care simulation for Europe.', 'Pony Luv (Europe) focuses on the daily responsibilities of pet ownership. Learn how to keep your pony happy through consistent care and playful interactions using the DS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pony-luv-usa-enfr', 'NDS', 'Pony Luv (USA) (En,Fr)', '2008', 'Simulation', 'Deep Silver', '1', 'Life Simulation', 'Pet simulation.', 'Adopt, raise, and love your very own pony.', 'North American release of Pony Luv.', 'Choose your favorite pony breed and start a new life together in Pony Luv (USA). Earn money by winning small competitions to buy better food and fancier accessories for your pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pop-cutie!---street-fashion-simulation-usa', 'NDS', 'Pop Cutie! - Street Fashion Simulation (USA)', '2009', 'Simulation', 'City Interactive', '1', 'Life Simulation', 'Business / Fashion sim.', 'Manage a fashion shop and set street trends.', 'Quirky and colorful fashion business simulator.', 'Pop Cutie! (USA) is a unique simulation where you design outfits and manage your boutique. Compete in "Fashion Battles" to gain popularity and become the trendsetter of the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pop-town-europe-enfrit', 'NDS', 'Pop Town (Europe) (En,Fr,It)', '2007', 'Simulation', 'Gameloft', '1', 'Life Simulation', 'Puzzle / Arcade.', 'Pop bubbles and clear the screen to build a town.', 'Town-building puzzle game for Europe.', 'Pop Town (Europe) combines classic match-3 bubble popping with a city-building mechanic. Clear levels to earn resources and watch your small village grow into a bustling metropolis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popstars-germany-ndsi-enhanced', 'NDS', 'Popstars (Germany) (NDSi Enhanced)', '2008', 'Simulation', 'RTL Games', '1', 'Life Simulation', 'Music / Rhythm.', 'Train a pop group and reach the top of the charts.', 'NDSi Enhanced music career simulation.', 'Popstars (Germany) lets you manage a rising band. Use the NDSi camera to put yourself in the game and master rhythm-based mini-games to win the ultimate talent show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-ds-europe-enfrdeesit', 'NDS', 'Populous DS (Europe) (En,Fr,De,Es,It)', '2007', 'Strategy', 'Electronic Arts', '1', 'Strategy', 'God simulation / Strategy.', 'Manipulate the land and guide your followers to victory.', 'Port of the legendary Peter Molyneux classic.', 'Populous DS (Europe) brings the "God Game" to the handheld. Use the stylus to create earthquakes, volcanoes, and floods to help your people defeat the rival deity across 50 missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-ds-japan', 'NDS', 'Populous DS (Japan)', '2007', 'Strategy', 'Electronic Arts', '1', 'Strategy', 'God simulation / Strategy.', 'Manipulate the land and guide your followers to victory.', 'Japanese release of the Populous remake.', 'Experience the strategic depth of Populous DS (Japan). This version features a unique touch-screen interface that makes managing your world and casting miracles intuitive and fast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-ds-usa', 'NDS', 'Populous DS (USA)', '2007', 'Strategy', 'Electronic Arts', '1', 'Strategy', 'God simulation / Strategy.', 'Manipulate the land and guide your followers to victory.', 'North American release of Populous DS.', 'Play as the hand of god in Populous DS (USA). Influence your civilization''s growth and use elemental powers to conquer enemy lands in this faithful and expanded handheld port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pororon!-docomodake-ds-japan', 'NDS', 'Pororon! Docomodake DS (Japan)', '2009', 'Adventure', 'Bandai Namco', '1', 'Adventure', 'Puzzle / Platformer.', 'Use mushrooms (Docomodake) to solve environmental puzzles.', 'Creative puzzle game based on the mascot.', 'Pororon! Docomodake DS (Japan) is a clever physics-puzzler. Divide and reunite your mushroom family to overcome obstacles and reach the goal in this charming Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('postcode-loterij-een-tegen-100-netherlands', 'NDS', 'Postcode Loterij Een tegen 100 (Netherlands)', '2008', 'Game Show', 'Endemol', '1', 'Game Show', 'Trivia / Game Show.', 'Answer questions to beat the 100 and win the lottery.', 'Dutch game show adaptation.', 'Een tegen 100 (Netherlands) recreates the popular TV show. Test your general knowledge against a "wall" of 100 people, using lifelines and strategy to win the virtual jackpot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('postman-pat-europe-enfrdeesitnlptsvnodafi', 'NDS', 'Postman Pat (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv,No,Da,Fi)', '2006', 'Adventure', 'Ocean Software', '1', 'Adventure', 'Adventure / Mini-games.', 'Deliver the mail and help the residents of Greendale.', 'Children''s game based on the famous postman.', 'Postman Pat (Europe) is a friendly adventure for toddlers. Drive the van and complete simple delivery tasks and puzzles that encourage helpfulness and problem-solving in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('postpet-ds---yumemiru-momo-to-fushigi-no-pen-japan', 'NDS', 'PostPet DS - Yumemiru Momo to Fushigi no Pen (Japan)', '2007', 'Simulation', 'From Software', '1', 'Life Simulation', 'Virtual pet / Communication.', 'Send letters and care for your digital PostPet.', 'Communication-focused pet sim from Japan.', 'PostPet DS (Japan) features Momo the teddy bear. Send digital mail to friends while taking care of your quirky pets in a world where communication and pet care go hand-in-hand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poupeegirl-ds-japan', 'NDS', 'Poupeegirl DS (Japan)', '2009', 'Simulation', 'Alvion', '1', 'Life Simulation', 'Fashion / Social sim.', 'Dress up your avatar and share styles online.', 'Community-focused fashion game for Japan.', 'Poupeegirl DS (Japan) brings the popular web service to the DS. Collect thousands of items, customize your doll, and participate in fashion contests to earn "Ribbons" for more shopping.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poupeegirl-ds-2---elegant-mint-style-japan', 'NDS', 'Poupeegirl DS 2 - Elegant Mint Style (Japan)', '2010', 'Simulation', 'Alvion', '1', 'Life Simulation', 'Fashion / Social sim.', 'Master the elegant and "Mint" fashion style.', 'Specialized sequel to the Poupeegirl series.', 'Poupeegirl DS 2: Elegant Mint Style focuses on sophisticated and mature fashion. Mix and match high-end items to create the perfect look for exclusive social events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poupeegirl-ds-2---sweet-pink-style-japan', 'NDS', 'Poupeegirl DS 2 - Sweet Pink Style (Japan)', '2010', 'Simulation', 'Alvion', '1', 'Life Simulation', 'Fashion / Social sim.', 'Master the cute and "Sweet Pink" fashion style.', 'Specialized sequel to the Poupeegirl series.', 'Poupeegirl DS 2: Sweet Pink Style is all about the "Kawaii" aesthetic. Collect adorable pink accessories and dresses to become the cutest fashionista in the community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-play-pool-europe-enfrdeesit', 'NDS', 'Power Play Pool (Europe) (En,Fr,De,Es,It)', '2007', 'Sports', 'Virtual Play Games', '2', 'Pool', 'Billiards / Sports.', 'Master the cues and win pool tournaments.', 'Realistic 3D pool and billiards for Europe.', 'Power Play Pool (Europe) offers a precise physics engine for pool fans. Choose between several game modes like 8-ball or 9-ball and compete against AI or friends in a portable billiards experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-play-pool-usa', 'NDS', 'Power Play Pool (USA)', '2007', 'Sports', 'Virtual Play Games', '2', 'Pool', 'Billiards / Sports.', 'Master the cues and win pool tournaments.', 'North American release of the 3D pool game.', 'Take the pool hall with you in Power Play Pool (USA). Use the stylus for fine-tuned aiming and power control as you climb the ranks to become a professional pool shark.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pocket-koushien-japan', 'NDS', 'Power Pocket Koushien (Japan)', '2006', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / Simulation.', 'Lead your high school team to the Koushien finals.', 'High school baseball sim with anime style.', 'Power Pocket Koushien (Japan) focuses on the journey of a student athlete. Manage training schedules, team morale, and play through intense baseball matches to win the national championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-10-japan', 'NDS', 'Power Pro Kun Pocket 10 (Japan)', '2007', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / RPG.', 'Balance professional baseball with a secret-agent life.', 'Quirky baseball-RPG hybrid for Japan.', 'Power Pro Kun Pocket 10 features the series'' signature "Success Mode." Improve your stats on the field while navigating a bizarre and humorous storyline filled with unexpected twists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-11-japan', 'NDS', 'Power Pro Kun Pocket 11 (Japan)', '2008', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / RPG.', 'Defeat rivals on the field and solve the mystery.', 'The 11th entry in the beloved baseball-RPG series.', 'Power Pro Kun Pocket 11 (Japan) offers refined baseball mechanics and a deep RPG mode. Build your player from scratch and make social choices that affect your career and the game''s ending.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-12-japan-ndsi-enhanced', 'NDS', 'Power Pro Kun Pocket 12 (Japan) (NDSi Enhanced)', '2009', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / RPG.', 'Win the league and utilize NDSi enhancements.', 'NDSi Enhanced baseball and story adventure.', 'Power Pro Kun Pocket 12 (Japan) takes advantage of the NDSi hardware for smoother performance. It features an expanded Success Mode and more complex baseball strategies for veteran fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-13-japan-ndsi-enhanced', 'NDS', 'Power Pro Kun Pocket 13 (Japan) (NDSi Enhanced)', '2010', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / RPG.', 'Become a baseball legend in this final DS entry.', 'The 13th installment with NDSi features.', 'Power Pro Kun Pocket 13 (Japan) is a content-packed baseball sim. Engage in high-stakes matches and a sci-fi influenced story mode that pushed the DS hardware to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-8-japan', 'NDS', 'Power Pro Kun Pocket 8 (Japan)', '2005', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / RPG.', 'Start your career and lead your team to victory.', 'The 8th chapter of the Power Pro pocket series.', 'Power Pro Kun Pocket 8 (Japan) established many core mechanics of the franchise. It blends realistic baseball physics with a visual novel-style story mode that is both funny and engaging.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-pro-kun-pocket-9-japan', 'NDS', 'Power Pro Kun Pocket 9 (Japan)', '2006', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / RPG.', 'Compete at the highest level and uncover secrets.', 'The 9th entry in the Japanese baseball franchise.', 'Power Pro Kun Pocket 9 (Japan) continues the tradition of deep player customization. Train hard, manage your social life, and play top-tier baseball in this classic portable sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---samurai-europe-enfrdeesit', 'NDS', 'Power Rangers - Samurai (Europe) (En,Fr,De,Es,It)', '2011', 'Action', 'Now Production', '4', 'Action Fighting', 'Action / Beat ''em up.', 'Master the Samurai symbols to defeat the Nighloks.', 'European release of the Power Rangers action game.', 'Power Rangers: Samurai (Europe) lets you control the legendary team. Use the stylus to draw Kanji symbols and activate special attacks in this multi-language action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---samurai-usa-enfres', 'NDS', 'Power Rangers - Samurai (USA) (En,Fr,Es)', '2011', 'Action', 'Now Production', '4', 'Action Fighting', 'Action / Beat ''em up.', 'Master the Samurai symbols to defeat the Nighloks.', 'North American release of Power Rangers Samurai.', 'Go Go Power Rangers! In Power Rangers: Samurai (USA), you can switch between rangers, pilot the Megazord, and save the city from Master Xandred''s forces in a series of fast-paced levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---super-legends-europe-enfrdeesit', 'NDS', 'Power Rangers - Super Legends (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Hybrid Productions', '4', 'Action Fighting', 'Action / Platformer.', 'Battle through time to save the Ranger legacy.', '15th anniversary crossover action game.', 'Power Rangers: Super Legends (Europe) features heroes from various seasons. Engage in 2D side-scrolling combat and use powerful combos to defeat the minions of Lord Zedd.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-rangers---super-legends-usa-enfrdeesit', 'NDS', 'Power Rangers - Super Legends (USA) (En,Fr,De,Es,It)', '2007', 'Action', 'Hybrid Productions', '4', 'Action Fighting', 'Action / Platformer.', 'Battle through time to save the Ranger legacy.', 'North American crossover action-adventure.', 'Celebrate Ranger history in Power Rangers: Super Legends (USA). Team up with a friend via local wireless and fight through iconic locations to preserve the legend of the Power Rangers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerbike-usa', 'NDS', 'Powerbike (USA)', '2003', 'Racing', 'Apogee Software', '1', 'Motorcycle Racing', 'Racing / Stunt.', 'Perform dangerous stunts and win urban races.', 'High-speed motorcycle stunt racing.', 'Powerbike (USA) focuses on gravity-defying tricks. Use the stylus to balance your bike mid-air and race through challenging tracks filled with obstacles and massive jumps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerful-pro-yagu-begins-korea', 'NDS', 'Powerful Pro-yagu Begins (Korea)', '2009', 'Sports', 'Konami', '1', 'Baseball', 'Baseball / Sports.', 'Win the professional Korean baseball league.', 'Korean localized version of the Power Pro series.', 'Powerful Pro-yagu Begins brings the famous "big-head" baseball players to Korea. Enjoy the realistic physics and deep management modes fully localized for the Korean market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerplay-tennis-usa', 'NDS', 'Powerplay Tennis (USA)', '2002', 'Sports', 'Camelot Software Planning', '2', 'Tennis', 'Tennis / Sports.', 'Win the grand slam tournaments with precision.', 'Accessible and fast-paced tennis simulation.', 'Powerplay Tennis (USA) offers intuitive touch-screen controls. Aim your shots and time your swings to outmaneuver opponents on grass, clay, and hard courts in various tournament modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerquiz---allgemeinbildung-germany', 'NDS', 'PowerQuiz - Allgemeinbildung (Germany)', '2008', 'Quiz', 'PowerQuiz', '1', 'Trivia', 'Trivia / Educational.', 'Test your general knowledge across various topics.', 'German-language general knowledge quiz.', 'PowerQuiz: Allgemeinbildung (Germany) features thousands of questions on history, science, and pop culture. Track your "IQ" score and compete with friends to see who is the smartest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powerquiz---die-sport-edition-germany', 'NDS', 'PowerQuiz - Die Sport-Edition (Germany)', '2009', 'Quiz', 'PowerQuiz', '1', 'Trivia', 'Trivia / Sports.', 'Prove you are the ultimate sports expert.', 'German-language sports trivia challenge.', 'PowerQuiz: Die Sport-Edition (Germany) focuses on everything from football to athletics. Perfect for sports fans, this quiz game tests your knowledge of records, players, and historical moments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('powershot-pinball-constructor-europe-enfrdeesit', 'NDS', 'Powershot Pinball Constructor (Europe) (En,Fr,De,Es,It)', '2006', 'Pinball', 'Digital Illusions', '1', 'Pinball', 'Pinball / Creative.', 'Build your own pinball tables and play them.', 'Pinball simulator with a powerful editor.', 'Powershot Pinball Constructor (Europe) allows you to design your dream table. Place bumpers, ramps, and traps, then test your creation with a realistic physics engine in multiple languages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ppiyodamari-ds-korea', 'NDS', 'Ppiyodamari DS (Korea)', '2008', 'Puzzle', 'Game Life', '1', 'Puzzle', 'Virtual Pet / Puzzle.', 'Care for the cute Ppiyodamari chicks.', 'Heartwarming Korean virtual pet and mini-game collection.', 'Ppiyodamari DS (Korea) features the adorable round chicks. Feed them, play with them, and complete simple puzzles in this relaxing game based on the popular Korean characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('practise-english!-europe-frdeesit', 'NDS', 'Practise English! (Europe) (Fr,De,Es,It)', '2007', 'Educational', 'Europress', '1', 'Language Learning', 'Educational / Language.', 'Improve your English skills with daily exercises.', 'English language trainer for European speakers.', 'Practise English! (Europe) focuses on real-world scenarios. Use the stylus and microphone to improve your listening, speaking, and writing skills through interactive drills and games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('press-your-luck---2010-edition-usa', 'NDS', 'Press Your Luck - 2010 Edition (USA)', '2010', 'Game Show', 'Ludia', '4', 'Game Show', 'Game Show / Trivia.', 'Spin the wheel and avoid the "Whammy."', 'Digital version of the classic TV game show.', 'Press Your Luck - 2010 Edition (USA) captures the tension of the show. Answer trivia questions to earn spins and try to win big without landing on the dreaded red Whammy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prey-the-stars---gabu-gabu-planet-europe-enfrdeesit', 'NDS', 'Prey the Stars - Gabu Gabu Planet (Europe) (En,Fr,De,Es,It)', '2008', 'Puzzle', 'Pandora Interactive', '4', 'Action Puzzle', 'Action / Puzzle.', 'Eat everything in sight to grow larger and win.', 'Quirky "eating" competition game for Europe.', 'Prey the Stars: Gabu Gabu Planet (Europe) is a competitive eating game. Customize your monster and swallow entire buildings to outscore your rivals in this colorful and chaotic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prey-the-stars-usa', 'NDS', 'Prey the Stars (USA)', '2008', 'Puzzle', 'Pandora Interactive', '4', 'Action Puzzle', 'Action / Puzzle.', 'Eat everything in sight to grow larger and win.', 'North American release of the Gabu Gabu eating contest.', 'Devour the world in Prey the Stars (USA). Use the touch screen to gobble up items, complete missions, and battle other hungry monsters in a race for total consumption.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('price-is-right-the---2010-edition-usa-enfr', 'NDS', 'Price Is Right, The - 2010 Edition (USA) (En,Fr)', '2010', 'Game Show', 'Ludia', '4', 'Game Show', 'Game Show / Trivia.', 'Guess the prices and reach the Showcase Showdown.', '2010 edition of the iconic pricing game show.', 'The Price Is Right: 2010 Edition (USA) features updated graphics and games. Play "Plinko," "Cliff Hangers," and more in a faithful recreation of the longest-running game show in history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('price-is-right-the-usa-enfr', 'NDS', 'Price Is Right, The (USA) (En,Fr)', '2007', 'Game Show', 'Ludia', '4', 'Game Show', 'Game Show / Trivia.', 'Guess the prices and reach the Showcase Showdown.', 'The classic DS version of the popular game show.', 'Come on down! The Price Is Right (USA) lets you experience the thrill of the show. Test your shopping knowledge and try your luck on the Big Wheel in this fun, family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia---the-fallen-king-europe-enfrdeesit', 'NDS', 'Prince of Persia - The Fallen King (Europe) (En,Fr,De,Es,It)', '2008', 'Action-Adventure', 'Ubisoft', '1', 'Action Platformer', 'Action-Adventure / Platformer.', 'Restore the land and defeat the dark Corrupted.', 'Stylus-controlled adventure based on the 2008 reboot.', 'Prince of Persia: The Fallen King (Europe) uses a unique control scheme. Every movement and sword strike is performed with the stylus as the Prince seeks to save a dying kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia---the-fallen-king-usa-enfrdeesit', 'NDS', 'Prince of Persia - The Fallen King (USA) (En,Fr,De,Es,It)', '2008', 'Action-Adventure', 'Ubisoft', '1', 'Action Platformer', 'Action-Adventure / Platformer.', 'Restore the land and defeat the dark Corrupted.', 'North American stylus-based Prince of Persia.', 'Guide the Prince through dangerous traps and combat in The Fallen King (USA). Use the DS touch screen to cast magical powers and navigate complex platforming segments in this 2D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia---the-forgotten-sands-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Prince of Persia - The Forgotten Sands (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Action-Adventure', 'Ubisoft', '1', 'Action Platformer', 'Action / Platformer.', 'Master the sands of time to defeat an ancient evil.', 'NDSi Enhanced adventure for the European market.', 'Prince of Persia: The Forgotten Sands (Europe) features side-scrolling action and puzzle-solving. Use the NDSi camera to unlock secret items and master elemental powers to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia---the-forgotten-sands-usa-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Prince of Persia - The Forgotten Sands (USA) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Action-Adventure', 'Ubisoft', '1', 'Action Platformer', 'Action / Platformer.', 'Master the sands of time to defeat an ancient evil.', 'North American NDSi Enhanced platformer.', 'Experience the Sands of Time saga on DS in The Forgotten Sands (USA). Featuring fluid combat and the ability to rewind time, it''s a dedicated handheld adventure that complements the console releases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-and-the-frog-the-europe-enfrdeesitnl', 'NDS', 'Princess and the Frog, The (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Platformer', 'Glu Mobile', '1', 'Platformer', 'Adventure / Mini-games.', 'Help Tiana open her restaurant in New Orleans.', 'Disney movie tie-in with music and cooking games.', 'The Princess and the Frog (Europe) follows the film''s plot. Engage in rhythm-based jazz games, cook delicious recipes, and explore the bayou in this charming and colorful adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-and-the-frog-the-usa-enfres', 'NDS', 'Princess and the Frog, The (USA) (En,Fr,Es)', '2009', 'Platformer', 'Glu Mobile', '1', 'Platformer', 'Adventure / Mini-games.', 'Help Tiana open her restaurant in New Orleans.', 'North American release of the Disney adventure.', 'Step into the world of Princess Tiana in The Princess and the Frog (USA). Use the stylus to dance, cook, and navigate through 25 different mini-games inspired by the hit animated movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-angel---baeguiui-cheonsa-korea', 'NDS', 'Princess Angel - Baeguiui Cheonsa (Korea)', '2005', 'Simulation', 'Storyline', '1', 'Life Simulation', 'Life simulation & RPG.', 'Train your princess to become the ultimate lady.', 'Korean life simulation for aspiring princesses.', 'Princess Angel (Korea) tasks you with managing a young girl''s schedule. Balance her education, social life, and etiquette training to ensure she grows up to be a refined and successful princess.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-bakery-korea', 'NDS', 'Princess Bakery (Korea)', '2006', 'Simulation', 'Storyline', '1', 'Cooking Simulation', 'Cooking & Management sim.', 'Run a bakery and bake delicious princess-themed treats.', 'Adorable bakery management game for Korea.', 'Princess Bakery (Korea) lets you manage your own dessert shop. Use the touch screen to knead dough, decorate cakes, and serve customers to become the most famous baker in the kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-ballerina---yumemiru-4-nin-no-prima-donna-japan', 'NDS', 'Princess Ballerina - Yumemiru 4-nin no Prima Donna (Japan)', '2006', 'Adventure', 'Nippon Columbia', '1', 'Adventure', 'Rhythm & Dancing.', 'Master ballet moves and win the grand performance.', 'Ballet-themed rhythm game from Japan.', 'Princess Ballerina (Japan) features four girls dreaming of becoming prima donnas. Follow the rhythm using the stylus to perform elegant spins and jumps in a series of competitive dance recitals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-debut---the-royal-ball-europe-enfrde', 'NDS', 'Princess Debut - The Royal Ball (Europe) (En,Fr,De)', '2008', 'Adventure', 'Storyline', '1', 'Adventure', 'Rhythm & Visual Novel.', 'Find your prince and win the dance competition.', 'Romantic rhythm adventure for Europe.', 'Princess Debut (Europe) blends otome romance with dancing. Travel to a magical kingdom, choose your dance partner, and practice your steps using the touch screen to win the Royal Ball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-debut-usa', 'NDS', 'Princess Debut (USA)', '2008', 'Adventure', 'Storyline', '1', 'Adventure', 'Rhythm & Visual Novel.', 'Find your prince and win the dance competition.', 'North American release of the princess rhythm sim.', 'In Princess Debut (USA), you have 30 days to train for the ball. Interact with handsome princes and master fluid dance mechanics in this charming hybrid of social sim and rhythm game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-in-love-europe-enfrdeesit', 'NDS', 'Princess in Love (Europe) (En,Fr,De,Es,It)', '2006', 'Visual Novel', 'Wolf Team', '1', 'Romance', 'Life simulation & Mini-games.', 'Find love and manage your royal social life.', 'Romance and lifestyle simulation for Europe.', 'Princess in Love (Europe) follows a princess looking for her true match. Participate in royal events, choose your fashion, and complete mini-games to win the heart of your favorite suitor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-in-love-usa-enfrdeesit', 'NDS', 'Princess in Love (USA) (En,Fr,De,Es,It)', '2006', 'Visual Novel', 'Wolf Team', '1', 'Romance', 'Life simulation & Mini-games.', 'Find love and manage your royal social life.', 'North American release of the princess romance sim.', 'Experience the trials of royal romance in Princess in Love (USA). Navigate a branching story where your choices and success in mini-games determine which prince you''ll end up with.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-isabella---witchs-curse-europe', 'NDS', 'Princess Isabella - Witch''s Curse (Europe)', '2010', 'Adventure', 'Gogii Games', '1', 'Hidden Object', 'Hidden Object Puzzle.', 'Break the witch''s curse and save the kingdom.', 'Supernatural hidden object adventure for Europe.', 'Princess Isabella: Witch''s Curse features challenging puzzles and eerie environments. Search for hidden items and solve brain-teasers to banish the evil witch and restore your castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-maker-4---special-edition-japan', 'NDS', 'Princess Maker 4 - Special Edition (Japan)', '2005', 'Simulation', 'Gainax', '1', 'Life Simulation', 'Life simulation & RPG.', 'Raise a young girl from childhood to adulthood.', 'Enhanced edition of the classic life simulator.', 'Princess Maker 4: Special Edition (Japan) offers deep stat management. Every choice you make regarding her education and work affects her personality and leads to dozens of different endings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-maker-4---special-edition-korea', 'NDS', 'Princess Maker 4 - Special Edition (Korea)', '2005', 'Simulation', 'Gainax', '1', 'Life Simulation', 'Life simulation & RPG.', 'Raise a young girl from childhood to adulthood.', 'Korean localization of the iconic life sim.', 'Experience the depth of Princess Maker 4 in Korea. Guide your daughter through the joys and struggles of life, managing her health and skills to determine her destiny in this Special Edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-melody-europe-enfrdeitnl', 'NDS', 'Princess Melody (Europe) (En,Fr,De,It,Nl)', '2006', 'Music', 'Game Life', '1', 'Music Rhythm', 'Music & Rhythm.', 'Perform beautiful melodies and become a star.', 'Music-focused rhythm game for Europe.', 'Princess Melody (Europe) lets you play various instruments using the DS stylus. Follow the beat to unlock new songs and outfits, aiming for a perfect performance in every royal concert.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-natasha---student-secret-agent-princess-europe-enfrdeesit', 'NDS', 'Princess Natasha - Student, Secret Agent, Princess (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Neko Entertainment', '1', 'Adventure', 'Action-adventure & Stealth.', 'Balance school life with secret agent missions.', 'Dual-life adventure based on the cartoon.', 'Princess Natasha (Europe) features two distinct gameplay styles. Complete stealth missions for the kingdom of Zoravia while maintaining your cover as an ordinary high school student.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-natasha---student-secret-agent-princess-usa', 'NDS', 'Princess Natasha - Student, Secret Agent, Princess (USA)', '2008', 'Adventure', 'Neko Entertainment', '1', 'Adventure', 'Action-adventure & Stealth.', 'Balance school life with secret agent missions.', 'North American release of the Natasha adventure.', 'Use high-tech gadgets and combat skills in Princess Natasha (USA). Navigate platforming levels to stop villains and return home in time to pass your classes in this quirky action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-on-ice-europe-enfrdeesit', 'NDS', 'Princess on Ice (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', 'Game Life', '2', 'Figure Skating', 'Rhythm & Figure Skating.', 'Win the figure skating championship with grace.', 'Ice skating rhythm simulation for Europe.', 'Princess on Ice (Europe) uses the touch screen to execute complex skating routines. Choose from multiple characters and costumes to impress the judges and win the gold medal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-on-ice-japan', 'NDS', 'Princess on Ice (Japan)', '2008', 'Sports', 'Game Life', '2', 'Figure Skating', 'Rhythm & Figure Skating.', 'Win the figure skating championship with grace.', 'Japanese release of the figure skating sim.', 'Experience the elegance of "Princess on Ice" in Japan. Master the timing of your jumps and spins to the beat of the music in this colorful and competitive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('princess-on-ice-usa-enfres', 'NDS', 'Princess on Ice (USA) (En,Fr,Es)', '2008', 'Sports', 'Game Life', '2', 'Figure Skating', 'Rhythm & Figure Skating.', 'Win the figure skating championship with grace.', 'North American release of the skating game.', 'Glide to victory in Princess on Ice (USA). Featuring a variety of tracks and customizable outfits, it’s a perfect mix of rhythm-action and sports simulation for the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prinses-lillifee-europe-frdenl', 'NDS', 'Prinses Lillifee (Europe) (Fr,De,Nl)', '2009', 'Adventure', 'Flashpoint', '1', 'Adventure', 'Adventure & Mini-games.', 'Help Princess Lillifee with her magical tasks.', 'Multilingual adventure based on the German books.', 'Prinses Lillifee (Europe) invites kids to explore a magical world. Complete creative mini-games and puzzles designed to encourage kindness and imagination in a colorful, friendly setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prinzessin-lillifee---feenzauber-germany', 'NDS', 'Prinzessin Lillifee - Feenzauber (Germany)', '2009', 'Adventure', 'Flashpoint', '1', 'Adventure', 'Adventure & Mini-games.', 'Use fairy magic to solve problems in the garden.', 'Magical fairy adventure for the German market.', 'Prinzessin Lillifee: Feenzauber (Germany) lets you help your forest friends. Use your magic wand to cast spells, fly through beautiful levels, and organize the ultimate garden party.');